# self-attest that it uses the real, defined constants of nature -- not approximations.
PHYSICS_CONSTANTS = {
    # Speed of light in vacuum (exact, defined -- SI 2019): m/s
    "c": 299792458.0,
    # Newtonian gravitational constant (CODATA 2018): m^3/(kg*s^2)
    "G": 6.67430e-11,
    # Earth mass (best estimate): kg
    "M_earth": 5.972168e24,
    # WGS-84 reference ellipsoid (defined, NIMA 1997 / DoD):
    #   semi-major axis (equatorial radius): m
    "WGS84_a": 6378137.0,
    #   inverse flattening (1/f, dimensionless)
    "WGS84_inv_f": 298.257223563,
    #   derived semi-minor axis (polar radius): m  = a*(1 - 1/inv_f)
    #   derived first eccentricity squared e^2 = f*(2 - f)
    #   mean radius (R1) for spherical fallback: m
    "WGS84_b": 6378137.0 * (1.0 - 1.0 / 298.257223563),
    "WGS84_e2": (1.0 / 298.257223563) * (2.0 - 1.0 / 298.257223563),
    "R_earth_mean": 6371000.0,        # spherical-Earth fallback (kept for back-compat)
    # Standard gravitational parameter for Earth: m^3/s^2  (GM)
    "mu_earth": 3.986004418e14,
    # GPS L1 reference downlink (MHz) -- for relativistic Doppler magnitude reference
    "gps_l1_mhz": 1575.42,
    # Textbook net GPS clock advance (Ashby 2003): us/day -- SR+GR self-check target
    "gps_expected_us_day": 38.6,
}
# Convenience single-letter aliases (exact, defined values).
C_LIGHT = PHYSICS_CONSTANTS["c"]              # 299792458.0 m/s -- use this everywhere
G_NEWTON = PHYSICS_CONSTANTS["G"]
M_EARTH = PHYSICS_CONSTANTS["M_earth"]
MU_EARTH = PHYSICS_CONSTANTS["mu_earth"]
WGS84_A = PHYSICS_CONSTANTS["WGS84_a"]
WGS84_B = PHYSICS_CONSTANTS["WGS84_b"]
WGS84_E2 = PHYSICS_CONSTANTS["WGS84_e2"]
R_EARTH_MEAN = PHYSICS_CONSTANTS["R_earth_mean"]


def wgs84_lla_to_ecef(lat_deg, lon_deg, alt_m):
    """Convert geodetic (WGS-84) lat/lon/alt to ECEF (Earth-Centered Earth-Fixed) XYZ.

    Args:
        lat_deg, lon_deg: geodetic latitude/longitude in degrees (WGS-84).
        alt_m: ellipsoidal height in metres (above the WGS-84 ellipsoid).
    Returns:
        (x, y, z) ECEF coordinates in metres. Exact WGS-84 ellipsoid math
        (no spherical approximation) -- the true-scale geocentric position.
    """
    import math as _m
    lat = _m.radians(float(lat_deg)); lon = _m.radians(float(lon_deg))
    a = WGS84_A; e2 = WGS84_E2
    sinlat = _m.sin(lat); coslat = _m.cos(lat)
    # Prime vertical radius of curvature: N = a / sqrt(1 - e^2 sin^2 lat)
    N = a / _m.sqrt(max(1e-30, 1.0 - e2 * sinlat * sinlat))
    x = (N + alt_m) * coslat * _m.cos(lon)
    y = (N + alt_m) * coslat * _m.sin(lon)
    z = (N * (1.0 - e2) + alt_m) * sinlat
    return (x, y, z)


def wgs84_ecef_to_enu(x, y, z, ref_lat_deg, ref_lon_deg, ref_alt_m):
    """Convert ECEF to local ENU (East/North/Up) about a reference geodetic point.

    Returns (east_m, north_m, up_m) -- true-scale local Cartesian metres relative
    to the reference, on the WGS-84 ellipsoid (not a spherical approximation).
    This is the standard survey-grade local-frame transform: the tangent plane at
    the reference point, X=East, Y=North, Z=Up.
    """
    import math as _m
    rx, ry, rz = wgs84_lla_to_ecef(ref_lat_deg, ref_lon_deg, ref_alt_m)
    dx = x - rx; dy = y - ry; dz = z - rz
    lat = _m.radians(float(ref_lat_deg)); lon = _m.radians(float(ref_lon_deg))
    sinlat = _m.sin(lat); coslat = _m.cos(lat); sinlon = _m.sin(lon); coslon = _m.cos(lon)
    # ENU rotation matrix (ECEF -> ENU):
    #   E = -sinlon      * dx + coslon       * dy
    #   N = -sinlat*coslon*dx - sinlat*sinlon*dy + coslat*dz
    #   U =  coslat*coslon*dx + coslat*sinlon*dy + sinlat*dz
    east  = -sinlon * dx + coslon * dy
    north = -sinlat * coslon * dx - sinlat * sinlon * dy + coslat * dz
    up    =  coslat * coslon * dx + coslat * sinlon * dy + sinlat * dz
    return (east, north, up)


def wgs84_lla_to_enu(lat_deg, lon_deg, alt_m, ref_lat_deg, ref_lon_deg, ref_alt_m):
    """One-shot geodetic LLA -> local ENU metres (WGS-84 ellipsoid, true-scale)."""
    x, y, z = wgs84_lla_to_ecef(lat_deg, lon_deg, alt_m)
    return wgs84_ecef_to_enu(x, y, z, ref_lat_deg, ref_lon_deg, ref_alt_m)


def wgs84_geodetic_curvature_radius(lat_deg):
    """Prime-vertical radius of curvature N at a geodetic latitude (WGS-84).
    The exact 'radius' for east-west scale at that latitude."""
    import math as _m
    lat = _m.radians(float(lat_deg))
    sinlat = _m.sin(lat)
    return WGS84_A / _m.sqrt(max(1e-30, 1.0 - WGS84_E2 * sinlat * sinlat))
def wgs84_vincenty_distance(lat1_deg, lon1_deg, lat2_deg, lon2_deg):
    """Vincenty's formula (inverse) for geodesic distance on the WGS-84 ellipsoid.

    Returns the ellipsoidal distance in metres with sub-metre accuracy (vs the
    ~0.3% error of the spherical great-circle approximation). This is the
    survey-grade distance used for the digital twin's geo-referenced objects.
    Falls back to the spherical great-circle if the iteration fails to converge
    (near-antipodal points)."""
    import math as _m
    a = WGS84_A; f = 1.0 / PHYSICS_CONSTANTS["WGS84_inv_f"]; b = WGS84_B
    L = _m.radians(float(lon2_deg) - float(lon1_deg))
    U1 = _m.atan((1 - f) * _m.tan(_m.radians(float(lat1_deg))))
    U2 = _m.atan((1 - f) * _m.tan(_m.radians(float(lat2_deg))))
    sinU1, cosU1 = _m.sin(U1), _m.cos(U1)
    sinU2, cosU2 = _m.sin(U2), _m.cos(U2)
    lam = L
    for _ in range(200):
        sinLam, cosLam = _m.sin(lam), _m.cos(lam)
        sinSigma = _m.sqrt((cosU2 * sinLam) ** 2 +
                           (cosU1 * sinU2 - sinU1 * cosU2 * cosLam) ** 2)
        if sinSigma == 0:
            return 0.0  # coincident points
        cosSigma = sinU1 * sinU2 + cosU1 * cosU2 * cosLam
        sigma = _m.atan2(sinSigma, cosSigma)
        sinAlpha = cosU1 * cosU2 * sinLam / sinSigma
        cos2Alpha = 1 - sinAlpha ** 2
        if cos2Alpha == 0:
            cos2SigmaM = 0.0  # equatorial line
        else:
            cos2SigmaM = cosSigma - 2 * sinU1 * sinU2 / cos2Alpha
        C = f / 16 * cos2Alpha * (4 + f * (4 - 3 * cos2Alpha))
        lamPrev = lam
        lam = L + (1 - C) * f * sinAlpha * (
            sigma + C * sinSigma * (cos2SigmaM + C * cosSigma * (-1 + 2 * cos2SigmaM ** 2)))
        if abs(lam - lamPrev) < 1e-12:
            break
    else:
        # Failed to converge (near-antipodal) -- fall back to spherical
        R = R_EARTH_MEAN
        la1, la2 = _m.radians(float(lat1_deg)), _m.radians(float(lat2_deg))
        dlo = _m.radians(float(lon2_deg) - float(lon1_deg))
        a_s = _m.sin((la2 - la1) / 2) ** 2 + _m.cos(la1) * _m.cos(la2) * _m.sin(dlo / 2) ** 2
        return R * 2 * _m.atan2(_m.sqrt(a_s), _m.sqrt(1 - a_s))
    u2 = cos2Alpha * (a ** 2 - b ** 2) / (b ** 2)
    A = 1 + u2 / 16384 * (4096 + u2 * (-768 + u2 * (320 - 175 * u2)))
    B = u2 / 1024 * (256 + u2 * (-128 + u2 * (74 - 47 * u2)))
    deltaSigma = B * sinSigma * (cos2SigmaM + B / 4 * (
        cosSigma * (-1 + 2 * cos2SigmaM ** 2) -
        B / 6 * cos2SigmaM * (-3 + 4 * sinSigma ** 2) * (-3 + 4 * cos2SigmaM ** 2)))
    s = b * A * (sigma - deltaSigma)
    return float(s)


def wgs84_vincenty_bearing(lat1_deg, lon1_deg, lat2_deg, lon2_deg):
    """Initial geodetic bearing (azimuth, radians, 0=N, clockwise) on WGS-84.
    Uses the same Vincenty iteration as wgs84_vincenty_distance. Falls back to
    the spherical great-circle bearing on non-convergence."""
    import math as _m
    f = 1.0 / PHYSICS_CONSTANTS["WGS84_inv_f"]
    L = _m.radians(float(lon2_deg) - float(lon1_deg))
    U1 = _m.atan((1 - f) * _m.tan(_m.radians(float(lat1_deg))))
    U2 = _m.atan((1 - f) * _m.tan(_m.radians(float(lat2_deg))))
    sinU1, cosU1 = _m.sin(U1), _m.cos(U1)
    sinU2, cosU2 = _m.sin(U2), _m.cos(U2)
    lam = L
    for _ in range(200):
        sinLam, cosLam = _m.sin(lam), _m.cos(lam)
        sinSigma = _m.sqrt((cosU2 * sinLam) ** 2 +
                           (cosU1 * sinU2 - sinU1 * cosU2 * cosLam) ** 2)
        if sinSigma == 0:
            return 0.0
        cosSigma = sinU1 * sinU2 + cosU1 * cosU2 * cosLam
        sigma = _m.atan2(sinSigma, cosSigma)
        sinAlpha = cosU1 * cosU2 * sinLam / sinSigma
        cos2Alpha = 1 - sinAlpha ** 2
        cos2SigmaM = (cosSigma - 2 * sinU1 * sinU2 / cos2Alpha) if cos2Alpha != 0 else 0.0
        C = f / 16 * cos2Alpha * (4 + f * (4 - 3 * cos2Alpha))
        lamPrev = lam
        lam = L + (1 - C) * f * sinAlpha * (
            sigma + C * sinSigma * (cos2SigmaM + C * cosSigma * (-1 + 2 * cos2SigmaM ** 2)))
        if abs(lam - lamPrev) < 1e-12:
            break
    else:
        # Spherical fallback
        la1, la2 = _m.radians(float(lat1_deg)), _m.radians(float(lat2_deg))
        dlo = _m.radians(float(lon2_deg) - float(lon1_deg))
        return _m.atan2(_m.sin(dlo) * _m.cos(la2),
                        _m.cos(la1) * _m.sin(la2) - _m.sin(la1) * _m.cos(la2) * _m.cos(dlo))
    # Forward azimuth from the Vincenty iteration
    alpha1 = _m.atan2(cosU2 * sinLam, cosU1 * sinU2 - sinU1 * cosU2 * cosLam)
    return float(alpha1)


def wgs84_geodesic(lat1_deg, lon1_deg, lat2_deg, lon2_deg):
    """One-shot (distance_m, bearing_rad) on the WGS-84 ellipsoid.
    The accurate companion to the spherical _great_circle -- use this where
    sub-metre geo accuracy matters for the digital twin."""
    return (wgs84_vincenty_distance(lat1_deg, lon1_deg, lat2_deg, lon2_deg),
            wgs84_vincenty_bearing(lat1_deg, lon1_deg, lat2_deg, lon2_deg))


def relativistic_doppler_factor(beta_radial):
    """Full special-relativity Doppler factor for a radial velocity fraction beta.

    beta_radial > 0 = receding (redshift, observed frequency LOWER).
    Returns f_obs / f_src = sqrt((1 - beta) / (1 + beta))  -- the EXACT SR formula.
    This is the relativistically-correct form; the first-order approximation
    (1 - beta) is recovered for |beta| << 1. Clamped to avoid div-by-zero.
    """
    b = max(-0.999999999999, min(0.999999999999, float(beta_radial)))
    return ((1.0 - b) / (1.0 + b)) ** 0.5


def relativistic_doppler_shift_hz(f_src_hz, beta_radial):
    """Observed frequency (Hz) given source frequency and radial beta (receding > 0)."""
    return float(f_src_hz) * relativistic_doppler_factor(beta_radial)
def relativistic_doppler_velocity(doppler_hz, f_src_hz):
    """Exact inversion of the SR Doppler formula: radial velocity from measured shift.

    Given a measured Doppler shift (Hz, positive = blueshift/approaching) and the
    source frequency (Hz), returns the radial velocity (m/s, positive = approaching).
    This is the relativistically-exact inversion of relativistic_doppler_shift_hz:
        f_obs = f_src * sqrt((1-beta)/(1+beta))   (receding beta > 0)
        => beta = (f_src^2 - f_obs^2) / (f_src^2 + f_obs^2)
        => v   = c * beta
    For |doppler| << f_src this reduces to the classical v = -doppler*c/f (the
    sign convention: positive doppler_hz = approaching = negative beta_radial).
    """
    f_src = float(f_src_hz)
    df = float(doppler_hz)
    if f_src <= 0:
        return 0.0
    f_obs = f_src + df
    if f_obs <= 0:
        return 0.0
    beta = (f_src * f_src - f_obs * f_obs) / (f_src * f_src + f_obs * f_obs)
    # beta > 0 = receding; positive doppler (blueshift) = approaching = negative beta
    # Our convention: return positive v for approaching (blueshift).
    return -C_LIGHT * beta


def bistatic_range_res_m(bw_hz):
    """Physics-bounded range resolution for a round-trip (radar/SAR) signal: dR = c/(2*BW).
    Returns metres. This is the FUNDAMENTAL limit -- no feature smaller than this
    can be resolved by a real radar of bandwidth BW. Used to gate the voxel grid
    so the digital twin is never drawn finer than the instruments can actually see
    (no fabricated super-resolution)."""
    bw = float(bw_hz)
    if bw <= 0:
        return 0.0
    return C_LIGHT / (2.0 * bw)


def oneway_tof_range_res_m(bw_hz):
    """One-way time-of-flight range resolution (CSI ToF, passive): dR = c/BW.
    Distinct from the bistatic round-trip c/(2*BW) -- a one-way photon travels
    the path once, so the unambiguous range bin is c/BW. Both are physically
    correct in their respective contexts."""
    bw = float(bw_hz)
    if bw <= 0:
        return 0.0
    return C_LIGHT / bw


def best_available_range_res_m(illuminators=None):
    """The finest range resolution available from the best-bandwidth illuminator
    in the active set. This is the 'best vision clarity' scale: the Nyquist voxel
    size the digital twin should adopt so it shows everything the instruments can
    resolve -- no coarser (would lose real detail), no finer (would fabricate).
    Returns metres. Falls back to the WiFi 5 GHz 80 MHz c/(2*BW) = 1.875 m if no
    illuminators are specified."""
    bw_best = 0.0
    illums = illuminators if illuminators else RF_ILLUMINATORS
    try:
        for _name, cfg in (illums or {}).items():
            bw = float(cfg.get("bw_hz", 0.0) or 0.0)
            if bw > bw_best:
                bw_best = bw
    except Exception:
        bw_best = 0.0
    if bw_best <= 0:
        bw_best = 80e6  # WiFi 5 GHz 80 MHz fallback
    return bistatic_range_res_m(bw_best)


# ===================================================
# ── TrueView3D true-linear-scale mode (v300++++) ────────────────────────────
# When TRUE, the TrueView3D dome renders range as LINEAR distance (litres to-scale)
# instead of the default log10 compression. The log view is the readable default
# (it fits 1 m .. 1000+ km on one dome); the linear view is the literal 100%-scale
# companion the user asked for. Flip via the config below or at runtime.
TRUEVIEW_LINEAR_SCALE = False          # default: log-depth (readable across 7 decades)
TRUEVIEW_LINEAR_MAX_M = 1_000_000.0    # 1000 km maps to RMAX in linear mode


def _tv_range_to_display(d_m, RMAX, linear=None):
    """Map a real range (metres) to the TrueView3D display coordinate.

    Default (linear=None -> uses TRUEVIEW_LINEAR_SCALE): log10(d_m) clamped to
    [0, RMAX] -- the existing readable log-depth that fits 1 m .. 10^RMAX m on the
    dome. When linear mode is active: d_m / TRUEVIEW_LINEAR_MAX_M * RMAX, clamped
    to [0, RMAX] -- a LITERAL linear scale where screen distance is proportional
    to real distance (100% to-scale). Both are honest; linear is the literal one.
    """
    import math as _m
    lin = bool(TRUEVIEW_LINEAR_SCALE if linear is None else linear)
    d = max(0.0, float(d_m))
    if lin:
        return max(0.0, min(float(RMAX), d / TRUEVIEW_LINEAR_MAX_M * float(RMAX)))
    return max(0.0, min(float(RMAX), _m.log10(max(1.0, d))))


# ===================================================
# ── Adaptive voxel grid (v300++++) -- 'best vision clarity' scale ───────────
# Recompute VOXEL_RES and M_PER_VOXEL from the finest range resolution the active
# RF illuminators can actually resolve (the physics Nyquist scale: dR = c/(2*BW)
# of the best bandwidth), bounded for performance. The digital twin then shows
# everything the instruments can see -- no coarser (would lose real detail), no
# finer than the physics limit (would fabricate super-resolution). Runs at import
# time, after RF_ILLUMINATORS and best_available_range_res_m are defined.
try:
    _BEST_RR_M = best_available_range_res_m(RF_ILLUMINATORS)   # c/(2*BW) of best BW
    # 'Best vision clarity': use the FINER of the physics Nyquist limit and the
    # original 0.25 m visualization scale. Oversampling below the physics limit
    # is honest (smooth interpolation for display, NOT fabricated super-resolution
    # -- the physics limit is recorded in VOXEL_PHYSICS_RES_M for UI honesty).
    # Going coarser than 0.25 m would lose the original room-scale detail.
    # Bounded to [0.05 m, 0.25 m] for memory (0.05 m -> 160 cells -> capped 128).
    _OPTIMAL_VOXEL_M = max(0.05, min(0.25, min(_BEST_RR_M, 0.25)))
    _opt_res = int(round(SCENE_RANGE_M / _OPTIMAL_VOXEL_M))
    VOXEL_RES = max(16, min(128, _opt_res))
    M_PER_VOXEL = SCENE_RANGE_M / VOXEL_RES
    VOXEL_PHYSICS_RES_M = _BEST_RR_M   # the physics Nyquist limit (for UI honesty)
except Exception:
    VOXEL_PHYSICS_RES_M = M_PER_VOXEL  # fallback: no adaptive info

# ===================================================
# ── Disciplined time: GNSS > NTP > wall clock (v300+++) ────────────────────
# The digital twin's time base: prefer GNSS-disciplined time (centimetre-accurate
# + nanosecond-accurate when a GNSS receiver is present), then NTP-synced time
# (millisecond-accurate when pool.ntp.org is reachable), then wall-clock
# time.time() as the last resort. The source is ALWAYS reported so downstream
# code and UI can distinguish real disciplined time from undisciplined wall clock.
# This is the honest time base for the digital twin -- no silent fallback to 0.0.

# Module-level registry of the current GNSS fix (updated by GPSDClient when a
# GNSS receiver is active). Holds the GNSS time string from the TPV report.
_GNSS_FIX_REGISTRY = {"time_str": "", "epoch_s": None, "last_update": 0.0}


def register_gnss_time(time_str, epoch_s=None):
    """Called by GPSDClient when a TPV report arrives with a GNSS time string.
    Stores the GNSS-disciplined time for true_time() to use."""
    import time as _t
    _GNSS_FIX_REGISTRY["time_str"] = str(time_str or "")
    _GNSS_FIX_REGISTRY["epoch_s"] = float(epoch_s) if epoch_s is not None else _t.time()
    _GNSS_FIX_REGISTRY["last_update"] = _t.time()


def true_time():
    """Return (epoch_s, source_str) for the digital twin's time base.

    Preference order:
      1. GNSS-disciplined time (if a GNSS fix was received within the last 10s)
      2. NTP-corrected time (if check_ntp_sync returned a non-None offset)
      3. Wall-clock time.time() (always available, undisciplined)
    source_str is one of 'GNSS' | 'NTP' | 'WALLCLOCK' -- always reported honestly.
    """
    import time as _t
    now = _t.time()
    # 1. GNSS (fresh within 10s)
    if _GNSS_FIX_REGISTRY["epoch_s"] is not None:
        age = now - _GNSS_FIX_REGISTRY["last_update"]
        if age < 10.0:
            return _GNSS_FIX_REGISTRY["epoch_s"], "GNSS"
    # 2. NTP (if the NetworkDiscoveryEngine has a non-None offset)
    # The NTP offset is stored in the NetworkDiscoveryEngine instance; we check
    # a module-level proxy that the engine updates. If no engine has registered,
    # we fall through to wall clock.
    ntp_offset = _NTP_OFFSET_PROXY.get("offset_s")
    if ntp_offset is not None:
        return now + ntp_offset, "NTP"
    # 3. Wall clock (undisciplined)
    return now, "WALLCLOCK"


def register_ntp_offset(offset_s):
    """Called by NetworkDiscoveryEngine.check_ntp_sync when NTP responds.
    offset_s is the NTP clock offset in seconds (None = unknown/not synced)."""
    _NTP_OFFSET_PROXY["offset_s"] = offset_s


_NTP_OFFSET_PROXY = {"offset_s": None}


