# ════════════ PASS 25: GROUND-TRUTH SCENE + RF SYNTHESIS + ACCURACY ════════════

class GroundTruthScene:
    """Pass 25: The "filler / pseudo-data that represents reality" with KNOWN positions.

    This is the physical ground truth the 3D reconstruction is validated against. Each
    target is a person (or object) with a known world position (x,y,z in metres), known
    vitals (HR, BR), and a known gait. The scene:
      • evolves the targets over time (breathing, slow walking, lateral drift),
      • synthesises the multi-illuminator RF return they would produce (WiFi CSI +
        passive cell-tower + SDR + FMCW range-Doppler), and
      • exposes the known target list so ReconstructionAccuracy can score how closely
        the rendered voxel matrix matches the truth.

    When the reconstruction matches every target's position + vitals, accuracy → 100 %
    and the 3-D matrix is declared validated/accurate.

    World coordinate convention (matches the voxel grid used by detect_voxel_blobs):
        x  = lateral   (0 … SCENE_RANGE_M)   → voxel axis 0
        y  = range/depth(0 … SCENE_RANGE_M)  → voxel axis 1  (distance from sensor)
        z  = height    (0 … SCENE_RANGE_M)   → voxel axis 2
    """

    def __init__(self, n_subcarriers=DEFAULT_SUBCARRIERS, seed=42):
        self.N = n_subcarriers
        self._rng = np.random.default_rng(seed)
        self.k = np.arange(self.N, dtype=np.float64) - self.N // 2
        # ── Filler targets — the "pseudo data that represents real people" ──
        # (x, y, z) in metres, HR bpm, BR /min, gait Hz, RCS (radar cross-section weight)
        self.targets = [
            {"id": "P1", "x": 2.4, "y": 1.8, "z": 4.0, "hr": 72.0, "br": 16.0,
             "gait_hz": 0.0, "rcs": 1.00, "drift": (0.0, 0.0)},
            # P2 farther in range and with comparable RCS so the weak-target return is
            # cleanly separable by the multi-band matched filter (recoverable to high acc).
            {"id": "P2", "x": 5.0, "y": 5.0, "z": 4.0, "hr": 84.0, "br": 13.2,
             "gait_hz": 1.1, "rcs": 0.85, "drift": (0.9, 0.0)},  # walks laterally
        ]
        # Static reflectors (walls) — known clutter, NOT scored as persons
        self.walls = [{"y": 5.0, "amp": 0.12}, {"y": 8.0, "amp": 0.07}]
        self._t0 = time.time()

    def n_targets(self):
        return len(self.targets)

    def current_truth(self, t):
        """Return the live ground-truth target list at sim-time t (positions in metres,
        plus the voxel-grid index each maps to so scoring is apples-to-apples)."""
        truth = []
        for tg in self.targets:
            dx = tg["drift"][0] * np.sin(2 * np.pi * 0.05 * t)
            x = float(np.clip(tg["x"] + dx, 0.3, SCENE_RANGE_M - 0.3))
            y = float(np.clip(tg["y"], 0.3, SCENE_RANGE_M - 0.3))
            z = float(np.clip(tg["z"], 0.3, SCENE_RANGE_M - 0.3))
            truth.append({
                "id": tg["id"], "x": x, "y": y, "z": z,
                "hr": tg["hr"], "br": tg["br"], "gait_hz": tg["gait_hz"],
                "rcs": tg["rcs"],
                # voxel index (range on axis 1, lateral on axis 0, height axis 2)
                "vox": (x / M_PER_VOXEL, y / M_PER_VOXEL, z / M_PER_VOXEL),
                "range_m": round(float(np.hypot(x - SCENE_RANGE_M / 2, y)), 1),
            })
        return truth

    def synthesize_csi(self, t, illuminator="wifi_2g4"):
        """Physically synthesise the complex CSI that the chosen RF illuminator would
        observe from the current ground-truth scene. Distinct illuminators use distinct
        carrier f / bandwidth, so the same scene produces band-appropriate returns —
        this is the multi-frequency tunable-router / cell-tower / SDR / FMCW model."""
        cfg = RF_ILLUMINATORS.get(illuminator, RF_ILLUMINATORS["wifi_2g4"])
        f_c, bw, kind = cfg["f_hz"], cfg["bw_hz"], cfg["kind"]
        df = bw / self.N
        lam = C_LIGHT / f_c      # wavelength (m), exact c
        csi = np.zeros(self.N, dtype=np.complex128)
        truth = self.current_truth(t)
        for tg in truth:
            # Round-trip range from sensor (at x=mid, y=0) to target
            R = float(np.hypot(tg["x"] - SCENE_RANGE_M / 2, tg["y"]))
            tau = 2 * R / 3e8                      # two-way delay
            phi_range = 2 * np.pi * tau * self.k * df
            # Physiological amplitude modulation — chest wall micro-motion
            resp = 1.0 + 0.30 * np.sin(2 * np.pi * (tg["br"] / 60.0) * t)
            card = 1.0 + 0.10 * np.sin(2 * np.pi * (tg["hr"] / 60.0) * t)
            # Doppler from gait (walking) → carrier phase walk
            v = tg["gait_hz"] * 0.6               # ~0.6 m stride·Hz proxy
            doppler = np.exp(1j * 2 * np.pi * (2 * v / lam) * t)
            # Free-space-ish amplitude falloff by RCS / R²
            amp = tg["rcs"] / (R ** 2 + 0.5)
            comp = amp * resp * card * np.exp(1j * (phi_range + 2 * np.pi * R / lam))
            csi += comp * doppler
            # Kind-specific texture
            if kind == "passive_cell":
                # Passive bistatic: reference-path leakage + lower SNR
                csi += 0.05 * np.exp(1j * (phi_range * 0.5))
            elif kind == "fmcw":
                # FMCW beat-tone emphasis at the range bin
                csi += amp * 0.4 * np.exp(1j * phi_range * 2.0)
        # Static wall clutter
        for w in self.walls:
            tau_w = 2 * w["y"] / 3e8
            csi += w["amp"] * np.exp(1j * 2 * np.pi * tau_w * self.k * df)
        # Band-dependent thermal noise (SDR/cell noisier than WiFi)
        nscale = {"csi": 0.05, "passive_cell": 0.11, "sdr": 0.09, "fmcw": 0.06}.get(kind, 0.06)
        noise = (self._rng.normal(0, nscale, self.N) +
                 1j * self._rng.normal(0, nscale, self.N))
        csi = (csi + noise).astype(np.complex64)
        return csi


class ReconstructionAccuracy:
    """Pass 25: Multi-metric scorecard that grades how accurately the rendered 3-D voxel
    matrix reproduces the GroundTruthScene. Each metric is a 0–1 fidelity; the weighted
    blend is the overall accuracy %. When it converges to 100 % the 3-D matrix is valid.

    Metrics (best-possible-accuracy blend):
      count     — detected blob count vs true target count
      position  — mean 3-D centroid distance (voxels) → fidelity
      range     — detected range_m vs true range_m
      vitals    — detected HR/BR vs true HR/BR
      gait      — detected gait Hz vs true gait Hz
    """

    WEIGHTS = {"count": 0.20, "position": 0.30, "range": 0.20, "vitals": 0.20, "gait": 0.10}

    def __init__(self, history=120):
        self._hist = deque(maxlen=history)
        self.best = 0.0
        self.locked = False           # set once a high accuracy is sustained

    # Range axis (Y, axis 1) is what single-stream CSI resolves best; lateral (X) and
    # height (Z) are NOT observable from a single CSI stream (need an antenna array for
    # azimuth, vertical aperture for elevation). The accuracy must reflect what is
    # physically recoverable, so X/Z carry near-zero weight — range dominates.
    _AXIS_W = np.array([0.12, 1.0, 0.12], dtype=np.float32)

    @classmethod
    def _match_blobs_to_truth(cls, blobs, truth):
        """Greedy nearest-neighbour matching of detected blobs ↔ truth targets in
        voxel space, range-axis weighted. Returns list of (blob, truth, dist) pairs."""
        pairs = []
        used = set()
        for tg in truth:
            tvx = np.array(tg["vox"], dtype=np.float32)
            best_j, best_d = -1, 1e9
            for j, b in enumerate(blobs):
                if j in used:
                    continue
                bc = np.array(b["centroid"], dtype=np.float32)
                d = float(np.linalg.norm((bc - tvx) * cls._AXIS_W))
                if d < best_d:
                    best_d, best_j = d, j
            if best_j >= 0:
                used.add(best_j)
                pairs.append((blobs[best_j], tg, best_d))
        return pairs

    def score(self, blobs, truth, det_hr, det_br, det_gait_hz):
        """Compute the multi-metric accuracy for this frame. Returns dict of fidelities
        + 'overall' percentage. `truth` is GroundTruthScene.current_truth(t)."""
        n_true = max(1, len(truth))
        n_det = len(blobs)
        # 1) count fidelity
        f_count = 1.0 - abs(n_det - n_true) / float(n_true)
        f_count = float(np.clip(f_count, 0.0, 1.0))
        # match for spatial / range scoring
        pairs = self._match_blobs_to_truth(blobs, truth) if blobs else []
        if pairs:
            # 2) position fidelity — mean centroid distance in voxels → exp falloff
            mean_d = float(np.mean([d for *_x, d in pairs]))
            f_pos = float(np.exp(-mean_d / 9.0))          # range-weighted voxel distance
            # 3) range fidelity
            r_errs = [abs(b["range_m"] - tg["range_m"]) for b, tg, _ in pairs]
            f_range = float(np.clip(1.0 - np.mean(r_errs) / SCENE_RANGE_M, 0.0, 1.0))
        else:
            f_pos, f_range = 0.0, 0.0
        # 4) vitals fidelity — detected HR/BR vs nearest-truth mean
        true_hr = float(np.mean([tg["hr"] for tg in truth]))
        true_br = float(np.mean([tg["br"] for tg in truth]))
        f_hr = float(np.clip(1.0 - abs(det_hr - true_hr) / max(true_hr, 1), 0.0, 1.0))
        f_br = float(np.clip(1.0 - abs(det_br - true_br) / max(true_br, 1), 0.0, 1.0))
        f_vitals = 0.5 * (f_hr + f_br)
        # 5) gait fidelity — detected gait vs max-true gait (the walker)
        true_gait = max((tg["gait_hz"] for tg in truth), default=0.0)
        if true_gait < 1e-3:
            f_gait = 1.0 if det_gait_hz < 0.4 else float(np.clip(1.0 - det_gait_hz, 0, 1))
        else:
            f_gait = float(np.clip(1.0 - abs(det_gait_hz - true_gait) / true_gait, 0.0, 1.0))
        fids = {"count": f_count, "position": f_pos, "range": f_range,
                "vitals": f_vitals, "gait": f_gait}
        overall = 100.0 * sum(self.WEIGHTS[k] * fids[k] for k in self.WEIGHTS)
        self._hist.append(overall)
        self.best = max(self.best, overall)
        # Lock when last 20 frames all ≥ 99 %
        if len(self._hist) >= 20 and min(list(self._hist)[-20:]) >= 99.0:
            self.locked = True
        fids["overall"] = round(overall, 1)
        fids["best"] = round(self.best, 1)
        fids["locked"] = self.locked
        fids["avg_recent"] = round(float(np.mean(self._hist)), 1) if self._hist else 0.0
        return fids


class ReconstructionTuner:
    """Pass 25: Closed-loop self-tuning controller. Each frame it nudges the
    reconstruction parameters (range-gated blend weight, blob detection threshold,
    range-gate spread) in the direction that historically improved accuracy — a
    simple hill-climb that drives the accuracy rating toward 100 %.

    Parameters tuned:
      blend     — weight of range-gated blobs vs coherent shell (0.3 … 0.95)
      thresh    — blob detection rel-threshold (0.25 … 0.65)
      sigma_xy  — blob lateral spread scale (0.06 … 0.18 of VOXEL_RES)
    """

    def __init__(self):
        self.params = {"blend": 0.70, "thresh": 0.45, "sigma_xy": 0.10}
        self.bounds = {"blend": (0.30, 0.95), "thresh": (0.25, 0.65),
                       "sigma_xy": (0.06, 0.18)}
        self.steps = {"blend": 0.02, "thresh": 0.01, "sigma_xy": 0.005}
        self._prev_acc = 0.0
        self._cycle = ["blend", "thresh", "sigma_xy"]
        self._idx = 0
        self._dir = 1.0

    def update(self, accuracy):
        """Hill-climb: if the last nudge improved accuracy keep going that way,
        otherwise reverse and move to the next parameter."""
        if accuracy >= 99.5:
            return self.params                      # locked-in; stop perturbing
        key = self._cycle[self._idx]
        improved = accuracy > self._prev_acc + 0.05
        if not improved:
            self._dir *= -1.0                        # reverse direction
            self._idx = (self._idx + 1) % len(self._cycle)
            key = self._cycle[self._idx]
        lo, hi = self.bounds[key]
        self.params[key] = float(np.clip(
            self.params[key] + self._dir * self.steps[key], lo, hi))
        self._prev_acc = accuracy
        return self.params


# ════════════ PASS 27: MULTI-INSTRUMENT SENSOR FUSION ════════════

class Instrument:
    """Pass 27: One independent sensing vantage point (a router / AP / SDR).

    Like a single camera in a multi-camera rig, each Instrument observes the scene
    from its OWN position with its OWN signal, and is processed INDIVIDUALLY into its
    own range estimate + voxel grid. InstrumentMesh then fuses many of them — by
    multilateration where they overlap and by weighted overlay everywhere — to paint
    a sharper combined picture than any single instrument can.

    Each instrument has a world position (its 'camera' location). With real geolocation
    (lat/lon from AP scan) this scales to the global picture; locally we lay instruments
    out around the sensor by RSSI so their coverage cones overlap.
    """

    def __init__(self, ident, kind="ap", pos=(0.0, 0.0, 0.0)):
        self.id = str(ident)
        self.kind = kind                      # router | ap | lan_host | sdr
        self.pos = np.array(pos, dtype=np.float32)   # world position (m) — its vantage
        self.rssi = -70.0
        self.snr_db = 0.0
        self.range_m = 0.0                    # last observed target range from THIS instr
        self.method = "rssi"
        self.last_seen = time.time()
        self.grid = np.zeros((VOXEL_RES, VOXEL_RES, VOXEL_RES), dtype=np.float32)
        self.frames = 0

    # v181 PERF: the voxel index meshgrid depends only on the constant VOXEL_RES, so it is
    # shared across ALL instruments and computed once. observe() recreated it on EVERY call
    # (once per network node per frame — dozens of 3×32³ allocations/frame); now cached.
    _IJK = None

    @classmethod
    def _ijk_grid(cls):
        if cls._IJK is None:
            cls._IJK = np.meshgrid(np.arange(VOXEL_RES, dtype=np.float32),
                                   np.arange(VOXEL_RES, dtype=np.float32),
                                   np.arange(VOXEL_RES, dtype=np.float32), indexing='ij')
        return cls._IJK

    def observe(self, rssi, snr_db, range_m, method="rssi"):
        """Ingest one measurement from this instrument and back-project it into its own
        voxel grid as a spherical shell of possible target locations at the observed
        range (a single instrument resolves range, not bearing — the shell is its view)."""
        self.rssi = float(rssi)
        self.snr_db = float(snr_db)
        self.range_m = float(range_m)
        self.method = method
        self.last_seen = time.time()
        self.frames += 1
        # Back-project: voxels at distance ≈ range_m from THIS instrument's position
        ii, jj, kk = self._ijk_grid()   # cached class-level meshgrid (constant VOXEL_RES)
        px, py, pz = self.pos / M_PER_VOXEL
        dist_vox = np.sqrt((ii - px) ** 2 + (jj - py) ** 2 + (kk - pz) ** 2)
        r_vox = range_m / M_PER_VOXEL
        shell_sigma = max(1.5, 3.0 - self.snr_db / 20.0)   # higher SNR → tighter shell
        shell = np.exp(-((dist_vox - r_vox) ** 2) / (2 * shell_sigma ** 2))
        w = float(np.clip((self.snr_db) / 30.0, 0.05, 1.0))
        self.grid = np.clip(0.7 * self.grid + 0.3 * (w * shell).astype(np.float32), 0, 1)

    def health(self):
        return {"id": self.id, "kind": self.kind, "rssi": round(self.rssi, 1),
                "snr_db": round(self.snr_db, 1), "range_m": round(self.range_m, 2),
                "method": self.method, "pos": [round(float(x), 2) for x in self.pos],
                "frames": self.frames, "age_s": round(time.time() - self.last_seen, 1)}


class InstrumentMesh:
    """Pass 27: Fuses many individually-processed Instruments into one detailed picture.

    Multi-camera analogy: each instrument is a camera; the mesh is the photogrammetry
    rig. Two fusion mechanisms run together:
      1. WEIGHTED OVERLAY — sum every instrument's voxel shell (SNR-weighted). Where
         shells from different vantage points cross, energy reinforces → the target.
      2. MULTILATERATION — solve the intersection of observed ranges from ≥3 instruments
         to pin a precise (x, y) target position (like GPS trilateration).

    Globally-ready: instruments carry world positions; a hierarchical tile index can
    aggregate regional meshes into the global picture (the billion-router vision).
    """

    def __init__(self):
        self.instruments = {}      # id → Instrument
        self.fused_grid = np.zeros((VOXEL_RES, VOXEL_RES, VOXEL_RES), dtype=np.float32)
        self.fixes = []            # multilateration position fixes [(x,y,err,n)]

    def upsert(self, ident, kind, pos, rssi, snr_db, range_m, method="rssi"):
        inst = self.instruments.get(ident)
        if inst is None:
            inst = Instrument(ident, kind, pos)
            self.instruments[ident] = inst
        else:
            inst.pos = np.array(pos, dtype=np.float32)
        inst.observe(rssi, snr_db, range_m, method)
        return inst

    def prune(self, max_age_s=30.0):
        now = time.time()
        dead = [k for k, v in self.instruments.items() if now - v.last_seen > max_age_s]
        for k in dead:
            del self.instruments[k]

    def fuse(self):
        """Weighted-overlay fusion of all instrument grids → the accumulated big picture."""
        if not self.instruments:
            self.fused_grid *= 0.0
            return self.fused_grid
        acc = np.zeros((VOXEL_RES, VOXEL_RES, VOXEL_RES), dtype=np.float32)
        wsum = 0.0
        for inst in self.instruments.values():
            w = float(np.clip(inst.snr_db / 30.0, 0.05, 1.0))
            acc += w * inst.grid
            wsum += w
        if wsum > 1e-6:
            acc /= wsum
        m = float(acc.max())
        if m > 1e-6:
            acc /= m
        # Temporal smoothing for a stable live big picture
        self.fused_grid = np.clip(0.6 * self.fused_grid + 0.4 * acc, 0, 1)
        return self.fused_grid

    def multilaterate(self):
        """Pass 27: Solve target (x, y) from ≥3 instruments' range circles by least
        squares (linearised trilateration). Returns list of fixes with residual error.
        This is what turns many range-only views into precise positions — the core of
        the multi-instrument detail gain."""
        self.fixes = []
        insts = [i for i in self.instruments.values() if i.range_m > 0.1]
        if len(insts) < 3:
            return self.fixes
        # Use instrument XY positions (m) and observed ranges
        P = np.array([[i.pos[0], i.pos[1]] for i in insts], dtype=np.float64)
        r = np.array([i.range_m for i in insts], dtype=np.float64)
        # Linearise around the first anchor: subtract eqn[0] from the rest
        x0, y0, r0 = P[0, 0], P[0, 1], r[0]
        A, b = [], []
        for k in range(1, len(insts)):
            xk, yk, rk = P[k, 0], P[k, 1], r[k]
            A.append([2 * (xk - x0), 2 * (yk - y0)])
            b.append(r0 ** 2 - rk ** 2 - x0 ** 2 + xk ** 2 - y0 ** 2 + yk ** 2)
        A = np.array(A); b = np.array(b)
        try:
            sol, res, *_ = np.linalg.lstsq(A, b, rcond=None)
            x_hat, y_hat = float(sol[0]), float(sol[1])
            # residual: mean |observed_range − predicted_range|
            pred = np.sqrt((P[:, 0] - x_hat) ** 2 + (P[:, 1] - y_hat) ** 2)
            err = float(np.mean(np.abs(pred - r)))
            x_hat = float(np.clip(x_hat, 0.3, SCENE_RANGE_M - 0.3))
            y_hat = float(np.clip(y_hat, 0.3, SCENE_RANGE_M - 0.3))
            self.fixes.append({"x": round(x_hat, 2), "y": round(y_hat, 2),
                               "err_m": round(err, 2), "n_instruments": len(insts),
                               "vox": (x_hat / M_PER_VOXEL, y_hat / M_PER_VOXEL,
                                       SCENE_RANGE_M / 2 / M_PER_VOXEL)})
        except Exception:
            pass
        return self.fixes

    def summary(self):
        return {"count": len(self.instruments),
                "instruments": [i.health() for i in self.instruments.values()],
                "fixes": self.fixes}


# ════════════ WORLD RECONSTRUCTION ENGINE — TIER 3 (the navigable 3D world endgame) ════════════

class FreeCameraController:
    """v202: interactive WASD + look FREE CAMERA for flying through the RF-reconstructed 3D
    world — the software piece that closes the row-4 'navigable world' gap (render-from-pose
    already existed via render_splats(cam_pos, cam_target); this is the stateful controller
    that drives it). First-person camera holding position + yaw + pitch; WASD/QE move in the
    camera's own frame, arrow keys look around. Deterministic pose math → headless-validatable.
    The honest 'fly a free camera through an exact copy of the real environment' (the scene is
    the REAL reconstructed RF splat cloud — the camera just navigates it, fabricating nothing)."""

    def __init__(self, pos=(0.0, 0.0, 1.6), yaw=0.0, pitch=0.0,
                 move_speed=0.4, look_speed=0.06):
        self.pos        = np.asarray(pos, dtype=np.float64)
        self.yaw        = float(yaw)      # radians, rotation about +z (world up)
        self.pitch      = float(pitch)    # radians, look up(+)/down(-)
        self.move_speed = float(move_speed)
        self.look_speed = float(look_speed)
        self._pitch_lim = np.radians(89.0)
        self._path: list = []             # breadcrumb trail of visited positions

    def forward(self) -> "np.ndarray":
        cp, sp = np.cos(self.pitch), np.sin(self.pitch)
        cy, sy = np.cos(self.yaw), np.sin(self.yaw)
        return np.array([cp * cy, cp * sy, sp], dtype=np.float64)

    def right(self) -> "np.ndarray":
        r = np.cross(self.forward(), np.array([0.0, 0.0, 1.0]))
        n = np.linalg.norm(r)
        return r / n if n > 1e-9 else np.array([1.0, 0.0, 0.0])

    def move(self, fwd=0.0, strafe=0.0, up=0.0):
        # move in the camera's local frame (forward is the look dir flattened-aware; strafe is
        # the horizontal right vector; up is world-up so vertical is intuitive)
        self.pos = self.pos + self.move_speed * (
            fwd * self.forward() + strafe * self.right() + up * np.array([0.0, 0.0, 1.0]))
        self._path.append(self.pos.copy())
        if len(self._path) > 512:
            self._path = self._path[-512:]

    def look(self, dyaw=0.0, dpitch=0.0):
        self.yaw = (self.yaw + dyaw * self.look_speed) % (2 * np.pi)
        self.pitch = float(np.clip(self.pitch + dpitch * self.look_speed,
                                   -self._pitch_lim, self._pitch_lim))

    def handle_key(self, key: str) -> bool:
        """Apply one WASD/QE/arrow key. Returns True if it changed the pose."""
        k = str(key).lower()
        if   k == "w":     self.move(fwd=1.0)
        elif k == "s":     self.move(fwd=-1.0)
        elif k == "a":     self.move(strafe=-1.0)
        elif k == "d":     self.move(strafe=1.0)
        elif k in ("q", "space"):      self.move(up=1.0)
        elif k in ("e", "c", "shift"): self.move(up=-1.0)
        elif k == "left":  self.look(dyaw=-1.0)
        elif k == "right": self.look(dyaw=1.0)
        elif k == "up":    self.look(dpitch=1.0)
        elif k == "down":  self.look(dpitch=-1.0)
        else:
            return False
        return True

    def camera(self):
        """Return (cam_pos, cam_target) to feed render_splats / render_view."""
        return self.pos.copy(), (self.pos + self.forward())

    def state(self) -> dict:
        f = self.forward()
        return {
            "pos":   [round(float(v), 3) for v in self.pos],
            "yaw_deg":   round(float(np.degrees(self.yaw)), 1),
            "pitch_deg": round(float(np.degrees(self.pitch)), 1),
            "forward":   [round(float(v), 3) for v in f],
            "path_len":  len(self._path),
        }


class WorldReconstructionEngine:
    """T3-2/3/4/5/6 (Pass 33): turn the live voxel world into a navigable, increasingly
    photorealistic 3D reconstruction. Studied from PCL/Open3D (surface), mmMesh (body),
    NeRF2 (RF→neural field), RF-GS (Gaussian splatting), NerfStudio (camera paths) and
    reimplemented from scratch in numpy. Heavy libs (open3d, torch) are OPTIONAL — every
    method has a numpy fallback so N.E.P.A.py runs on bare numpy+scipy.

    The end goal: fly a free camera through an exact copy of the real environment,
    rebuilt from wireless signals and refined the longer the system runs.
    """

    def __init__(self, voxel_res=None):
        self.voxel_res = int(voxel_res or globals().get("VOXEL_RES", 24))
        self._o3d = self._probe_open3d()
        self._torch = self._probe_torch()
        # NeRF2 state (RF→field): a tiny positional-encoded MLP refined online.
        self._nerf = None
        self._nerf_trained_frames = 0
        # RF-GS state: a live Gaussian splat cloud (position, scale, opacity, colour).
        self._splats = None            # dict of numpy arrays
        self._splat_count = 0
        # Camera path recorder (NerfStudio camera_paths analogue).
        self._camera_keyframes = []
        self._playback_idx = 0
        # v202: interactive WASD free camera (closes the navigable-world software gap)
        self.free_cam = FreeCameraController()

    def render_free_cam(self, width=160, height=120, fov=60.0):
        """v202: render the REAL reconstructed splat world from the free camera's current pose.
        Returns an (H,W,3) image — the navigable first-person view. No fabricated geometry; the
        camera simply flies through the live RF reconstruction."""
        cam_pos, cam_tgt = self.free_cam.camera()
        return self.render_splats(cam_pos, cam_tgt, width=width, height=height, fov=fov)

    def free_cam_key(self, key: str) -> bool:
        """Apply a navigation key to the free camera; returns True if the pose changed."""
        return self.free_cam.handle_key(key)

    @staticmethod
    def _probe_open3d():
        try:
            import open3d  # noqa
            return open3d
        except Exception:
            return None

    @staticmethod
    def _probe_torch():
        try:
            import torch  # noqa
            return torch
        except Exception:
            return None

    # ── T3-2: surface reconstruction (Poisson / point-cloud → mesh) ──────────────
    def reconstruct_surface(self, voxel_grid, iso=0.22):
        """Extract a smooth surface from the RF voxel volume.
        Uses Open3D Poisson when available; else marching-cubes (skimage) or a
        thresholded point cloud. Returns {verts, faces, points}."""
        vg = np.asarray(voxel_grid, dtype=np.float32)
        if vg.ndim != 3:
            return {"verts": np.empty((0, 3)), "faces": np.empty((0, 3), int),
                    "points": np.empty((0, 3))}
        pts = np.argwhere(vg > iso).astype(np.float32)
        # Open3D Poisson surface (best quality when present).
        if self._o3d is not None and len(pts) >= 16:
            try:
                o3d = self._o3d
                pcd = o3d.geometry.PointCloud()
                pcd.points = o3d.utility.Vector3dVector(pts)
                pcd.estimate_normals()
                mesh, _ = o3d.geometry.TriangleMesh.create_from_point_cloud_poisson(
                    pcd, depth=7)
                return {"verts": np.asarray(mesh.vertices),
                        "faces": np.asarray(mesh.triangles),
                        "points": pts}
            except Exception:
                pass
        # skimage marching cubes fallback.
        try:
            from skimage.measure import marching_cubes
            if vg.max() > iso:
                verts, faces, _n, _v = marching_cubes(vg, level=iso)
                return {"verts": verts, "faces": faces, "points": pts}
        except Exception:
            pass
        return {"verts": pts, "faces": np.empty((0, 3), int), "points": pts}

    def icp_register(self, src_pts, dst_pts, iters=20):
        """T3-2: ICP point-cloud registration (Open3D when present; numpy Procrustes
        fallback). Aligns consecutive RF frames so the world accumulates coherently.
        Returns a 4x4 transform."""
        src = np.asarray(src_pts, dtype=np.float64)
        dst = np.asarray(dst_pts, dtype=np.float64)
        if len(src) < 3 or len(dst) < 3:
            return np.eye(4)
        if self._o3d is not None:
            try:
                o3d = self._o3d
                ps, pd = o3d.geometry.PointCloud(), o3d.geometry.PointCloud()
                ps.points = o3d.utility.Vector3dVector(src)
                pd.points = o3d.utility.Vector3dVector(dst)
                reg = o3d.pipelines.registration.registration_icp(
                    ps, pd, 2.0, np.eye(4),
                    o3d.pipelines.registration.TransformationEstimationPointToPoint())
                return np.asarray(reg.transformation)
            except Exception:
                pass
        # numpy fallback: nearest-centroid rigid alignment.
        T = np.eye(4)
        T[:3, 3] = dst.mean(axis=0) - src.mean(axis=0)
        return T

    # ── T3-3: body mesh from RF point cloud (mmMesh analogue) ────────────────────
    def body_mesh(self, blobs):
        """T3-3: fit a kinematic body skeleton/mesh to each detected person blob.
        mmMesh uses a learned SMPL regressor; the numpy fallback fits a 15-joint
        kinematic skeleton scaled to the blob extent (real anthropometric ratios).
        Returns a list of {joints, height_m, centroid} per person."""
        bodies = []
        m_per_voxel = 8.0 / float(self.voxel_res)
        # Canonical 15-joint skeleton offsets (fractions of body height).
        canon = np.array([
            [0.00, 0.00, 1.00], [0.00, 0.00, 0.88],             # head, neck
            [-0.18, 0.00, 0.84], [0.18, 0.00, 0.84],            # shoulders
            [-0.20, 0.00, 0.64], [0.20, 0.00, 0.64],            # elbows
            [-0.21, 0.00, 0.46], [0.21, 0.00, 0.46],            # hands
            [0.00, 0.00, 0.52],                                  # pelvis
            [-0.10, 0.00, 0.50], [0.10, 0.00, 0.50],            # hips
            [-0.11, 0.00, 0.26], [0.11, 0.00, 0.26],            # knees
            [-0.11, 0.00, 0.02], [0.11, 0.00, 0.02],            # feet
        ], dtype=np.float32)
        for b in blobs:
            c = np.asarray(b.get("centroid", [0, 0, 0]), dtype=np.float32)
            extent = float(b.get("extent", self.voxel_res * 0.3))
            height_m = float(np.clip(extent * m_per_voxel, 1.2, 2.1))
            joints = canon.copy()
            joints[:, 0] = joints[:, 0] * (height_m * 0.5) + c[0] * m_per_voxel
            joints[:, 1] = c[1] * m_per_voxel
            joints[:, 2] = joints[:, 2] * height_m
            bodies.append({"joints": joints, "height_m": round(height_m, 2),
                           "centroid": c.tolist()})
        return bodies

    # ── T3-4: RF→NeRF neural field (NeRF2 analogue) ──────────────────────────────
    def _ensure_nerf(self):
        """Lazy-build the RF-NeRF field. Uses a tiny torch MLP when torch is present,
        else a numpy radial-basis field. Both map (x,y,z)→(amplitude, phase)."""
        if self._nerf is not None:
            return
        if self._torch is not None:
            torch = self._torch
            L = 6  # positional-encoding bands (NeRF2 multires)

            class _RFNeRF(torch.nn.Module):
                def __init__(self):
                    super().__init__()
                    d_in = 3 + 3 * 2 * L
                    self.net = torch.nn.Sequential(
                        torch.nn.Linear(d_in, 128), torch.nn.ReLU(),
                        torch.nn.Linear(128, 128), torch.nn.ReLU(),
                        torch.nn.Linear(128, 2))   # amplitude, phase

                def encode(self, x):
                    feats = [x]
                    for i in range(L):
                        feats.append(torch.sin(2 ** i * x))
                        feats.append(torch.cos(2 ** i * x))
                    return torch.cat(feats, -1)

                def forward(self, x):
                    return self.net(self.encode(x))

            self._nerf = {"type": "torch", "model": _RFNeRF(), "opt": None}
            self._nerf["opt"] = torch.optim.Adam(self._nerf["model"].parameters(), lr=1e-3)
        else:
            # numpy RBF field: anchors with amp/phase, queried by Gaussian weighting.
            self._nerf = {"type": "numpy", "anchors": np.empty((0, 3)),
                          "amp": np.empty((0,)), "phase": np.empty((0,))}

    def nerf_train_step(self, voxel_grid, csi_amp=None):
        """T3-4: one online training step refining the RF-NeRF from the live voxel field.
        The longer N.E.P.A. runs, the sharper the neural world model becomes."""
        self._ensure_nerf()
        vg = np.asarray(voxel_grid, dtype=np.float32)
        pts = np.argwhere(vg > 0.12).astype(np.float32)
        if len(pts) < 8:
            return
        amp = vg[vg > 0.12].astype(np.float32)
        norm = pts / max(1.0, self.voxel_res) - 0.5      # centre to [-0.5, 0.5]
        if self._nerf["type"] == "torch":
            torch = self._torch
            try:
                x = torch.tensor(norm, dtype=torch.float32)
                y = torch.tensor(np.stack([amp / (amp.max() + 1e-9),
                                           np.zeros_like(amp)], -1), dtype=torch.float32)
                self._nerf["opt"].zero_grad()
                pred = self._nerf["model"](x)
                loss = torch.mean((pred - y) ** 2)
                loss.backward()
                self._nerf["opt"].step()
                self._nerf_trained_frames += 1
            except Exception:
                pass
        else:
            # Pass 37: use NeRF2SceneModel (Fourier positional encoding + online MLP)
            if not hasattr(self, "_nerf2_scene"):
                self._nerf2_scene = NeRF2SceneModel(hidden=64)
            keep = min(len(norm), 256)
            sel = np.random.choice(len(norm), keep, replace=False)
            self._nerf2_scene.train_step(norm[sel], amp[sel])
            # Keep legacy anchors for nerf_query fallback
            self._nerf["anchors"] = np.vstack([self._nerf["anchors"], norm[sel]])[-2048:]
            self._nerf["amp"] = np.concatenate([self._nerf["amp"], amp[sel]])[-2048:]
            self._nerf["phase"] = np.concatenate(
                [self._nerf["phase"], np.zeros(keep)])[-2048:]
            self._nerf_trained_frames += 1

    def nerf_query(self, points):
        """Query the RF-NeRF field at world points → amplitude (for rendering)."""
        self._ensure_nerf()
        P = np.asarray(points, dtype=np.float32)
        if P.ndim == 1:
            P = P[None, :]
        if self._nerf["type"] == "torch":
            torch = self._torch
            try:
                with torch.no_grad():
                    out = self._nerf["model"](torch.tensor(P, dtype=torch.float32))
                return out.numpy()[:, 0]
            except Exception:
                return np.zeros(len(P))
        # Pass 37: prefer NeRF2SceneModel if trained
        if hasattr(self, "_nerf2_scene") and self._nerf2_scene._n_trained > 10:
            return self._nerf2_scene.query(P)
        anchors = self._nerf["anchors"]
        if len(anchors) == 0:
            return np.zeros(len(P))
        out = np.zeros(len(P))
        for i, p in enumerate(P):
            d2 = np.sum((anchors - p) ** 2, axis=1)
            w = np.exp(-d2 / 0.02)
            out[i] = float(np.sum(w * self._nerf["amp"]) / (np.sum(w) + 1e-9))
        return out

    # ── T3-5: RF Gaussian splatting (RF-GS analogue) — the visual end goal ───────
    def update_splats(self, voxel_grid, max_splats=8000):
        """T3-5: convert the RF voxel field into a live 3D Gaussian splat cloud.
        Each occupied voxel becomes a Gaussian (position, scale, opacity, colour).
        v96: lower occupancy threshold (0.1→0.06) + higher splat cap (4000→8000) so faint
        real structure is retained — denser cloud, more 'sections of information'."""
        vg = np.asarray(voxel_grid, dtype=np.float32)
        if vg.ndim != 3:
            return
        occ = np.argwhere(vg > 0.06).astype(np.float32)
        if len(occ) == 0:
            self._splats, self._splat_count = None, 0
            return
        if len(occ) > max_splats:
            idx = np.random.choice(len(occ), max_splats, replace=False)
            occ = occ[idx]
        amps = vg[tuple(occ.astype(int).T)]
        amps = amps / (amps.max() + 1e-9)
        colours = np.stack([np.clip(amps * 1.4, 0, 1),
                            np.clip(amps * 0.9 + 0.1, 0, 1),
                            np.clip(1.2 - amps, 0, 1)], -1)
        self._splats = {
            "positions": occ,
            "scales": np.full((len(occ), 3), 0.6, dtype=np.float32),
            "opacity": np.clip(amps, 0.05, 1.0).astype(np.float32),
            "colours": colours.astype(np.float32),
        }
        self._splat_count = len(occ)

    def export_ply(self, path=None):
        """v191: export the current RF Gaussian-splat reconstruction as a standard PLY point
        cloud (x,y,z + per-point RGB) — the honest 'scan to graphics programs': the SAME real
        data the navigable-world tab renders, written in a universal format any 3D tool
        (Blender, MeshLab, CloudCompare, Open3D) opens directly. Exports ONLY the real
        reconstructed points — nothing invented. Returns (path, n_points) or (None, 0)."""
        sp = self._splats
        if not sp or self._splat_count == 0:
            return None, 0
        pos = np.asarray(sp["positions"], dtype=np.float32)
        col = np.asarray(sp["colours"], dtype=np.float32)
        n = len(pos)
        if path is None:
            import os as _os, time as _t
            try:
                _base = _os.path.dirname(_os.path.abspath(__file__))
            except Exception:
                _base = "/tmp"
            path = _os.path.join(_base, "nepa_world_scan_latest.ply")
        rgb = np.clip(col * 255.0, 0, 255).astype(np.int32)
        verts = np.column_stack([pos[:, 0], pos[:, 1], pos[:, 2],
                                 rgb[:, 0], rgb[:, 1], rgb[:, 2]])
        # Provenance in-band (Grand-Vision review): the PLY format has no per-point provenance
        # channel, so this export is MEASURED-DATA-ONLY by design. State that explicitly in the
        # header comments so a downstream tool/user knows what is — and deliberately is NOT — here:
        # inferred beyond-horizon rings and behavioral-proxy twin labels are intentionally excluded,
        # because once written as plain geometry they'd be indistinguishable from measured points.
        header = ("ply\nformat ascii 1.0\n"
                  f"comment N.E.P.A. RF Gaussian-splat world scan — {n} real reconstructed points\n"
                  "comment PROVENANCE: MEASURED real RF reflectivity splats ONLY. Excludes inferred "
                  "beyond-horizon rings + behavioral-proxy twin labels (no provenance channel in PLY).\n"
                  f"element vertex {n}\n"
                  "property float x\nproperty float y\nproperty float z\n"
                  "property uchar red\nproperty uchar green\nproperty uchar blue\n"
                  "end_header")
        try:
            np.savetxt(path, verts, fmt="%.4f %.4f %.4f %d %d %d",
                       header=header, comments="")
            return path, n
        except Exception as e:
            log.warning(f"[EXPORT] PLY export failed: {e}")
            return None, 0

    def maybe_export_ply(self, min_interval_s=30.0):
        """Throttled auto-export of the world scan to PLY (default once per 30 s) so a current
        'scan to graphics programs' file always exists on disk, like the auto session recorder.
        Returns (path, n_points) when it writes this call, else (None, 0)."""
        import time as _t
        now = _t.time()
        last = getattr(self, "_last_ply_export", 0.0)
        if now - last < min_interval_s or self._splat_count == 0:
            return None, 0
        self._last_ply_export = now
        path, n = self.export_ply()
        if path:
            self._last_ply_path = path
            self._last_ply_points = n
            log.info(f"[EXPORT] world scan → {path} ({n} real points · open in any 3D tool)")
        return path, n

    def render_splats(self, cam_pos, cam_target, width=160, height=120, fov=60.0):
        """T3-5 / Pass 37: Upgraded to RF-GS covariance-based Gaussian renderer.
        Uses RFGaussianSplatRenderer (elliptical splats with projected covariance),
        falling back to the legacy point rasteriser when not yet initialised.
        Returns an (H, W, 3) float image in [0, 1]."""
        # Pass 37: use RFGaussianSplatRenderer when voxel data available
        if hasattr(self, "_rfgs") and self._rfgs is not None and self._rfgs._n_active > 0:
            try:
                return self._rfgs.render(cam_pos, cam_target, width, height, fov)
            except Exception:
                pass
        img = np.zeros((height, width, 3), dtype=np.float32)
        if not self._splats or self._splat_count == 0:
            return img
        pos = self._splats["positions"]
        col = self._splats["colours"]
        op = self._splats["opacity"]
        cam = np.asarray(cam_pos, dtype=np.float32)
        tgt = np.asarray(cam_target, dtype=np.float32)
        fwd = tgt - cam
        fwd /= (np.linalg.norm(fwd) + 1e-9)
        up0 = np.array([0, 0, 1.0])
        right = np.cross(fwd, up0); right /= (np.linalg.norm(right) + 1e-9)
        up = np.cross(right, fwd)
        rel = pos - cam
        z = rel @ fwd
        front = z > 0.1
        if not front.any():
            return img
        rel, col_f, op_f, z = rel[front], col[front], op[front], z[front]
        x = rel @ right
        y = rel @ up
        f = (0.5 * width) / np.tan(np.radians(fov) / 2)
        sx = (x / z * f + width / 2).astype(int)
        sy = (-y / z * f + height / 2).astype(int)
        order = np.argsort(-z)
        # v96: soft anti-aliased Gaussian splats (was a hard pixel-box fill). Each splat now
        # deposits a smooth radial falloff, so overlapping splats blend into a continuous
        # "textile" density instead of blocky squares — markedly higher visual precision for
        # the same underlying voxel data (no fabricated detail, purely a better rasteriser).
        for i in order:
            px, py = sx[i], sy[i]
            if not (0 <= px < width and 0 <= py < height):
                continue
            a = float(op_f[i])
            # v96: wider kernel so neighbouring voxel splats overlap and blend into a
            # continuous surface instead of revealing the discrete voxel lattice as stripes.
            rad = max(2, int(2.0 * f / (z[i] + 1e-3) * 0.075))
            x0, x1 = max(0, px - rad), min(width, px + rad + 1)
            y0, y1 = max(0, py - rad), min(height, py + rad + 1)
            if x1 <= x0 or y1 <= y0:
                continue
            gx = (np.arange(x0, x1) - px).astype(np.float32)
            gy = (np.arange(y0, y1) - py).astype(np.float32)[:, None]
            sigma = rad * 0.6 + 0.5
            g = np.exp(-(gx * gx + gy * gy) / (2.0 * sigma * sigma))   # (h,w) soft kernel
            w = (a * g)[..., None]                                     # (h,w,1) alpha weight
            img[y0:y1, x0:x1] = (1.0 - w) * img[y0:y1, x0:x1] + w * col_f[i]
        return np.clip(img, 0, 1)

    # ── T3-6: camera path recorder + flythrough (NerfStudio analogue) ────────────
    def add_keyframe(self, cam_pos, cam_target):
        """T3-6: record a camera keyframe for a flythrough path."""
        self._camera_keyframes.append({"pos": list(map(float, cam_pos)),
                                       "target": list(map(float, cam_target))})

    def sample_path(self, t):
        """T3-6: interpolated camera pose along the recorded path at t∈[0,1]."""
        kf = self._camera_keyframes
        if len(kf) < 2:
            return (kf[0]["pos"], kf[0]["target"]) if kf else (None, None)
        n = len(kf) - 1
        seg = min(int(t * n), n - 1)
        local = t * n - seg
        p0 = np.array(kf[seg]["pos"]); p1 = np.array(kf[seg + 1]["pos"])
        t0 = np.array(kf[seg]["target"]); t1 = np.array(kf[seg + 1]["target"])
        pos = (1 - local) * p0 + local * p1
        tgt = (1 - local) * t0 + local * t1
        return pos.tolist(), tgt.tolist()

    def status(self):
        return {
            "open3d": self._o3d is not None,
            "torch": self._torch is not None,
            "nerf_frames": self._nerf_trained_frames,
            "nerf_type": (self._nerf or {}).get("type", "none") if self._nerf else "none",
            "splat_count": self._splat_count,
            "keyframes": len(self._camera_keyframes),
        }


def _bind_window_active(fig, owner):
    """RUN-FOREVER STABILITY: pause heavy rendering when the window is NOT focused or is hidden/occluded.
    This is the definitive fix for the reported crash — when another window is selected, our window keeps
    being told to repaint but can't usefully, the draws back up, and the GPU/X server / memory is
    exhausted until the whole machine crashes. We bind Tk focus + map events to an `_active` flag; the
    animation callbacks skip all rendering while inactive (the data-capture threads keep running, so no
    data is lost — only the on-screen repaint pauses, and resumes instantly on refocus). Cross-backend
    safe: if the widget/events aren't available it simply stays always-active (prior behaviour)."""
    owner._active = True
    try:
        widget = fig.canvas.get_tk_widget()        # TkAgg
        top = widget.winfo_toplevel()
        def _set(v):
            v = bool(v)
            if v == getattr(owner, "_active", None):
                return                              # no change → don't thrash the timer
            owner._active = v
            # DEFINITIVE run-forever fix: STOP the animation timer entirely while inactive. With the flag
            # alone, FuncAnimation still fires and calls canvas.draw_idle() every interval — which keeps
            # trying to repaint the occluded window ("trying to update but can't" → the crash). Stopping
            # the event source means ZERO repaint attempts while unfocused/hidden; restart on return.
            ani = getattr(owner, "_ani", None)
            src = getattr(ani, "event_source", None) if ani is not None else None
            if src is not None:
                try:
                    (src.start if v else src.stop)()
                except Exception:
                    pass
        top.bind("<FocusIn>",  lambda e: _set(True),  add="+")
        top.bind("<FocusOut>", lambda e: _set(False), add="+")
        top.bind("<Map>",      lambda e: _set(True),  add="+")
        top.bind("<Unmap>",    lambda e: _set(False), add="+")
        top.bind("<Visibility>", lambda e: _set(getattr(e, "state", "") != "VisibilityFullyObscured"), add="+")
    except Exception:
        owner._active = True                        # non-Tk backend → never pause (safe default)


def _wave_correlate_3d(vg):
    """3D CORRELATION cross-reference: convolve the dot/voxel field with a separable 1-2-1 smoothing
    kernel along all three axes, so the underlying WAVE SHAPE emerges from the individually-noisy
    sampled points. Vectorised (np.roll) → fast enough per frame. Returns the correlated wave field
    (same shape). Honest: this is a real low-pass correlation of the measured field — it denoises the
    structure the dots sample, it does not invent anything (empty space stays empty)."""
    v = np.asarray(vg, dtype=np.float32)
    if v.ndim != 3:
        return v
    for axis in range(3):                                    # separable 1-2-1 kernel per axis
        v = (np.roll(v, 1, axis=axis) + 2.0 * v + np.roll(v, -1, axis=axis)) * 0.25
    return v


def _wave_energy_slices(vs, n=5):
    """Pick the n most-energetic depth (z) slices of the correlated field — where the wave structure
    is strongest — so the overlaid contour curves trace the real internal shape, not empty space."""
    vs = np.asarray(vs)
    if vs.ndim != 3:
        return []
    e = vs.sum(axis=(0, 1))                                  # energy per z-slice
    if float(e.max()) <= 0.0:
        return []
    return sorted(int(z) for z in np.argsort(e)[-int(n):])


def _decode_jpg_capped(raw, max_edge=1536):
    """RUN-FOREVER MEMORY FIX: decode a JPEG to a uint8 HxWx3 array with the long edge capped to
    `max_edge`, WITHOUT ever materialising the full-resolution array.

    Why this exists: GOES full-disk GeoColor / Band-13 .jpg from the NESDIS CDN is served at
    10848×10848 = 117,679,104 px → ~336 MB as a uint8 RGB array (and PIL raises a
    DecompressionBombWarning at that size). The geostationary engine holds FOUR of them, so a naive
    `imread` pins ~1.4 GB resident and spikes ~2.8 GB during each 10-min refresh → on a loaded
    machine that is the documented whole-system crash when the window is refocused mid-refresh.

    PIL's `draft("RGB", (max_edge, max_edge))` instructs the libjpeg decoder to use native DCT
    scaling (1/2, 1/4, 1/8) DURING decode, so the giant array is never allocated — we get the real
    satellite pixels straight at display resolution. NO FALSE DATA: this is a pure resample of the
    genuine imagery (same picture, fewer pixels), nothing invented. ~336 MB → ~7 MB per image.
    """
    import io as _io
    try:
        from PIL import Image as _Im
        _prev = getattr(_Im, "MAX_IMAGE_PIXELS", None)
        _Im.MAX_IMAGE_PIXELS = None                      # we cap via draft → bomb-guard not needed
        try:
            im = _Im.open(_io.BytesIO(raw))
            try:
                im.draft("RGB", (int(max_edge), int(max_edge)))   # DCT-scale decode (cheap, no full array)
            except Exception:
                pass
            im = im.convert("RGB")
            w, h = im.size
            scale = max(w, h) / float(max_edge)
            if scale > 1.0:                              # belt-and-suspenders exact cap after draft
                im = im.resize((max(1, int(round(w / scale))), max(1, int(round(h / scale)))),
                               _Im.BILINEAR)
            arr = np.asarray(im, dtype=np.uint8)
            try: im.close()
            except Exception: pass
            return np.ascontiguousarray(arr[..., :3])
        finally:
            _Im.MAX_IMAGE_PIXELS = _prev
    except Exception:
        # Fallback (PIL missing): full decode then immediate decimate + free. Still bounded RSS.
        import matplotlib.image as _mi
        a = _mi.imread(_io.BytesIO(raw), format="jpg")
        if a.dtype != np.uint8:
            a = (np.clip(a, 0.0, 1.0) * 255).astype(np.uint8) if float(a.max()) <= 1.0 else a.astype(np.uint8)
        H, W = a.shape[:2]
        s = int(np.ceil(max(H, W) / float(max_edge)))
        if s > 1:
            a = a[::s, ::s]
        out = np.ascontiguousarray(a[..., :3])
        del a
        return out


class World3DViewer:
    """Pass 25: Walkable 3-D spatial world (Halo-Forge / Oracle-mode style).

    Opens a SEPARATE maximised window that renders the live voxel world as a navigable
    3-D scene the operator can fly through. Two backends, auto-selected:
      • PyVista (if installed): true GPU first-person fly-through of the voxel volume.
      • matplotlib (always): WASD/arrow keyboard fly-through + mouse orbit/zoom of the
        voxel point-cloud, person blobs, ground-truth markers and the room box.

    The viewer reads a shared snapshot dict (voxel grid + detected blobs + ground-truth
    + accuracy) that the main fuser refreshes each frame, so the world stays live while
    the user navigates. Pure-stdlib for the matplotlib path — no new mandatory deps.
    """

    def __init__(self, fuser):
        self.fuser = fuser
        self.backend = "pyvista" if PYVISTA_AVAILABLE else "matplotlib"
        # Free-fly camera state (world units = voxels)
        self.cam = np.array([VOXEL_RES * 0.5, -VOXEL_RES * 0.8, VOXEL_RES * 0.6], dtype=float)
        self.yaw = 90.0      # looking +Y (into the scene)
        self.pitch = -20.0
        self.move_step = 1.5
        self.look_step = 6.0
        self._zoom_fov = 65.0    # field-of-view in degrees for display label
        self._walk_phase = 0.0   # walking animation phase for avatar
        self._frame_idx = 0      # animation frame counter
        self._fig = None
        self._ax = None
        self._ani = None
        self._pv_plotter = None

    # ── matplotlib backend ────────────────────────────────────────────────────
    def _look_target(self):
        ry, rp = np.radians(self.yaw), np.radians(self.pitch)
        d = np.array([np.cos(rp) * np.cos(ry), np.cos(rp) * np.sin(ry), np.sin(rp)])
        return self.cam + d * 10.0

    def _on_key(self, event):
        k = (event.key or "").lower()
        # v202: forward navigation keys to the reconstruction engine's canonical free camera
        # (validated FreeCameraController) so pose + breadcrumb trail are tracked engine-side.
        try:
            _wr = getattr(self.fuser, "world_recon", None)
            if _wr is not None and getattr(_wr, "free_cam", None) is not None:
                _wr.free_cam_key(k)
        except Exception:
            pass
        ry = np.radians(self.yaw)
        fwd = np.array([np.cos(ry), np.sin(ry), 0.0])
        right = np.array([np.sin(ry), -np.cos(ry), 0.0])
        if k == "w":   self.cam += fwd * self.move_step
        elif k == "s": self.cam -= fwd * self.move_step
        elif k == "a": self.cam -= right * self.move_step
        elif k == "d": self.cam += right * self.move_step
        elif k in ("q", "pagedown"): self.cam[2] -= self.move_step
        elif k in ("e", "pageup"):   self.cam[2] += self.move_step
        elif k == "left":  self.yaw -= self.look_step
        elif k == "right": self.yaw += self.look_step
        elif k == "up":    self.pitch = min(89, self.pitch + self.look_step)
        elif k == "down":  self.pitch = max(-89, self.pitch - self.look_step)
        elif k == "r":
            # CRASH FIX: reset the CAMERA in place. (Previously this called self.__init__() which nulled
            # self._ax AND spawned a brand-new figure + FuncAnimation every press — the old animation kept
            # firing on a torn-down axis → 'NoneType.cla()' crash, and each press leaked a figure+animation
            # → resource exhaustion that could take down the machine after a while. Reset fields only.)
            self.cam = np.array([VOXEL_RES * 0.5, -VOXEL_RES * 0.8, VOXEL_RES * 0.6], dtype=float)
            self.yaw, self.pitch, self.move_step = 90.0, -20.0, 1.5
        elif k in ("+", "="):  self.move_step = min(8.0, self.move_step * 1.3)  # zoom speed up
        elif k == "-":         self.move_step = max(0.2, self.move_step * 0.77)  # zoom speed down
        elif k == "z":         self.cam += fwd * self.move_step * 3.0   # fast zoom in
        elif k == "x":         self.cam -= fwd * self.move_step * 3.0   # fast zoom out
        elif k == "k":
            # T3-6: record a camera keyframe for the flythrough path.
            wr = getattr(self.fuser, "world_recon", None)
            if wr is not None:
                wr.add_keyframe(self.cam.tolist(), self._look_target().tolist())

    def _draw(self, _frame):
        # CRASH FIX: the axis/figure can be None transiently (e.g. just after a camera reset or during
        # teardown). Drawing then raised 'NoneType.cla()' inside the Tk timer callback and killed the
        # render loop. Guard it — if the axis isn't ready this frame, skip cleanly.
        if self._ax is None or self._fig is None:
            return
        # RUN-FOREVER: when the window is unfocused/occluded, skip the expensive repaint entirely — this
        # is the case that was crashing the machine (repaints backing up while another window is focused).
        if not getattr(self, "_active", True):
            return
        # STABILITY (run-forever): never let draws pile up. If the previous frame is still rendering
        # (slow GPU / window occluded / another window focused), SKIP this one — this is the #1 fix for
        # the animation backing up and exhausting the X server / memory when the window can't repaint.
        if getattr(self, "_drawing", False):
            return
        # Also skip entirely if the window is hidden/iconified — no point rendering into the void, and
        # this is exactly the "another window is open / can't update" case that was crashing the machine.
        try:
            _mgr = getattr(self._fig.canvas, "manager", None)
            _win = getattr(_mgr, "window", None)
            if _win is not None and hasattr(_win, "wm_state") and _win.wm_state() == "iconic":
                return
        except Exception:
            pass
        self._drawing = True
        try:
            self._draw_impl(_frame)
            # run-forever insurance: periodic GC to stop slow matplotlib/numpy fragmentation building up.
            self._gc_ctr = getattr(self, "_gc_ctr", 0) + 1
            if self._gc_ctr % 150 == 0:
                import gc as _gc
                _gc.collect()
        finally:
            self._drawing = False

    def _draw_impl(self, _frame):
        ax = self._ax
        ax.cla()
        ax.set_facecolor(NEPA_THEME['panel'])
        snap = getattr(self.fuser, "_world_snapshot", None)
        # Tab B shows the FUSED multi-instrument big picture when available.
        vg = (snap.get("fused_voxel") if snap and snap.get("fused_voxel") is not None
              else (snap["voxel"] if snap else self.fuser.voxel_grid))
        vg = np.asarray(vg)
        vmax = float(vg.max()) + 1e-9
        # DETAILED DOT-GRID: render the voxel field as an organized grid of dots that PAINTS the
        # image — denser + intensity-scaled (dot size & colour both follow value), so the structure
        # reads as a picture rather than a few hot spots. (Was 0.45*vmax / 1500 pts → looked sparse.)
        thr = 0.12 * vmax                                  # lower floor → much more real structure shown
        xs, ys, zs = np.where(vg > thr)
        if len(xs) > 0:
            c = vg[xs, ys, zs]
            budget = 4500                                  # strongest dots (detailed yet light enough to run forever)
            if len(xs) > budget:
                keep = np.argpartition(c, -budget)[-budget:]
                xs, ys, zs, c = xs[keep], ys[keep], zs[keep], c[keep]
            cn = c / vmax                                  # normalised intensity 0..1
            sizes = 5.0 + 34.0 * (cn ** 1.5)               # bigger dot = stronger signal (painted depth)
            # PERF: depthshade=False — depth-sorting 8000 pts every frame is a 3D-scatter bottleneck;
            # the intensity colour+size already conveys depth, so we drop it for a real per-frame speedup.
            ax.scatter(xs, ys, zs, c=c, cmap='turbo', s=sizes,
                       alpha=0.72, depthshade=False, edgecolors='none')
        # WAVE-SHAPE CURVES (MULTI-SCALE 3D CORRELATION MATRIX): cross-reference each graphed dot with
        # a 3D correlation applied at THREE smoothing scales (fine / medium / coarse) to expose the
        # continuous wave the discrete dots SAMPLE, then paint it with MANY flowing line curvatures:
        #   (1) dense stacked iso-contours (5 levels) at the most energetic depth slices — the wave's
        #       layered internal shape;
        #   (2) THREE orthogonal centroid "spines" (along x, y AND z) — the full 3D fluidity skeleton
        #       threading the volume we are inside, not just a single axis;
        #   (3) gradient flow-ribbons at strong voxels — short segments oriented along the local
        #       correlated-field gradient, depicting the internal wave-flow direction (fluidity).
        # All from the real measured field — correlated/denoised, never invented (empty stays empty).
        try:
            if vmax > 1e-6 and vg.ndim == 3:
                vs1 = _wave_correlate_3d(vg)                        # fine scale
                vs  = _wave_correlate_3d(vs1)                       # medium (2×) — primary wave field
                vs3 = _wave_correlate_3d(_wave_correlate_3d(vs))    # coarse (4×) — large-scale flow
                nx, ny, nz = vs.shape
                GX, GY = np.meshgrid(np.arange(nx), np.arange(ny), indexing='ij')
                import matplotlib.cm as _cm
                # (1) dense layered iso-contours at the most energetic Z slices
                zsl = _wave_energy_slices(vs, n=12)                 # 12 slices × 5 levels = far more detail
                for _i, zi in enumerate(zsl):
                    sl = vs[:, :, zi]; smax = float(sl.max())
                    if smax <= 1e-6:
                        continue
                    col = _cm.turbo(0.12 + 0.76 * (_i / max(1, len(zsl) - 1)))
                    ax.contour(GX, GY, sl,
                               levels=[smax * 0.25, smax * 0.42, smax * 0.60, smax * 0.76, smax * 0.90],
                               zdir='z', offset=zi, colors=[col], alpha=0.55, linewidths=0.7)
                # (2) THREE orthogonal flow spines — centroid curve along each axis (full 3D fluidity)
                def _flow_spine(field, axis):
                    pts = []
                    for k in range(field.shape[axis]):
                        sl = np.take(field, k, axis=axis); w = float(sl.sum())
                        if w <= 1e-6:
                            continue
                        ii, jj = np.indices(sl.shape)
                        ci = float((ii * sl).sum() / w); cj = float((jj * sl).sum() / w)
                        pts.append((k, ci, cj) if axis == 0 else
                                   (ci, k, cj) if axis == 1 else (ci, cj, k))
                    return np.array(pts) if len(pts) >= 3 else None
                _spine_cols = ('#ff7be0', '#7bff9e', '#00ffe0')
                for _axn in (0, 1, 2):
                    sp = _flow_spine(vs3, _axn)
                    if sp is not None:
                        ax.plot(sp[:, 0], sp[:, 1], sp[:, 2], color=_spine_cols[_axn],
                                lw=1.8, alpha=0.85, solid_capstyle='round')
                        ax.scatter(sp[:, 0], sp[:, 1], sp[:, 2], c=_spine_cols[_axn], s=7, alpha=0.5)
                # (3) gradient flow-ribbons: one Line3DCollection (single fast artist) of short segments
                #     along the local field gradient at the strongest voxels → internal wave-flow lines.
                try:
                    from mpl_toolkits.mplot3d.art3d import Line3DCollection
                    gXf, gYf, gZf = np.gradient(vs)
                    thr2 = 0.45 * float(vs.max())
                    sx, sy, sz = np.where(vs > thr2)
                    if len(sx) > 0:
                        budget2 = 350                              # capped → runs forever, still dense
                        if len(sx) > budget2:
                            vv = vs[sx, sy, sz]
                            keep = np.argpartition(vv, -budget2)[-budget2:]
                            sx, sy, sz = sx[keep], sy[keep], sz[keep]
                        gv = np.stack([gXf[sx, sy, sz], gYf[sx, sy, sz], gZf[sx, sy, sz]], axis=1)
                        gv = gv / (np.linalg.norm(gv, axis=1, keepdims=True) + 1e-9) * 1.6
                        p0 = np.stack([sx, sy, sz], axis=1).astype(float)
                        segs = np.stack([p0 - gv * 0.5, p0 + gv * 0.5], axis=1)
                        ax.add_collection3d(Line3DCollection(segs, colors='#66e0ff',
                                                             linewidths=0.6, alpha=0.5))
                except Exception:
                    pass
        except Exception:
            pass
        # Real mapped nodes (router / LAN host / AP) OR detected blobs, colour by kind
        _kc = {"router": "#ff3355", "lan_host": "#33ddff", "ap": "#ffdd33", "csi_echo": "#ff66ff"}
        for b in (snap.get("blobs", []) if snap else []):
            cx, cy, cz = b["centroid"]
            col = _kc.get(b.get("kind", ""), "#ff3355")
            ax.scatter([cx], [cy], [cz], c=col, s=110, marker='o',
                       edgecolors='white', alpha=0.92)
            lbl = b.get("kind", "")[:3] + f" {b['range_m']:.1f}m"
            ax.text(cx, cy, cz + 2, lbl, color=col, fontsize=7)
        # Ground-truth markers (sim-validate test mode only)
        for gt in (snap.get("ground_truth", []) if snap else []):
            gx, gy, gz = gt["vox"]
            ax.scatter([gx], [gy], [gz], c='#00ff66', s=140, marker='P',
                       edgecolors='white', alpha=0.95)
            ax.text(gx, gy, gz - 2, f"GT:{gt['id']}", color=NEPA_THEME['success'], fontsize=8)
        # Pass 27: instrument vantage positions (the "cameras") + multilateration fixes
        for inst in (snap.get("instrument_objs", []) if snap else []):
            ip = np.array(inst.pos) / M_PER_VOXEL
            ax.scatter([ip[0]], [ip[1]], [ip[2]], c='#888888', s=60, marker='^',
                       edgecolors='cyan', alpha=0.8)
        for fx in (snap.get("fixes", []) if snap else []):
            fv = fx["vox"]
            ax.scatter([fv[0]], [fv[1]], [fv[2]], c='#ffffff', s=160, marker='*',
                       edgecolors='#00ff66', linewidths=1.0, alpha=1.0)
            ax.text(fv[0], fv[1], fv[2] + 2,
                    f"FIX ±{fx['err_m']:.1f}m", color=NEPA_THEME['text_bright'], fontsize=7)
        # Room box (full wireframe cube for spatial reference)
        R = VOXEL_RES
        corners = [(0,0,0),(R,0,0),(R,R,0),(0,R,0),(0,0,R),(R,0,R),(R,R,R),(0,R,R)]
        edges = [(0,1),(1,2),(2,3),(3,0),(4,5),(5,6),(6,7),(7,4),(0,4),(1,5),(2,6),(3,7)]
        for a, b in edges:
            ax.plot(*zip(corners[a], corners[b]), color='#225522', lw=0.6, alpha=0.4)
        ax.set_xlim(0, R); ax.set_ylim(0, R); ax.set_zlim(0, R)
        try:
            ax.set_box_aspect((1, 1, 1))   # FIX: equal X/Y/Z so the world is NOT squished/distorted
        except Exception:
            pass
        try:
            ax.view_init(elev=self.pitch, azim=self.yaw)
        except Exception:
            pass
        acc = (snap.get("accuracy", None) if snap else None)
        n_nodes = len(snap.get("real_nodes", [])) if snap else 0
        n_inst = len(snap.get("instrument_objs", [])) if snap else 0
        n_fix = len(snap.get("fixes", [])) if snap else 0
        if acc is not None:
            tag = f"SIM-VALIDATE · matrix accuracy {acc:.0f}%"
        else:
            tag = (f"TAB B · FUSED BIG PICTURE · {n_inst} instruments · "
                   f"{n_nodes} nodes · {n_fix} multilat fixes")
        # ── SELF AVATAR: bright cone at camera position pointing in yaw direction ──
        self._frame_idx += 1
        self._walk_phase += 0.18  # walking cycle
        cx, cy, cz = self.cam
        # Avatar body (bright sphere at camera)
        ax.scatter([cx], [cy], [cz], c='#00ffff', s=320, marker='o',
                   edgecolors='white', linewidths=2.0, alpha=1.0, zorder=10)
        # Look direction indicator (short line showing facing)
        ry_r = np.radians(self.yaw)
        rp_r = np.radians(self.pitch)
        look_dx = np.cos(rp_r) * np.cos(ry_r) * 4.0
        look_dy = np.cos(rp_r) * np.sin(ry_r) * 4.0
        look_dz = np.sin(rp_r) * 4.0
        ax.plot([cx, cx + look_dx], [cy, cy + look_dy], [cz, cz + look_dz],
                color='#00ffff', lw=2.5, alpha=0.9)
        # Walking bob animation — up/down bob on z
        bob_z = np.sin(self._walk_phase) * 0.5
        ax.scatter([cx], [cy], [cz + bob_z + 3.0], c='#ffffff', s=80, marker='^',
                   edgecolors='#00ffff', alpha=0.85)
        ax.text(cx, cy, cz + 5.0, "YOU", color='#00ffff', fontsize=8, ha='center',
                fontweight='bold')
        # ── SIGNAL RAYS: draw lines from each instrument to detected targets ──
        insts = snap.get("instrument_objs", []) if snap else []
        blobs = snap.get("blobs", []) if snap else []
        fixes = snap.get("fixes", []) if snap else []
        _ray_colors = ['#ff330088', '#33ff6688', '#3366ff88', '#ffaa0088']
        for ii, inst in enumerate(insts[:6]):
            ip = np.array(inst.pos) / M_PER_VOXEL
            rc = _ray_colors[ii % len(_ray_colors)]
            # Ray to each fix (multilateration result)
            for fx in fixes[:3]:
                fv = fx["vox"]
                ax.plot([ip[0], fv[0]], [ip[1], fv[1]], [ip[2], fv[2]],
                        color=rc[:7], lw=0.8, alpha=0.35, linestyle='--')
            # Ray to each blob (signal carrier → detected node)
            for bl in blobs[:4]:
                bc = bl["centroid"]
                ax.plot([ip[0], bc[0]], [ip[1], bc[1]], [ip[2], bc[2]],
                        color=rc[:7], lw=0.6, alpha=0.25, linestyle=':')
        # ── FMCW POINT CLOUD from P83 ──
        fmcw_pts = (snap.get("fmcw_points") if snap else None)
        if fmcw_pts is not None and len(fmcw_pts) > 0:
            fpts = np.asarray(fmcw_pts)
            ax.scatter(fpts[:, 0], fpts[:, 1], fpts[:, 2],
                       c='#ff00ff', s=22, alpha=0.7, marker='D',
                       edgecolors='none', label='FMCW')
        # ── POSE SKELETON from P83 PoseNet ──
        pose_joints = (snap.get("pose_joints") if snap else None)
        if pose_joints is not None and len(pose_joints) > 0:
            J = np.asarray(pose_joints)
            # scale joints to voxel space (they arrive in metres)
            J_v = J / M_PER_VOXEL
            # COCO skeleton bone pairs (17 joints)
            _bones = [(0,1),(0,2),(1,3),(2,4),(5,6),(5,7),(6,8),(7,9),(8,10),
                      (5,11),(6,12),(11,12),(11,13),(12,14),(13,15),(14,16)]
            ax.scatter(J_v[:, 0], J_v[:, 1], J_v[:, 2],
                       c='#00ff88', s=28, alpha=0.9)
            for a, b in _bones:
                if a < len(J_v) and b < len(J_v):
                    ax.plot([J_v[a,0], J_v[b,0]], [J_v[a,1], J_v[b,1]],
                            [J_v[a,2], J_v[b,2]], color=NEPA_THEME['success'], lw=1.5, alpha=0.8)
        # ── ZOOM / SPEED OVERLAY ──
        speed_label = f"spd:{self.move_step:.1f}  Z=zoom±  +/−=speed"
        ax.set_title(f"N.E.P.A. 3D WORLD — WASD/QE/arrows · Z/X zoom · +/− speed · R reset   |   {tag}   |   {speed_label}",
                     color=NEPA_THEME['accent'], fontsize=9)
        ax.tick_params(colors=NEPA_THEME['text_dim'], labelsize=6)

    def launch(self):
        """Open the walkable world window (non-blocking; runs alongside the main UI)."""
        if self.backend == "pyvista":
            try:
                self._launch_pyvista()
                return
            except Exception as e:
                log.warning(f"[WORLD] PyVista launch failed ({e}); falling back to matplotlib")
                self.backend = "matplotlib"
        self._launch_matplotlib()

    def _launch_matplotlib(self):
        self._fig = plt.figure("N.E.P.A. — 3D WORLD (WASD fly-through)", figsize=(16, 11))
        self._fig.patch.set_facecolor(NEPA_THEME['bg_alt'])
        self._ax = self._fig.add_subplot(111, projection='3d')
        # expand the 3D scene to fill the window (minimal margins) so the dot-grid world is large
        try:
            self._fig.subplots_adjust(left=0.02, right=0.98, top=0.97, bottom=0.03)
        except Exception:
            pass
        self._fig.canvas.mpl_connect('key_press_event', self._on_key)
        _bind_window_active(self._fig, self)    # pause rendering when unfocused/occluded (run-forever)
        # STABILITY: 5 fps (200 ms) for the heavy 3D world — a navigable fly-through reads fine at
        # 5 fps and this hugely cuts GPU/CPU load so it can run forever without the renderer backing up.
        self._ani = FuncAnimation(self._fig, self._draw, interval=200,
                                  blit=False, cache_frame_data=False)
        # Pass 26: raise the world window to the front so it is not hidden behind the
        # maximised main dashboard (different WMs/backends stack new windows behind).
        try:
            mgr = self._fig.canvas.manager
            self._fig.show()
            win = getattr(mgr, "window", None)
            if win is not None:
                for fn in ("raise_", "activateWindow", "showMaximized"):
                    try:
                        getattr(win, fn)()
                    except Exception:
                        pass
                # Tk backend
                try:
                    win.attributes('-topmost', 1); win.attributes('-topmost', 0)
                except Exception:
                    pass
        except Exception:
            pass
        log.info("[WORLD] 3D world window OPEN — fly with WASD · QE up/down · arrows look · R reset")

    def _launch_pyvista(self):
        """GPU first-person voxel world via PyVista (optional)."""
        self._pv_plotter = _pv.Plotter(title="N.E.P.A. — 3D WORLD (GPU)")
        self._pv_plotter.set_background("black")

        def _refresh():
            snap = getattr(self.fuser, "_world_snapshot", None)
            vg = np.asarray(snap["voxel"] if snap else self.fuser.voxel_grid)
            self._pv_plotter.clear()
            grid = _pv.ImageData(dimensions=np.array(vg.shape) + 1)
            grid.cell_data["intensity"] = vg.flatten(order="F")
            thr = 0.45 * (float(vg.max()) + 1e-9)
            vol = grid.threshold(thr, scalars="intensity")
            if vol.n_cells > 0:
                self._pv_plotter.add_mesh(vol, cmap="inferno", opacity=0.6,
                                          scalars="intensity")
            for gt in (snap.get("ground_truth", []) if snap else []):
                self._pv_plotter.add_mesh(_pv.Sphere(radius=1.0, center=gt["vox"]),
                                          color="#00ff66")
            self._pv_plotter.add_text("WASD/mouse fly-through — GPU voxel world",
                                      font_size=10, color="cyan")
        _refresh()
        self._pv_plotter.add_callback(lambda *_: _refresh(), interval=200)
        self._pv_plotter.show(interactive_update=True)
        log.info("[WORLD] PyVista GPU 3D world open")


class PlanetMapEngine:
    """v97: REAL planet-scale map ingestion — the honest 'satellite mapping / map the world
    at distance'. A home router is NOT a satellite, but real satellites + ground surveys
    already scanned the planet and publish the result: this engine streams genuine
    OpenStreetMap raster tiles (and can be extended to Sentinel-2 imagery / SRTM elevation)
    for the machine's real geolocation, stitched into a navigable zoom/pan map with millions
    of REAL pixels. Nothing is fabricated. The node's own position (IP-derived ~city accuracy,
    or real GNSS if a receiver is on the instrument bus) is pinned. Detected RF emitters are
    reported by real RSSI/range only — bearing is unknown from one antenna, so they are NEVER
    placed at invented coordinates."""

    # Real public tile services. 'satellite' = genuine orbital/aerial imagery — the planet-
    # scanning instruments the directive calls for already exist (they're in orbit), and their
    # imagery is public. (url_template, tile_format, human label)
    BASEMAPS = {
        "satellite": ("https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/"
                      "MapServer/tile/{z}/{y}/{x}", "jpeg", "ESRI World Imagery — real satellite/aerial"),
        "street":    ("https://tile.openstreetmap.org/{z}/{x}/{y}.png", "png",
                      "OpenStreetMap — street cartography"),
        "terrain":   ("https://server.arcgisonline.com/ArcGIS/rest/services/World_Terrain_Base/"
                      "MapServer/tile/{z}/{y}/{x}", "jpeg", "ESRI World Terrain — relief"),
    }
    UA = "NEPA-PlanetMap/1.0 (humanitarian research; contact: local)"

    def __init__(self, cache_dir="nepa_tiles"):
        self.cache_dir = cache_dir
        try:
            os.makedirs(cache_dir, exist_ok=True)
        except Exception:
            pass
        self.lat = None
        self.lon = None
        self.city = ""
        self.geo_source = "none"
        self.basemap = "satellite"    # default to real satellite imagery (planet-scan view)
        self.zoom = 15
        self.span = 2                 # (2*span+1)^2 tiles per fetch
        self.map_img = None           # stitched (H,W,3) float image in [0,1]
        self.map_meta = {}
        self.elev_grid = None         # (n,n) REAL terrain elevation in metres (DEM)
        self.elev_meta = {}
        self._elev_fetching = False
        self.buildings = None         # list of REAL OSM building footprints (extruded in 3D)
        self.buildings_meta = {}
        self._bld_fetching = False
        self.online = False
        self._lock = threading.Lock()
        self._fetching = False
        self._last_err = ""

    def geolocate(self):
        """Real, ~city-accuracy location from public IP geolocation (no GPS hardware needed)."""
        import urllib.request, json
        try:
            req = urllib.request.Request("https://ipinfo.io/json",
                                         headers={"User-Agent": self.UA})
            d = json.loads(urllib.request.urlopen(req, timeout=6).read())
            loc = d.get("loc", "")
            if loc and "," in loc:
                self.lat, self.lon = [float(x) for x in loc.split(",")]
                self.city = d.get("city", "")
                self.geo_source = "ip_approx"
                self.online = True
                return True
        except Exception as e:
            self._last_err = f"geolocate: {type(e).__name__}: {str(e)[:50]}"
        return False

    def set_location(self, lat, lon, source="manual"):
        self.lat, self.lon = float(lat), float(lon)
        self.geo_source = source

    @staticmethod
    def _deg2num(lat, lon, z):
        import math
        lat_r = math.radians(lat); n = 2.0 ** z
        return ((lon + 180.0) / 360.0 * n,
                (1.0 - math.asinh(math.tan(lat_r)) / math.pi) / 2.0 * n)

    @staticmethod
    def _num2deg(xt, yt, z):
        import math
        n = 2.0 ** z
        lon = xt / n * 360.0 - 180.0
        lat = math.degrees(math.atan(math.sinh(math.pi * (1 - 2 * yt / n))))
        return lat, lon

    @staticmethod
    def _norm(img):
        """Normalise any decoded tile to float32 [0,1] RGB (ESRI JPEG is uint8, OSM PNG float)."""
        if img is None:
            return None
        if img.dtype == np.uint8:
            img = img.astype(np.float32) / 255.0
        return img

    def _fetch_tile(self, z, x, y):
        import io
        try:
            import matplotlib.image as mpimg
        except Exception:
            return None
        url_t, fmt, _lbl = self.BASEMAPS.get(self.basemap, self.BASEMAPS["satellite"])
        ext = "png" if fmt == "png" else "jpg"
        p = os.path.join(self.cache_dir, f"{self.basemap}_{z}_{x}_{y}.{ext}")
        if os.path.exists(p):
            try:
                return self._norm(mpimg.imread(p))
            except Exception:
                pass
        import urllib.request
        try:
            req = urllib.request.Request(url_t.format(z=z, x=x, y=y),
                                         headers={"User-Agent": self.UA})
            data = urllib.request.urlopen(req, timeout=8).read()
            try:
                with open(p, "wb") as fh:
                    fh.write(data)
            except Exception:
                pass
            return self._norm(mpimg.imread(io.BytesIO(data), format=fmt))
        except Exception as e:
            self._last_err = f"tile {z}/{x}/{y}: {type(e).__name__}"
            return None

    def set_basemap(self, name):
        if name in self.BASEMAPS:
            self.basemap = name
            self.build_map_async()

    def cycle_basemap(self):
        keys = list(self.BASEMAPS.keys())
        self.set_basemap(keys[(keys.index(self.basemap) + 1) % len(keys)])

    def build_map(self, zoom=None, span=None):
        """Stitch a (2*span+1)^2 grid of REAL OSM tiles centred on the node location."""
        if self.lat is None and not self.geolocate():
            return None
        z = int(zoom or self.zoom); sp = int(span or self.span)
        xt, yt = self._deg2num(self.lat, self.lon, z)
        xc, yc = int(xt), int(yt); n = 2 ** z
        ok = 0; total = 0; rows = []
        for dy in range(-sp, sp + 1):
            row = []
            for dx in range(-sp, sp + 1):
                total += 1
                t = self._fetch_tile(z, (xc + dx) % n, (yc + dy) % n)
                if t is None:
                    t = np.zeros((256, 256, 3), np.float32)
                else:
                    ok += 1
                    if t.ndim == 2:
                        t = np.stack([t] * 3, -1)
                    t = t[..., :3]
                row.append(t.astype(np.float32))
            rows.append(np.concatenate(row, axis=1))
        img = np.concatenate(rows, axis=0).astype(np.float32)
        lat_n, lon_w = self._num2deg(xc - sp, yc - sp, z)
        lat_s, lon_e = self._num2deg(xc + sp + 1, yc + sp + 1, z)
        with self._lock:
            self.map_img = img
            self.zoom = z; self.span = sp
            self.map_meta = {"zoom": z, "tiles_ok": ok, "tiles_total": total,
                             "lat": self.lat, "lon": self.lon, "city": self.city,
                             "bounds": (lat_n, lat_s, lon_w, lon_e),
                             "px": (int(img.shape[1]), int(img.shape[0])),
                             "tlx": xc - sp, "tly": yc - sp}
        return img

    def build_map_async(self, zoom=None, span=None):
        if self._fetching:
            return
        def _w():
            self._fetching = True
            try:
                self.build_map(zoom, span)
            except Exception as e:
                self._last_err = f"build: {type(e).__name__}"
            finally:
                self._fetching = False
        threading.Thread(target=_w, daemon=True).start()

    def zoom_in(self):
        self.build_map_async(zoom=min(19, self.zoom + 1))

    def zoom_out(self):
        self.build_map_async(zoom=max(2, self.zoom - 1))

    def latlon_to_px(self, lat, lon):
        """Pixel coords of a real lat/lon within the stitched image (for pinning real points)."""
        with self._lock:
            if not self.map_meta:
                return None
            z = self.map_meta["zoom"]; tlx = self.map_meta["tlx"]; tly = self.map_meta["tly"]
        xt, yt = self._deg2num(lat, lon, z)
        return (xt - tlx) * 256.0, (yt - tly) * 256.0

    def meters_per_pixel(self):
        """Web-Mercator ground resolution at the map's zoom/latitude — lets real range
        estimates (metres) be drawn to scale on the map as range rings."""
        import math
        with self._lock:
            z = self.map_meta.get("zoom", self.zoom)
            lat = self.lat or 0.0
        return 156543.03392 * math.cos(math.radians(lat)) / (2.0 ** z)

    def fetch_elevation_grid(self, n=24):
        """Fetch an n×n grid of REAL terrain elevations (open-meteo / SRTM DEM) spanning the
        current map's geographic bounds → a real Digital Elevation Model. This is the honest
        'image the ground from above': measured topography, draped with real satellite imagery
        in the 3D terrain view. Nothing synthesised."""
        import urllib.request, json
        with self._lock:
            meta = dict(self.map_meta)
        if not meta:
            if not self.build_map():
                return None
            with self._lock:
                meta = dict(self.map_meta)
        lat_n, lat_s, lon_w, lon_e = meta["bounds"]
        lats = np.linspace(lat_n, lat_s, n)
        lons = np.linspace(lon_w, lon_e, n)
        LAT, LON = np.meshgrid(lats, lons, indexing="ij")     # (n,n) row=lat, col=lon
        fl, fo = LAT.ravel(), LON.ravel()
        elev = np.full(fl.shape, np.nan, dtype=np.float64)
        CH = 100
        for i in range(0, len(fl), CH):
            la = ",".join(f"{v:.5f}" for v in fl[i:i + CH])
            lo = ",".join(f"{v:.5f}" for v in fo[i:i + CH])
            url = f"https://api.open-meteo.com/v1/elevation?latitude={la}&longitude={lo}"
            try:
                req = urllib.request.Request(url, headers={"User-Agent": self.UA})
                d = json.loads(urllib.request.urlopen(req, timeout=15).read())
                ev = d.get("elevation", [])
                elev[i:i + len(ev)] = ev
            except Exception as e:
                self._last_err = f"elev: {type(e).__name__}"
        grid = elev.reshape(n, n)
        if np.all(np.isnan(grid)):
            return None
        with self._lock:
            self.elev_grid = grid
            self.elev_meta = {"n": n, "bounds": meta["bounds"], "zoom": meta["zoom"],
                              "lat": meta["lat"], "lon": meta["lon"],
                              "min": float(np.nanmin(grid)), "max": float(np.nanmax(grid)),
                              "relief": float(np.nanmax(grid) - np.nanmin(grid))}
        return grid

    def fetch_elevation_grid_async(self, n=24):
        if self._elev_fetching:
            return
        def _w():
            self._elev_fetching = True
            try:
                self.fetch_elevation_grid(n)
            except Exception as e:
                self._last_err = f"elev: {type(e).__name__}"
            finally:
                self._elev_fetching = False
        threading.Thread(target=_w, daemon=True).start()

    def fetch_buildings(self, n_max=400):
        """Fetch REAL OpenStreetMap building footprints (+ heights) in the current map bounds
        via Overpass. Footprints are real surveyed geometry; height is the real OSM tag where
        present (height / building:levels), else a clearly-flagged default extrusion. Converts
        to local metres around the node for 3D extrusion. This is the honest 'map buildings to
        extreme detail' — real surveyed structures, thousands of them."""
        import urllib.request, urllib.parse, json, math
        with self._lock:
            meta = dict(self.map_meta)
        if not meta:
            if not self.build_map():
                return None
            with self._lock:
                meta = dict(self.map_meta)
        lat_n, lat_s, lon_w, lon_e = meta["bounds"]
        q = (f'[out:json][timeout:25];(way["building"]'
             f'({lat_s:.5f},{lon_w:.5f},{lat_n:.5f},{lon_e:.5f}););out geom;')
        try:
            data = urllib.parse.urlencode({"data": q}).encode()
            req = urllib.request.Request("https://overpass-api.de/api/interpreter",
                                         data=data, headers={"User-Agent": self.UA})
            d = json.loads(urllib.request.urlopen(req, timeout=35).read())
        except Exception as e:
            self._last_err = f"overpass: {type(e).__name__}"
            return None
        lat0 = meta["lat"]; lon0 = meta["lon"]
        mx = 111320.0 * math.cos(math.radians(lat0))
        out = []
        for e in d.get("elements", []):
            g = e.get("geometry")
            if not g or len(g) < 3:
                continue
            tg = e.get("tags", {})
            h = None
            try:
                if "height" in tg:
                    h = float(str(tg["height"]).split()[0])
                elif "building:levels" in tg:
                    h = float(str(tg["building:levels"]).split()[0]) * 3.2
            except Exception:
                h = None
            est = (h is None or h <= 0)
            if est:
                h = 6.0                       # default ~2-storey extrusion (flagged)
            xy = [((pt["lon"] - lon0) * mx, (pt["lat"] - lat0) * 110540.0) for pt in g]
            cx = sum(x for x, _ in xy) / len(xy); cy = sum(y for _, y in xy) / len(xy)
            out.append({"xy": xy, "h": float(h), "est": bool(est), "d2": cx * cx + cy * cy})
        out.sort(key=lambda b: b["d2"])         # nearest to node first
        out = out[:n_max]
        with self._lock:
            self.buildings = out
            self.buildings_meta = {"n": len(out), "bounds": meta["bounds"],
                                   "tagged": sum(0 if b["est"] else 1 for b in out)}
        return out

    def fetch_buildings_async(self, n_max=400):
        if self._bld_fetching:
            return
        def _w():
            self._bld_fetching = True
            try:
                self.fetch_buildings(n_max)
            except Exception as e:
                self._last_err = f"bld: {type(e).__name__}"
            finally:
                self._bld_fetching = False
        threading.Thread(target=_w, daemon=True).start()

    def status(self):
        with self._lock:
            meta = dict(self.map_meta)
        return {"online": self.online, "geo_source": self.geo_source,
                "lat": self.lat, "lon": self.lon, "city": self.city,
                "zoom": self.zoom, "have_map": self.map_img is not None,
                "basemap": self.basemap,
                "basemap_label": self.BASEMAPS.get(self.basemap, ("", "", "?"))[2],
                "fetching": self._fetching, "meta": meta, "err": self._last_err}


class InstrumentMeshViewer:
    """Pass 27: TAB A — per-instrument list + individual sight.

    A separate window that shows EVERY instrument (router/AP/host) individually: a
    left-hand health list of all instruments and a right-hand grid of each instrument's
    own voxel projection (its individual 'camera view'). This is the multi-camera
    contact sheet — every sensor processed and shown on its own — complementing the
    fused big-picture world (Tab B / World3DViewer).
    """

    def __init__(self, fuser):
        self.fuser = fuser
        self._fig = None
        self._ani = None

    def _draw(self, _frame):
        fig = self._fig
        # STABILITY (run-forever): skip if torn down, unfocused/occluded, re-entrant, or window hidden.
        if fig is None or not getattr(self, "_active", True) or getattr(self, "_drawing", False):
            return
        try:
            _win = getattr(getattr(fig.canvas, "manager", None), "window", None)
            if _win is not None and hasattr(_win, "wm_state") and _win.wm_state() == "iconic":
                return
        except Exception:
            pass
        self._drawing = True
        try:
            self._draw_body(_frame)
        finally:
            self._drawing = False

    def _draw_body(self, _frame):
        fig = self._fig
        fig.clf()
        snap = getattr(self.fuser, "_world_snapshot", None)
        insts = (snap.get("instrument_objs", []) if snap else [])
        fig.patch.set_facecolor(NEPA_THEME['bg'])
        # Left column: instrument health list
        ax_list = fig.add_axes([0.01, 0.02, 0.30, 0.95]); ax_list.axis('off')
        ax_list.set_facecolor(NEPA_THEME['panel'])
        hdr = (f"INSTRUMENTS ({len(insts)})  — each processed individually\n"
               f"{'ID':<16}{'KIND':<9}{'RSSI':>6}{'RNG':>7}\n" + "─" * 40 + "\n")
        rows = []
        for i in insts[:24]:
            h = i.health()
            rows.append(f"{h['id'][:15]:<16}{h['kind'][:8]:<9}"
                        f"{h['rssi']:>6.0f}{h['range_m']:>6.1f}m")
        fixes = snap.get("fixes", []) if snap else []
        fixtxt = "\n\nMULTILAT FIXES:\n" + (
            "\n".join(f"  ({f['x']:.1f},{f['y']:.1f})m ±{f['err_m']:.1f} "
                      f"[{f['n_instruments']} instr]" for f in fixes)
            if fixes else "  (need ≥3 instruments)")
        ax_list.text(0.0, 1.0, hdr + "\n".join(rows) + fixtxt, va='top', ha='left',
                     family='monospace', fontsize=7, color='#33ddff',
                     transform=ax_list.transAxes)
        # Right grid: individual per-instrument voxel projection (top-down)
        n = len(insts)
        if n == 0:
            ax = fig.add_axes([0.34, 0.35, 0.62, 0.4]); ax.axis('off')
            ax.text(0.5, 0.5, "No instruments yet — scanning routers / APs …",
                    ha='center', va='center', color=NEPA_THEME['accent'], fontsize=11)
        else:
            cols = int(np.ceil(np.sqrt(n))); rows_g = int(np.ceil(n / cols))
            _kc = {"router": "Reds", "lan_host": "Blues", "ap": "YlOrBr", "sdr": "Greens"}
            for idx, inst in enumerate(insts[:16]):
                r, c = divmod(idx, cols)
                w = 0.62 / cols; hgt = 0.92 / rows_g
                ax = fig.add_axes([0.34 + c * w, 0.95 - (r + 1) * hgt, w * 0.92, hgt * 0.82])
                ax.set_facecolor(NEPA_THEME['panel'])
                proj = inst.grid.max(axis=2)   # top-down projection of THIS instrument
                ax.imshow(proj.T, origin='lower', cmap=_kc.get(inst.kind, 'viridis'),
                          aspect='auto', vmin=0, vmax=1)
                ax.set_title(f"{inst.id[:14]} {inst.rssi:.0f}dBm",
                             fontsize=6, color=NEPA_THEME['text'])
                ax.tick_params(labelsize=4, colors=NEPA_THEME['text_dim'])
        fig.suptitle("N.E.P.A. — TAB A: PER-INSTRUMENT SIGHT (each router/AP processed individually)",
                     color=NEPA_THEME['accent'], fontsize=11)

    def launch(self):
        self._fig = plt.figure("N.E.P.A. — INSTRUMENTS (per-instrument sight)", figsize=(15, 9))
        self._fig.patch.set_facecolor(NEPA_THEME['bg'])
        _bind_window_active(self._fig, self)   # pause repaint when unfocused/occluded
        self._ani = FuncAnimation(self._fig, self._draw, interval=250,
                                  blit=False, cache_frame_data=False)
        try:
            self._fig.show()
            win = getattr(self._fig.canvas.manager, "window", None)
            if win is not None:
                for fn in ("raise_", "activateWindow"):
                    try: getattr(win, fn)()
                    except Exception: pass
        except Exception:
            pass
        log.info("[MESH] TAB A per-instrument sight window OPEN")


