        axg.plot(theta, [1.0] * len(theta), color=col, lw=14, solid_capstyle="round")
        axg.plot(_np.linspace(_np.pi * 1.25, _np.pi * 1.25 - 2 * _np.pi * 0.75, 60), [1.0] * 60,
                 color="#13252e", lw=14, solid_capstyle="round", zorder=0)
