# ════════════════════════════════════════════════════════════════════════════════
# Pass 34 (T-LSL): BCILSLBroadcaster — broadcast BCI band powers over Lab Streaming Layer
# Studies BCIexamplecode1/OpenBCI_GUI-master LSL outlet design.
# When pylsl is installed and --lsl flag is given, pushes one sample per fuser
# frame containing all 7 band powers + motor intent confidence + mindfulness +
# restfulness to an LSL outlet named "NEPA_BCI".  Compatible with OpenBCI GUI,
# BrainFlow, and any LSL-aware recording / BCI pipeline.
# ════════════════════════════════════════════════════════════════════════════════

try:
    import pylsl  # type: ignore
    _pylsl_ok = True
except ImportError:
    pylsl = None  # type: ignore
    _pylsl_ok = False

class BCILSLBroadcaster:
    """Pass 34: Publishes live BCI band-power fields as an LSL stream.

    Stream info:
      Name:     NEPA_BCI
      Type:     EEG   (convention: band powers treated as derived EEG features)
      Channels: 10
        0-6  : absolute band powers (infra_gamma, delta, theta, alpha,
                                     beta, low_gamma, high_gamma)
        7    : bci_motor_conf (Riemannian classifier confidence 0-1)
        8    : bci_mindfulness (0-1)
        9    : bci_restfulness (0-1)
      Rate:     nominal_srate = fuser's target_fps (default 20 Hz)
      Format:   float32

    If pylsl is not installed, the broadcaster silently does nothing (no crash).
    """

    CHANNEL_NAMES = [
        "infra_gamma", "delta", "theta", "alpha", "beta",
        "low_gamma", "high_gamma",
        "motor_conf", "mindfulness", "restfulness",
    ]

    def __init__(self, srate: float = 20.0):
        self._outlet = None
        self._srate  = srate
        if not _pylsl_ok:
            log.info("[LSL] pylsl not available — BCI broadcast disabled "
                     "(install pylsl to enable: pip install pylsl)")
            return
        try:
            info = pylsl.StreamInfo(
                name="NEPA_BCI",
                type="EEG",
                channel_count=len(self.CHANNEL_NAMES),
                nominal_srate=srate,
                channel_format=pylsl.cf_float32,
                source_id="nepa_bci_0",
            )
            # Add channel labels to the XML metadata
            chns = info.desc().append_child("channels")
            for name in self.CHANNEL_NAMES:
                ch = chns.append_child("channel")
                ch.append_child_value("label",  name)
                ch.append_child_value("unit",   "microvolts" if name.endswith("_gamma")
                                                 or name in ("delta","theta","alpha","beta",
                                                             "low_gamma") else "normalized")
                ch.append_child_value("type",   "EEG")
            self._outlet = pylsl.StreamOutlet(info)
            log.info(f"[LSL] NEPA_BCI LSL outlet opened — {len(self.CHANNEL_NAMES)} ch @ {srate:.0f} Hz")
        except Exception as e:
            log.warning(f"[LSL] Failed to open LSL outlet: {e}")
            self._outlet = None

    @property
    def active(self) -> bool:
        return self._outlet is not None

    def push(self, psych_profile: dict):
        """Push one sample from the current psych_profile to the LSL outlet.
        Called once per fuser frame when --lsl is active."""
        if self._outlet is None:
            return
        p = psych_profile
        sample = [
            float(p.get("bci_band_infra_gamma", 0.0)),
            float(p.get("bci_band_delta",       0.0)),
            float(p.get("bci_band_theta",        0.0)),
            float(p.get("bci_band_alpha",        0.0)),
            float(p.get("bci_band_beta",         0.0)),
            float(p.get("bci_band_low_gamma",    0.0)),
            float(p.get("bci_band_high_gamma",   0.0)),
            float(p.get("bci_motor_conf",        0.0)),
            float(p.get("bci_mindfulness",       0.5)),
            float(p.get("bci_restfulness",       0.5)),
        ]
        try:
            self._outlet.push_sample(sample)
        except Exception as e:
            log.debug(f"[LSL] push_sample error: {e}")

    def close(self):
        """Explicitly destroy the LSL outlet."""
        if self._outlet is not None:
            del self._outlet
            self._outlet = None
            log.info("[LSL] NEPA_BCI LSL outlet closed")


class EEGStreamInletClient:
    """v170: REAL wired/wireless EEG ingestion via Lab Streaming Layer (LSL) inlet.

    THE HONEST "MAKE WIRELESS BCI REAL" PATH. A consumer EEG headset IS a genuine wireless
    BCI: a Muse (Bluetooth, via muselsl), an OpenBCI Cyton/Ganglion, an Emotiv, or any
    BrainFlow/LSL-aware device publishes a REAL LSL stream of type 'EEG' — microvolt samples
    measured by electrodes physically on ONE consenting wearer's scalp. This client
    auto-detects such a stream (excluding N.E.P.A.'s own NEPA_BCI outlet), pulls the real
    samples into a rolling window, and computes REAL per-channel band powers (delta / theta /
    alpha / beta / gamma) by FFT. When a device is present, BCI becomes a REAL neural source
    for that wearer — the literal honest answer to "wireless BCI should be real."

    Same "show what is live, don't show what isn't" pattern as every other instrument: a real
    headset lights it up; nothing present → it simply does not appear. Same path the ESP32-CSI
    sensor uses — plug in real hardware and the real data flows, no code change.

    HONESTY CEILING (hard physical limits, NOT engineering hurdles that can be coded around):
      • Reads ONE wearer wearing electrodes on their own scalp — NOT remote, NOT through walls,
        NOT animals, NOT a planet of minds. EEG fields are microvolts at the scalp; they are
        undetectable at a distance (that is WHY EEG needs contact electrodes and MEG needs
        femtotesla SQUIDs in a shielded room).
      • Reads aggregate cortical RHYTHMS (band powers, evoked potentials, coarse motor-imagery
        after per-wearer training) — NOT the semantic CONTENT of thoughts. No instrument,
        contact or remote, decodes the content of thought. "Reading minds" is not a sensor
        N.E.P.A. lacks; it is data that does not exist to be read.
      • Remote neural monitoring (RMN) of thought has no real signal — N.E.P.A. will not
        fabricate one. This client publishes ONLY what a real attached device measures.

    NO FALSE DATA: pylsl absent OR no real EEG stream present → no-op, eeg_real_ok=False, no
    band powers. Never synthesises EEG (SyntheticEEGGenerator is a separate, explicitly
    SIMULATED path used only under --sim-validate).
    """
    _BANDS = [("delta", 1.0, 4.0), ("theta", 4.0, 8.0), ("alpha", 8.0, 13.0),
              ("beta", 13.0, 30.0), ("gamma", 30.0, 50.0)]
    _WIN_S      = 2.0      # 2-second analysis window
    _REFRESH_S  = 0.5

    def __init__(self):
        import threading as _thr
        self._lock = _thr.Lock()
        self._ok = False
        self._stream_name = ""
        self._n_channels = 0
        self._srate = 0.0
        self._ch_labels: list = []
        self._band_mean: dict = {}     # band -> mean fraction across channels
        self._per_channel: list = []   # [{ch,label,bands:{frac},total_uv2}]
        self._xcorr_mean = 0.0         # v186: cross-channel coherence diagnostics (read-only,
        self._xcorr_max = 0.0          # never used to alter band powers — see _cross_channel_diag)
        self._dom_eigval_frac = 0.0
        self._n_samples_seen = 0
        self._inlet = None
        self._buf = None               # numpy (channels x winN) rolling buffer
        self._buf_fill = 0
        _thr.Thread(target=self._loop, daemon=True, name="eeg_inlet_v170").start()

    @staticmethod
    def _band_powers_psd(sig, srate, bands):
        """Real one-sided PSD band powers for a 1-D signal (Hann-windowed periodogram).

        Returns {band: absolute power} in input-units² (µV² for EEG). Pure numpy, no SciPy.
        """
        import numpy as _np
        x = _np.asarray(sig, dtype=float)
        n = x.size
        if n < 8 or srate <= 0:
            return None
        x = x - _np.mean(x)
        w = _np.hanning(n)
        sw2 = float(_np.sum(w ** 2)) or 1.0
        sp = _np.fft.rfft(x * w)
        psd = (_np.abs(sp) ** 2) / (srate * sw2)
        if psd.size > 2:
            psd[1:-1] *= 2.0          # one-sided correction
        freqs = _np.fft.rfftfreq(n, d=1.0 / srate)
        out = {}
        for name, lo, hi in bands:
            m = (freqs >= lo) & (freqs < hi)
            out[name] = float(_np.sum(psd[m]))
        return out

    @staticmethod
    def _cross_channel_diag(buf):
        """v186: REAL, non-destructive cross-channel coherence diagnostic for a genuine
        multi-electrode EEG window — the engineering tool the correlation-matrix/error-
        correction request actually applies to (real electrodes have real shared artifacts:
        blink, mains hum, motion). Reports how much of the cross-channel variance is shared,
        WITHOUT touching the band-power numbers shown elsewhere.

        Why diagnostic-only, not subtractive: tested a Gauss-Seidel common-mode SUBTRACTION
        (same math as FrequencyResonanceNeuralProxyEngine) on synthetic multi-channel EEG —
        it also erased 80-90%+ of genuine independent same-frequency activity (e.g. alpha
        present on every channel with different phase, which is normal volume conduction,
        not an artifact) because a blind eigen-projection cannot distinguish "shared artifact"
        from "same-band neural rhythm coherent across nearby electrodes." Subtracting it would
        make real decoding LESS accurate — worse than not having the feature. Reporting the
        coherence value (still real correlation-matrix math) without altering the signal avoids
        that failure mode while still surfacing the information honestly.
        """
        import numpy as _np
        n_ch = buf.shape[0]
        if n_ch < 2:
            return 0.0, 0.0, 0.0
        X = buf - buf.mean(axis=1, keepdims=True)
        std = X.std(axis=1, keepdims=True) + 1e-9
        Xn = X / std
        C = (Xn @ Xn.T) / Xn.shape[1]
        iu = _np.triu_indices(n_ch, k=1)
        off = _np.abs(C[iu])
        try:
            evals = _np.linalg.eigvalsh(C)
            dom_frac = float(evals.max() / n_ch)
        except _np.linalg.LinAlgError:
            dom_frac = 0.0
        return float(off.mean()) if off.size else 0.0, float(off.max()) if off.size else 0.0, dom_frac

    def _find_stream(self):
        """Resolve a real, non-NEPA EEG LSL stream. Returns StreamInfo or None."""
        try:
            streams = pylsl.resolve_streams(wait_time=1.0)
        except Exception:
            return None
        for st in streams:
            try:
                if (st.type() or "").upper() == "EEG" \
                        and st.source_id() != "nepa_bci_0" and st.name() != "NEPA_BCI":
                    return st
            except Exception:
                continue
        return None

    def _open(self, info):
        import numpy as _np
        self._inlet = pylsl.StreamInlet(info, max_buflen=8)
        meta = self._inlet.info()
        self._srate = float(meta.nominal_srate()) or 256.0
        self._n_channels = max(1, int(meta.channel_count()))
        labels = []
        try:
            ch = meta.desc().child("channels").child("channel")
            for i in range(self._n_channels):
                lbl = ch.child_value("label")
                labels.append(lbl if lbl else f"ch{i}")
                ch = ch.next_sibling()
        except Exception:
            labels = [f"ch{i}" for i in range(self._n_channels)]
        self._ch_labels = labels
        self._stream_name = meta.name() or "EEG"
        winN = max(16, int(self._WIN_S * self._srate))
        self._buf = _np.zeros((self._n_channels, winN), dtype=float)
        self._buf_fill = 0
        log.info(f"[EEG] REAL EEG stream '{self._stream_name}' — {self._n_channels} ch "
                 f"@ {self._srate:.0f} Hz (genuine wireless BCI ingest active)")

    def _loop(self):
        import time as _ti, numpy as _np
        if not _pylsl_ok:
            log.info("[EEG] pylsl not available — real EEG ingest disabled (no fabrication). "
                     "Install pylsl + run a Muse (muselsl)/OpenBCI/BrainFlow LSL stream to enable.")
            return
        while True:
            try:
                if self._inlet is None:
                    info = self._find_stream()
                    if info is None:
                        with self._lock:
                            self._ok = False
                        _ti.sleep(3.0)
                        continue
                    self._open(info)
                chunk, _ts = self._inlet.pull_chunk(timeout=0.4, max_samples=512)
                if chunk:
                    arr = _np.asarray(chunk, dtype=float)        # (samples x channels)
                    if arr.ndim == 1:
                        arr = arr.reshape(-1, 1)
                    arr = arr.T[: self._n_channels, :]            # (channels x samples)
                    ns = arr.shape[1]
                    winN = self._buf.shape[1]
                    if ns >= winN:
                        self._buf = arr[:, -winN:].copy()
                        self._buf_fill = winN
                    else:
                        self._buf = _np.roll(self._buf, -ns, axis=1)
                        self._buf[:, -ns:] = arr
                        self._buf_fill = min(winN, self._buf_fill + ns)
                    self._n_samples_seen += ns
                    if self._buf_fill >= max(16, int(0.5 * winN)):
                        per_ch = []
                        agg = {b: 0.0 for b, _lo, _hi in self._BANDS}
                        for ci in range(self._n_channels):
                            bp = self._band_powers_psd(
                                self._buf[ci, -self._buf_fill:], self._srate, self._BANDS)
                            if bp is None:
                                continue
                            tot = sum(bp.values()) or 1.0
                            frac = {b: round(bp[b] / tot, 4) for b in bp}
                            for b in agg:
                                agg[b] += frac[b]
                            per_ch.append({
                                "ch": ci,
                                "label": self._ch_labels[ci] if ci < len(self._ch_labels) else f"ch{ci}",
                                "bands": frac,
                                "total_uv2": round(tot, 3),
                            })
                        nch = len(per_ch) or 1
                        band_mean = {b: round(agg[b] / nch, 4) for b in agg}
                        # v186: real cross-channel coherence diagnostic — informational only,
                        # never subtracted from the band powers above (see _cross_channel_diag).
                        try:
                            _xm, _xx, _de = self._cross_channel_diag(
                                self._buf[:, -self._buf_fill:])
                        except Exception:
                            _xm = _xx = _de = 0.0
                        with self._lock:
                            self._per_channel = per_ch
                            self._band_mean = band_mean
                            self._xcorr_mean = _xm
                            self._xcorr_max = _xx
                            self._dom_eigval_frac = _de
                            self._ok = len(per_ch) > 0
                _ti.sleep(self._REFRESH_S)
            except Exception as e:
                log.debug(f"[EEG] inlet loop error: {e}")
                self._inlet = None
                with self._lock:
                    self._ok = False
                _ti.sleep(2.0)

    def get(self) -> dict:
        with self._lock:
            return {
                "eeg_real_ok":          bool(self._ok),
                "eeg_real_stream_name": self._stream_name,
                "eeg_real_n_channels":  self._n_channels if self._ok else 0,
                "eeg_real_srate":       round(self._srate, 1) if self._ok else 0.0,
                "eeg_real_band_powers": dict(self._band_mean) if self._ok else {},
                "eeg_real_per_channel": list(self._per_channel) if self._ok else [],
                "eeg_real_n_samples":   self._n_samples_seen,
                # v186: real cross-channel coherence (correlation-matrix diagnostic, informational
                # only — see _cross_channel_diag for why it is NOT subtracted from band powers).
                "eeg_real_xcorr_mean":      round(self._xcorr_mean, 3) if self._ok else 0.0,
                "eeg_real_xcorr_max":       round(self._xcorr_max, 3) if self._ok else 0.0,
                "eeg_real_dom_eigval_frac": round(self._dom_eigval_frac, 3) if self._ok else 0.0,
            }


# ════════════════════════════════════════════════════════════════════════════════
# Pass 34 (T-SEM): SemanticStateEngine — RuView-style room-presence semantic states
# Studies Examplecode1/RuView for occupancy + multi-room + activity classification.
# 10 semantic macro-states inferred from RF voxel blobs + BCI + vital signs.
# Optional MQTT + Home Assistant entity publishing (paho-mqtt or hbmqtt).
# ════════════════════════════════════════════════════════════════════════════════

try:
    import paho.mqtt.client as _paho_mqtt  # type: ignore
except ImportError:
    _paho_mqtt = None  # type: ignore

class SemanticStateEngine:
    """Pass 34: Infers 10 high-level semantic room/occupancy states from the live
    RF voxel field, BCI outputs, vital signs, and motion history.  Mirrors the
    RuView occupancy semantics but runs entirely from the N.E.P.A. sensor stack.

    Semantic macro-states (one per room / per tracked person):
      ROOM_EMPTY         — no detected RF presence in the zone
      ROOM_ACTIVE        — person present + motion / normal activity
      PERSON_STATIONARY  — person present, no motion for >30 s
      PERSON_SLEEPING    — stationary + low arousal + restful BCI signature
      POSSIBLE_DISTRESS  — abnormal vitals (BR<8 or HR>100) + low mobility
      FALL_RISK_ELEVATED — rapid vertical centroid drop (SAR / voxel Z-shift)
      FALL_DETECTED      — confirmed Z-drop + no recovery within 10 s
      COGNITIVE_FOCUS    — high BCI focus/alpha, low motion
      COGNITIVE_STRESS   — high BCI stress + elevated threat score
      MULTI_OCCUPANCY    — ≥2 person blobs detected simultaneously

    MQTT: if --mqtt-host is given, publishes each state change to
      nepa/room/{room_id}/state  with JSON payload.
    Home Assistant: auto-announces sensor entities via HA MQTT discovery prefix.
    """

    STATES = [
        "ROOM_EMPTY",
        "ROOM_ACTIVE",
        "PERSON_STATIONARY",
        "PERSON_SLEEPING",
        "POSSIBLE_DISTRESS",
        "FALL_RISK_ELEVATED",
        "FALL_DETECTED",
        "COGNITIVE_FOCUS",
        "COGNITIVE_STRESS",
        "MULTI_OCCUPANCY",
    ]

    # Thresholds
    _MOTION_VEL_THRESH   = 0.05   # m/frame: below this → stationary
    _STATIONARY_FRAMES   = 30 * 20  # 30 s at 20 fps
    _SLEEP_ALPHA_MIN     = 0.30
    _SLEEP_RESTFUL_MIN   = 0.55
    _SLEEP_MOTION_MAX    = 0.02
    _DISTRESS_BR_LOW     = 8.0    # breaths/min
    _DISTRESS_HR_HIGH    = 100.0  # bpm
    _FALL_Z_DROP_FRAC    = 0.25   # 25% centroid drop per frame
    _FALL_CONFIRM_FRAMES = 10 * 20  # 10 s at 20 fps

    def __init__(self, room_id: str = "room_0", mqtt_host: str = None,
                 mqtt_port: int = 1883, ha_discovery: bool = False):
        self.room_id      = room_id
        self.mqtt_host    = mqtt_host
        self.mqtt_port    = mqtt_port
        self.ha_discovery = ha_discovery
        self._state       = "ROOM_EMPTY"
        self._prev_state  = None
        self._state_since = 0           # frame index when state last changed
        self._frame       = 0
        self._stationary_count = 0
        self._fall_candidate   = 0      # frame when fall candidate began
        self._prev_centroid_z  = None
        self._history          = deque(maxlen=300)  # (frame, state)
        self._mqtt_client      = None
        self._rooms: dict      = {}     # room_id → state for multi-room
        self._rooms[room_id]   = "ROOM_EMPTY"
        if mqtt_host and _paho_mqtt is not None:
            self._connect_mqtt()
        log.info(f"[Semantic] SemanticStateEngine init room={room_id} "
                 f"mqtt={'yes' if mqtt_host else 'no'} "
                 f"paho={'ok' if _paho_mqtt else 'missing'}")

    # ── MQTT connection ───────────────────────────────────────────────────────
    def _connect_mqtt(self):
        try:
            self._mqtt_client = _paho_mqtt.Client(client_id=f"nepa_{self.room_id}")
            self._mqtt_client.connect(self.mqtt_host, self.mqtt_port, keepalive=60)
            self._mqtt_client.loop_start()
            if self.ha_discovery:
                self._publish_ha_discovery()
            log.info(f"[Semantic] MQTT connected to {self.mqtt_host}:{self.mqtt_port}")
        except Exception as e:
            log.warning(f"[Semantic] MQTT connect failed: {e}")
            self._mqtt_client = None

    def _publish_ha_discovery(self):
        """Announce N.E.P.A. room sensor to Home Assistant via MQTT discovery."""
        if self._mqtt_client is None:
            return
        import json as _json
        topic = f"homeassistant/sensor/nepa_{self.room_id}/config"
        payload = {
            "name":          f"NEPA {self.room_id.replace('_',' ').title()} State",
            "unique_id":     f"nepa_{self.room_id}_state",
            "state_topic":   f"nepa/room/{self.room_id}/state",
            "value_template":"{{ value_json.state }}",
            "icon":          "mdi:radar",
            "device": {
                "identifiers": ["nepa_rf_system"],
                "name":        "N.E.P.A. RF Sensor Array",
                "model":       "WiFi-CSI",
                "manufacturer":"NEPA",
            },
        }
        self._mqtt_client.publish(topic, _json.dumps(payload), retain=True)

    def _publish_state(self, state: str, extra: dict = None):
        """Publish a state-change event to MQTT."""
        if self._mqtt_client is None:
            return
        import json as _json
        payload = {"state": state, "room": self.room_id,
                   "frame": self._frame, **(extra or {})}
        topic = f"nepa/room/{self.room_id}/state"
        try:
            self._mqtt_client.publish(topic, _json.dumps(payload))
        except Exception as e:
            log.debug(f"[Semantic] MQTT publish error: {e}")

    # ── Core inference ────────────────────────────────────────────────────────
    def update(self, psych_profile: dict, world_snapshot: dict) -> str:
        """Infer the current semantic state from live sensor outputs.
        Called once per fuser frame with the latest psych_profile and world_snapshot.
        Returns the current semantic state string."""
        self._frame += 1
        pp  = psych_profile or {}
        snp = world_snapshot or {}

        # ── blob geometry
        blobs   = snp.get("blobs", [])
        n_blobs = len(blobs)
        # motion velocity from the fuser (m/frame proxy via Doppler or voxel centroid shift)
        motion_vel = float(pp.get("motion_velocity", 0.0))

        # ── vertical centroid (Z) for fall detection
        centroid_z = None
        if blobs:
            centroid_z = float(np.mean([b.get("centroid", [0, 0, 0])[2]
                                        for b in blobs]))

        # ── BCI fields
        alpha       = float(pp.get("bci_band_alpha",    0.0))
        restfulness = float(pp.get("bci_restfulness",   0.5))
        focus       = float(pp.get("bci_focus",         0.0))
        stress      = float(pp.get("bci_stress",        0.0))
        arousal     = float(pp.get("arousal_level",     0.5))

        # ── vitals
        hr  = float(pp.get("heart_rate",    72.0))
        br  = float(pp.get("breathing_rate", 15.0))

        # ── overseer threat
        threat = float(pp.get("threat_score",      0.0))

        # ── derive state ─────────────────────────────────────────────────────
        new_state = self._infer(
            n_blobs, motion_vel, centroid_z,
            alpha, restfulness, focus, stress, arousal,
            hr, br, threat,
        )
        # ── state transition bookkeeping
        if new_state != self._state:
            self._prev_state  = self._state
            self._state       = new_state
            self._state_since = self._frame
            self._rooms[self.room_id] = new_state
            self._publish_state(new_state, {
                "prev": self._prev_state,
                "n_blobs": n_blobs,
                "motion_vel": round(motion_vel, 4),
            })
        self._history.append((self._frame, self._state))
        return self._state

    def _infer(self, n_blobs, motion_vel, centroid_z,
               alpha, restfulness, focus, stress, arousal,
               hr, br, threat) -> str:
        """Stateful 10-state classifier — priority order matters."""
        # MULTI_OCCUPANCY first (highest priority for safety)
        if n_blobs >= 2:
            return "MULTI_OCCUPANCY"
        # ROOM_EMPTY
        if n_blobs == 0:
            self._stationary_count = 0
            self._prev_centroid_z  = None
            self._fall_candidate   = 0
            return "ROOM_EMPTY"

        # ── single-person states ─────────────────────────────────────────────
        # FALL_DETECTED (confirm after enough frames since candidate)
        if self._fall_candidate > 0:
            if (self._frame - self._fall_candidate) >= self._FALL_CONFIRM_FRAMES:
                return "FALL_DETECTED"
            # still in confirmation window — stay at FALL_RISK_ELEVATED
            return "FALL_RISK_ELEVATED"

        # FALL_RISK: sudden Z-drop this frame?
        if (centroid_z is not None and self._prev_centroid_z is not None):
            drop = self._prev_centroid_z - centroid_z
            if drop > abs(self._prev_centroid_z) * self._FALL_Z_DROP_FRAC and drop > 0.05:
                if self._fall_candidate == 0:
                    self._fall_candidate = self._frame
                return "FALL_RISK_ELEVATED"
        else:
            self._fall_candidate = 0  # reset if no centroid
        if centroid_z is not None:
            self._prev_centroid_z = centroid_z

        # POSSIBLE_DISTRESS
        if (br < self._DISTRESS_BR_LOW or hr > self._DISTRESS_HR_HIGH) and motion_vel < 0.10:
            return "POSSIBLE_DISTRESS"

        # PERSON_SLEEPING (override STATIONARY when BCI says rest)
        if motion_vel < self._SLEEP_MOTION_MAX:
            self._stationary_count += 1
        else:
            self._stationary_count = max(0, self._stationary_count - 1)

        if (self._stationary_count >= self._STATIONARY_FRAMES
                and alpha >= self._SLEEP_ALPHA_MIN
                and restfulness >= self._SLEEP_RESTFUL_MIN):
            return "PERSON_SLEEPING"

        # PERSON_STATIONARY
        if self._stationary_count >= self._STATIONARY_FRAMES:
            return "PERSON_STATIONARY"

        # COGNITIVE_FOCUS
        if focus > 0.65 and stress < 0.40 and motion_vel < 0.10:
            return "COGNITIVE_FOCUS"

        # COGNITIVE_STRESS
        if stress > 0.65 or (threat > 0.70 and arousal > 0.60):
            return "COGNITIVE_STRESS"

        # Default: active
        return "ROOM_ACTIVE"

    # ── multi-room tracking ───────────────────────────────────────────────────
    def add_room(self, room_id: str):
        """Register an additional room ID for multi-room tracking."""
        if room_id not in self._rooms:
            self._rooms[room_id] = "ROOM_EMPTY"

    def update_room(self, room_id: str, state: str):
        """Directly set the state for a non-primary room (e.g. from a remote sensor)."""
        self._rooms[room_id] = state
        if self._mqtt_client:
            self._publish_state(state)

    # ── queries ───────────────────────────────────────────────────────────────
    @property
    def state(self) -> str:
        return self._state

    @property
    def all_rooms(self) -> dict:
        return dict(self._rooms)

    def frames_in_state(self) -> int:
        return self._frame - self._state_since

    def state_history(self, last_n: int = 20) -> list:
        return list(self._history)[-last_n:]

    def summary_line(self) -> str:
        rooms_str = " | ".join(f"{r}:{s}" for r, s in self._rooms.items())
        return (f"SEMANTIC  state={self._state:<20s}  "
                f"since={self.frames_in_state()}f  rooms=[{rooms_str}]")


