"""
N.E.P.A. Pass 46 Engine Classes
Sources:
  - NeRF2 (crucialuseexamplecode11): model.py positional encoding + renderer.py ray marching
  - RF-GS (Crucialuseexamplecode12): neural_gaussian_splats.py adaptive density
  - NerfStudio (cruicialuseexamplecode10): camera_paths.py keyframe interpolation
  - Crucialuseexamplecode4: cyclostationary_detector full T_y statistic
  - Examplecode3/wifi-3d-fusion: multi-AP quality-weighted fusion, CSI format upgrades
  - CSIKit (Crucialuseexamplecode8): ESP32 int8 binary format, Nexmon chip-specific unpack
"""

import math
import collections
import struct
import numpy as np


# ─────────────────────────────────────────────────────
#  NeRF2 numpy positional encoding (torch-free fallback)
# ─────────────────────────────────────────────────────

class _NP2Embedder:
    """Numpy port of NeRF2 Embedder — sinusoidal positional encoding."""
    def __init__(self, input_dims=3, multires=10, include_input=True):
        self.input_dims = input_dims
        self.include_input = include_input
        freqs = 2.0 ** np.linspace(0.0, multires - 1, multires)
        self.freqs = freqs
        self.out_dim = (input_dims if include_input else 0) + input_dims * 2 * multires

    def embed(self, x):
        # x: (..., input_dims)
        parts = []
        if self.include_input:
            parts.append(x)
        for f in self.freqs:
            parts.append(np.sin(f * x))
            parts.append(np.cos(f * x))
        return np.concatenate(parts, axis=-1)


class _NP2Linear:
    """Numpy linear layer with Xavier init."""
    def __init__(self, in_f, out_f):
        scale = np.sqrt(2.0 / (in_f + out_f))
        self.W = np.random.randn(out_f, in_f).astype(np.float32) * scale
        self.b = np.zeros(out_f, dtype=np.float32)

    def __call__(self, x):
        return x @ self.W.T + self.b


class NeRF2ModelNP:
    """
    Numpy-only NeRF2 network (D=4, W=64 for real-time use).
    Mirrors the NeRF2 architecture: attenuation MLP + signal MLP with skip connections.
    Positional encoding on pts (L=6) and view dirs (L=4).
    Outputs: (attn_amp, attn_phase, sig_amp, sig_phase) per sample point.
    """

    def __init__(self, D=4, W=64, skip=2,
                 pts_multires=6, view_multires=4):
        self.skip = skip
        self.embed_pts = _NP2Embedder(3, pts_multires, True)
        self.embed_view = _NP2Embedder(3, view_multires, True)
        pts_dim = self.embed_pts.out_dim
        view_dim = self.embed_view.out_dim

        # attenuation MLP
        self.atten_layers = []
        in_d = pts_dim
        for i in range(D):
            out_d = W
            self.atten_layers.append(_NP2Linear(in_d, out_d))
            in_d = W
            if i == skip:
                in_d = W + pts_dim  # skip connection
        self.atten_out = _NP2Linear(W, 2)    # attn_amp, attn_phase
        self.feat_layer = _NP2Linear(W, W)

        # signal MLP
        self.sig_lin1 = _NP2Linear(view_dim + W, W)
        self.sig_lin2 = _NP2Linear(W, W // 2)
        self.sig_out  = _NP2Linear(W // 2, 2)  # sig_amp, sig_phase

        self._skip_dim = pts_dim

    @staticmethod
    def _relu(x):
        return np.maximum(x, 0.0)

    def forward(self, pts, view):
        """
        pts:  (N, 3) world positions
        view: (N, 3) unit view directions
        Returns: (N, 4) [attn_amp, attn_phase, sig_amp, sig_phase]
        """
        ep = self.embed_pts.embed(pts)    # (N, pts_dim)
        ev = self.embed_view.embed(view)  # (N, view_dim)

        x = ep
        for i, layer in enumerate(self.atten_layers):
            x = self._relu(layer(x))
            if i == self.skip:
                x = np.concatenate([ep, x], axis=-1)

        attn = self.atten_out(x)             # (N, 2)
        feat = self.feat_layer(x)            # (N, W)

        sx = np.concatenate([feat, ev], axis=-1)
        sx = self._relu(self.sig_lin1(sx))
        sx = self._relu(self.sig_lin2(sx))
        sig = self.sig_out(sx)               # (N, 2)

        return np.concatenate([attn, sig], axis=-1)  # (N, 4)


class NeRF2RayRendererFullNP2:
    """
    Numpy ray marcher for NeRF2 — renders received signal strength from a set of rays.
    Mirrors renderer.py raw2outputs: alpha compositing on RF attenuation + phase accumulation.
    """

    def __init__(self, model: NeRF2ModelNP, near=0.1, far=10.0, n_samples=32):
        self.model = model
        self.near = near
        self.far = far
        self.n_samples = n_samples

    def render(self, rays_o, rays_d):
        """
        rays_o: (R, 3) ray origins (AP positions in metres)
        rays_d: (R, 3) unit ray directions (towards target)
        Returns: (R,) received signal strength per ray
        """
        t_vals = np.linspace(self.near, self.far, self.n_samples)  # (S,)
        pts = rays_o[:, None, :] + rays_d[:, None, :] * t_vals[None, :, None]  # (R, S, 3)
        view = np.broadcast_to(rays_d[:, None, :], pts.shape)

        R, S = pts.shape[:2]
        raw = self.model.forward(pts.reshape(-1, 3), view.reshape(-1, 3))  # (R*S, 4)
        raw = raw.reshape(R, S, 4)

        dists = np.diff(t_vals, append=t_vals[-1] + 1e-3)  # (S,)
        attn_a = np.abs(np.maximum(raw[..., 0], 0.0))
        alpha = 1.0 - np.exp(-attn_a * dists)
        T = np.cumprod(np.concatenate([np.ones((R, 1)), 1 - alpha[:, :-1] + 1e-10], axis=1), axis=1)
        weights = alpha * T  # (R, S)

        sig_a = np.abs(np.maximum(raw[..., 2], 0.0))
        sig_p = np.arctan2(np.sin(raw[..., 3]), np.cos(raw[..., 3]))
        signal = np.sum(weights * sig_a * np.exp(1j * sig_p), axis=1)
        return np.abs(signal)  # (R,)

    def scene_strength_grid(self, ap_pos, grid_xy, z=0.0):
        """
        Cast rays from each AP towards a 2D grid at height z.
        Returns (len(grid_xy),) average RSS across APs.
        """
        G = len(grid_xy)
        targets = np.column_stack([grid_xy, np.full(G, z)])
        rss_sum = np.zeros(G)
        for ap in ap_pos:
            o = np.broadcast_to(ap, (G, 3)).copy()
            d = targets - o
            norms = np.linalg.norm(d, axis=1, keepdims=True) + 1e-9
            d = d / norms
            rss_sum += self.render(o, d)
        return rss_sum / max(1, len(ap_pos))


# ─────────────────────────────────────────────────────
#  RF Gaussian Splatting — numpy adaptive density cloud
# ─────────────────────────────────────────────────────

class RFGSGaussian:
    """Single RF Gaussian: position, log-scale, opacity, color."""
    __slots__ = ('pos', 'log_scale', 'opacity', 'color', 'grad_accum', 'alive')

    def __init__(self, pos, log_scale=None, opacity=0.5, color=None):
        self.pos = np.asarray(pos, dtype=np.float32)
        self.log_scale = np.array(log_scale if log_scale is not None else [-2.0, -2.0, -2.0], dtype=np.float32)
        self.opacity = float(opacity)
        self.color = np.asarray(color if color is not None else [0.5, 0.5, 0.5], dtype=np.float32)
        self.grad_accum = 0.0
        self.alive = True


class RFGaussianSplatRendererNP:
    """
    Numpy RF Gaussian splatting renderer with adaptive density control.
    Implements densification (clone/split high-gradient Gaussians) and
    pruning (remove low-opacity Gaussians) from neural_gaussian_splats.py.
    """

    MIN_OPACITY = 0.005
    DENSIFY_GRAD_THRESHOLD = 0.002
    MAX_GAUSSIANS = 4000
    PRUNE_PERIOD = 100
    DENSIFY_PERIOD = 50

    def __init__(self, n_init=200, room_size=(8.0, 8.0, 3.0)):
        rng = np.random.default_rng(42)
        self.gaussians: list[RFGSGaussian] = []
        for _ in range(n_init):
            pos = rng.uniform(-1, 1, 3) * np.array(room_size) * 0.5
            self.gaussians.append(RFGSGaussian(pos))
        self.step_count = 0
        self.room_size = room_size

    @property
    def active(self):
        return [g for g in self.gaussians if g.alive]

    def _project_to_2d(self, pos3d, cam_pos, cam_dir):
        """Simple orthographic project: returns (u, v, depth)."""
        right = np.cross(cam_dir, [0, 0, 1])
        right = right / (np.linalg.norm(right) + 1e-9)
        up = np.cross(right, cam_dir)
        rel = pos3d - cam_pos
        return float(np.dot(rel, right)), float(np.dot(rel, up)), float(np.dot(rel, cam_dir))

    def render_view(self, cam_pos, cam_dir, width=64, height=64):
        """
        Alpha-composite Gaussians onto a 2D grid.
        Returns (H, W, 3) float32 RF intensity image.
        """
        cam_pos = np.asarray(cam_pos, dtype=np.float32)
        cam_dir = np.asarray(cam_dir, dtype=np.float32)
        cam_dir = cam_dir / (np.linalg.norm(cam_dir) + 1e-9)

        img = np.zeros((height, width, 3), dtype=np.float32)
        alpha_acc = np.zeros((height, width), dtype=np.float32)

        gs = sorted(self.active, key=lambda g: -np.dot(g.pos - cam_pos, cam_dir))

        for g in gs:
            u, v, depth = self._project_to_2d(g.pos, cam_pos, cam_dir)
            if depth <= 0:
                continue
            scale = np.exp(g.log_scale).mean() * max(width, height) / 10.0
            pu = int((u / 10.0 + 0.5) * width)
            pv = int((v / 10.0 + 0.5) * height)
            if not (0 <= pu < width and 0 <= pv < height):
                continue
            r = max(1, int(scale))
            ys, xs = np.ogrid[max(0, pv-r):min(height, pv+r+1),
                               max(0, pu-r):min(width,  pu+r+1)]
            dx = xs - pu; dy = ys - pv
            gauss2d = np.exp(-(dx**2 + dy**2) / (2 * scale**2 + 1e-9))
            alpha = g.opacity * gauss2d
            remain = 1.0 - alpha_acc[ys, xs]
            contrib = remain[..., None] * alpha[..., None] * g.color
            img[ys, xs] += contrib
            alpha_acc[ys, xs] += remain * alpha
            # accumulate gradient signal for densification
            g.grad_accum += float(np.mean(alpha))

        return np.clip(img, 0, 1)

    def update_from_rss(self, rss_map, positions_3d):
        """
        Feed measured RSS into Gaussian colors/positions.
        rss_map: (N,) float values, positions_3d: (N,3) world coords.
        """
        if len(rss_map) == 0:
            return
        rss_n = (np.asarray(rss_map) - np.min(rss_map))
        mx = np.max(rss_n)
        if mx > 0:
            rss_n /= mx
        for i, (pos, val) in enumerate(zip(positions_3d, rss_n)):
            if i < len(self.gaussians):
                self.gaussians[i].color = np.array([val, val * 0.5, 1.0 - val], dtype=np.float32)
                self.gaussians[i].pos = np.asarray(pos, dtype=np.float32)
                self.gaussians[i].opacity = 0.3 + 0.6 * float(val)

    def adaptive_density_step(self):
        """
        Densification + pruning.  Called periodically.
        Clones high-gradient low-scale Gaussians, splits high-scale ones.
        Prunes opacity < MIN_OPACITY.
        """
        self.step_count += 1
        active = self.active

        if self.step_count % self.DENSIFY_PERIOD == 0 and len(active) < self.MAX_GAUSSIANS:
            new_gs = []
            for g in active:
                if g.grad_accum < self.DENSIFY_GRAD_THRESHOLD:
                    continue
                scale = np.exp(g.log_scale).mean()
                if scale < 0.1:  # clone
                    new = RFGSGaussian(
                        g.pos + np.random.randn(3).astype(np.float32) * scale * 0.5,
                        g.log_scale.copy(), g.opacity * 0.8, g.color.copy()
                    )
                    new_gs.append(new)
                else:  # split
                    for _ in range(2):
                        offset = np.random.randn(3).astype(np.float32) * scale
                        new = RFGSGaussian(
                            g.pos + offset,
                            g.log_scale - np.log(1.6), g.opacity * 0.6, g.color.copy()
                        )
                        new_gs.append(new)
                g.grad_accum = 0.0
            self.gaussians.extend(new_gs[:self.MAX_GAUSSIANS - len(self.gaussians)])

        if self.step_count % self.PRUNE_PERIOD == 0:
            for g in self.gaussians:
                if g.opacity < self.MIN_OPACITY:
                    g.alive = False
            # keep alive list manageable
            self.gaussians = [g for g in self.gaussians if g.alive]

    def get_point_cloud(self):
        """Return (N,3) positions of active Gaussians for Open3D visualization."""
        a = self.active
        if not a:
            return np.zeros((0, 3))
        return np.stack([g.pos for g in a])


# ─────────────────────────────────────────────────────
#  NerfStudio camera path — keyframe flythrough (numpy)
# ─────────────────────────────────────────────────────

class _Pose:
    """Simple camera pose: position (3,) + quaternion (4,)."""
    __slots__ = ('pos', 'quat')

    def __init__(self, pos, quat=None):
        self.pos = np.asarray(pos, dtype=np.float64)
        self.quat = np.asarray(quat if quat is not None else [1, 0, 0, 0], dtype=np.float64)
        self.quat /= np.linalg.norm(self.quat) + 1e-12


def _slerp(q1, q2, t):
    dot = np.clip(np.dot(q1, q2), -1.0, 1.0)
    if dot < 0:
        q2 = -q2; dot = -dot
    if dot > 0.9995:
        return q1 + t * (q2 - q1)
    theta = math.acos(dot)
    return (math.sin((1 - t) * theta) * q1 + math.sin(t * theta) * q2) / math.sin(theta)


class NerfStudioCameraPath:
    """
    Keyframe-based camera flythrough from nerfstudio camera_paths.py.
    Supports: add_keyframe, sample_path, spiral_path.
    """

    def __init__(self):
        self.keyframes: list[_Pose] = []

    def add_keyframe(self, position, quaternion=None):
        self.keyframes.append(_Pose(position, quaternion))

    def sample_path(self, steps_per_segment=30):
        """
        Interpolate between keyframes.
        Returns list of _Pose with len = (n_keyframes-1)*steps_per_segment.
        """
        if len(self.keyframes) < 2:
            return list(self.keyframes)
        poses = []
        for i in range(len(self.keyframes) - 1):
            p0, p1 = self.keyframes[i], self.keyframes[i + 1]
            for s in range(steps_per_segment):
                t = s / steps_per_segment
                pos = p0.pos + t * (p1.pos - p0.pos)
                quat = _slerp(p0.quat, p1.quat, t)
                poses.append(_Pose(pos, quat))
        poses.append(self.keyframes[-1])
        return poses

    def spiral_path(self, center, radius=2.0, height=1.5, rots=2, steps=60, tilt=0.3):
        """
        Generate spiral flythrough around a center point.
        Matches get_spiral_path() in camera_paths.py.
        """
        poses = []
        for i in range(steps):
            t = i / steps
            angle = 2 * math.pi * rots * t
            x = center[0] + radius * math.cos(angle)
            y = center[1] + radius * math.sin(angle)
            z = center[2] + height * tilt * math.sin(angle * 0.5)
            pos = np.array([x, y, z])
            # look-at quaternion towards center
            look = np.array(center) - pos
            look = look / (np.linalg.norm(look) + 1e-9)
            up = np.array([0, 0, 1.0])
            right = np.cross(look, up)
            right = right / (np.linalg.norm(right) + 1e-9)
            up2 = np.cross(right, look)
            R = np.column_stack([right, up2, -look])
            # rotation matrix to quaternion
            tr = R[0, 0] + R[1, 1] + R[2, 2]
            if tr > 0:
                s = 0.5 / math.sqrt(tr + 1)
                quat = np.array([0.25 / s, (R[2, 1] - R[1, 2]) * s,
                                  (R[0, 2] - R[2, 0]) * s, (R[1, 0] - R[0, 1]) * s])
            else:
                quat = np.array([1, 0, 0, 0], dtype=np.float64)
            poses.append(_Pose(pos, quat))
        return poses

    def flythrough_frames(self, steps_per_segment=30):
        """Convenience: return list of (pos, quat) tuples."""
        return [(p.pos.tolist(), p.quat.tolist()) for p in self.sample_path(steps_per_segment)]


# ─────────────────────────────────────────────────────
#  Cyclostationary T_y detector (full conjugate-product)
# ─────────────────────────────────────────────────────

class CyclostationaryTyDetector:
    """
    Full cyclostationary conjugate-product T_y statistic.
    Sources: Crucialuseexamplecode4/Spectrum-Sensing-for-Cognitive-Radio-master
    Detects presence of OFDM/WiFi signals using cyclostationary features at
    cycle frequency alpha = 1/(N_c + N_d).

    H0: noise only      → T_y small
    H1: signal present  → T_y large (periodic correlation at CP rate)
    """

    def __init__(self, N_c=64, N_d=16, K=8, pfa=0.01):
        """
        N_c: FFT size (OFDM symbol length)
        N_d: cyclic prefix length
        K:   number of lags to average
        pfa: target probability of false alarm → threshold via chi2 CDF approximation
        """
        self.N_c = N_c
        self.N_d = N_d
        self.K = K
        self.period = N_c + N_d
        # Chi2(2K) threshold for pfa
        # Use approximation: threshold ≈ 2K + z_alpha * sqrt(4K) where z_alpha from pfa
        z = -2 * math.log(pfa)  # approximate chi2 tail
        self.threshold = 2 * K + z * math.sqrt(4.0 * K)
        self.last_T = 0.0
        self.last_decision = False

    def compute_Ty(self, y):
        """
        y: 1D complex array of received samples (length >= period * K + N_d)
        Returns: T_y statistic (float)
        """
        y = np.asarray(y, dtype=np.complex128)
        N = len(y)
        period = self.period
        needed = period * self.K + self.N_d
        if N < needed:
            return 0.0

        # T_y = |sum_{n=0}^{K-1} y[n*(N_c+N_d)] * conj(y[n*(N_c+N_d)+N_d])|^2
        # normalized by K^2 * noise_power^2
        acc = 0.0 + 0j
        for k in range(self.K):
            n0 = k * period
            n1 = n0 + self.N_d
            if n1 < N:
                acc += y[n0] * np.conjugate(y[n1])

        T_y = abs(acc) ** 2 / (self.K ** 2 + 1e-30)
        # normalize by estimated noise power
        noise_pow = float(np.mean(np.abs(y[:period]) ** 2)) + 1e-30
        self.last_T = T_y / (noise_pow ** 2)
        self.last_decision = self.last_T > self.threshold
        return self.last_T

    def detect(self, y):
        """Returns (T_y, H1_detected)."""
        T = self.compute_Ty(y)
        return T, self.last_decision


# ─────────────────────────────────────────────────────
#  CSIKit ESP32 binary parser upgrade (int8 I/Q format)
# ─────────────────────────────────────────────────────

class ESP32BinaryCSIParser:
    """
    Parses ESP32 CSI Tool binary output (int8 I/Q interleaved pairs).
    Format from CSIKit: field 25 in CSV is raw binary string of len=2*64 bytes.
    Supports 20MHz (64 subs) and 40MHz (128 subs) modes.
    """

    SUBCARRIER_COUNTS = {20: 64, 40: 128}
    # Subcarrier index offsets to skip null/pilot subcarriers (20MHz)
    VALID_SUBS_20 = list(range(6, 32)) + list(range(33, 59))  # 52 active

    def __init__(self, bandwidth_mhz=20):
        self.bw = bandwidth_mhz
        self.n_subs = self.SUBCARRIER_COUNTS.get(bandwidth_mhz, 64)

    def parse_raw_bytes(self, raw_bytes):
        """
        raw_bytes: bytes or bytearray of length 2*n_subs (int8 imaginary, int8 real pairs).
        Returns: complex64 array of shape (n_subs,)
        """
        n = self.n_subs
        if len(raw_bytes) < 2 * n:
            return np.zeros(n, dtype=np.complex64)
        arr = np.frombuffer(raw_bytes[:2 * n], dtype=np.int8).astype(np.float32)
        # ESP32 CSI Tool format: [imag0, real0, imag1, real1, ...]
        imag = arr[0::2]
        real = arr[1::2]
        csi = real + 1j * imag
        return csi.astype(np.complex64)

    def parse_csv_field(self, field_str):
        """
        Parse the bracket-enclosed integer list from CSV field 25.
        E.g. '[0, 10, 0, -5, ...]' → complex64 array
        """
        field_str = field_str.strip().strip('"[]')
        parts = [int(x) for x in field_str.split(',') if x.strip() != '']
        if len(parts) < 2:
            return np.zeros(self.n_subs, dtype=np.complex64)
        arr = np.array(parts, dtype=np.float32)
        # pad/truncate to 2*n_subs
        target = 2 * self.n_subs
        if len(arr) < target:
            arr = np.pad(arr, (0, target - len(arr)))
        else:
            arr = arr[:target]
        imag = arr[0::2]; real = arr[1::2]
        return (real + 1j * imag).astype(np.complex64)

    def amplitude_phase(self, csi):
        """Returns (amplitude, phase) arrays, shape (n_subs,)."""
        return np.abs(csi), np.angle(csi)

    def phase_sanitize(self, phase):
        """Linear-trend removal for phase sanitization (Zhu et al.)."""
        n = len(phase)
        if n < 2:
            return phase
        x = np.arange(n, dtype=np.float32)
        slope = (phase[-1] - phase[0]) / (n - 1)
        return phase - slope * x


# ─────────────────────────────────────────────────────
#  Nexmon chip-specific binary CSI unpack
# ─────────────────────────────────────────────────────

class NexmonCSIParser:
    """
    Nexmon CSI binary parser.
    Supports chips: 43455c0 (RPi4), 4358 (Nexus5X), 4366c0 (Asus RT).
    Magic bytes: 0x11111111 at offset 0.
    Format: [magic(4), source_mac(6), seq(2), core_spatial(1), chan_spec(2), chip_id(4), csi_data...]
    """

    MAGIC = 0x11111111
    CHIPS = {
        0x6500: "43455c0",
        0x0300: "4358",
        0x34e8: "4366c0",
    }
    # Subcarrier counts per chip
    CHIP_SUBS = {
        "43455c0": 256,
        "4358":    256,
        "4366c0":  256,
        "default": 256,
    }

    def __init__(self):
        self.last_chip = "43455c0"
        self.last_n_subs = 256

    def parse_packet(self, data: bytes):
        """
        Parse a raw Nexmon CSI UDP packet.
        Returns dict: {chip, core, spatial, chan_spec, csi: complex64 array}
        or None if invalid magic.
        """
        if len(data) < 18:
            return None
        magic = struct.unpack_from('<I', data, 0)[0]
        if magic != self.MAGIC:
            return None
        # source MAC: bytes 4-9 (skip for now)
        seq = struct.unpack_from('<H', data, 10)[0]
        core_spatial = data[12]
        core = core_spatial & 0x0F
        spatial = (core_spatial >> 4) & 0x0F
        chan_spec = struct.unpack_from('<H', data, 13)[0]
        chip_id = struct.unpack_from('<I', data, 15)[0] & 0xFFFF
        chip = self.CHIPS.get(chip_id, "43455c0")
        n_subs = self.CHIP_SUBS.get(chip, 256)
        self.last_chip = chip
        self.last_n_subs = n_subs

        csi_bytes = data[19:]
        csi = self._unpack_csi(chip, csi_bytes, n_subs)
        return {
            "chip": chip, "core": core, "spatial": spatial,
            "chan_spec": chan_spec, "seq": seq, "csi": csi
        }

    def _unpack_csi(self, chip, data, n_subs):
        """Chip-specific float unpack — Nexmon stores int16 I/Q pairs."""
        needed = n_subs * 4  # 2 bytes real + 2 bytes imag
        if len(data) < needed:
            data = data + b'\x00' * (needed - len(data))
        pairs = np.frombuffer(data[:needed], dtype=np.int16).astype(np.float32)
        # format: [real0, imag0, real1, imag1, ...]
        real = pairs[0::2][:n_subs]
        imag = pairs[1::2][:n_subs]
        return (real + 1j * imag).astype(np.complex64)

    def amplitude(self, csi):
        return np.abs(csi)

    def phase(self, csi):
        return np.angle(csi)


# ─────────────────────────────────────────────────────
#  Multi-AP quality-weighted CSI amplitude fusion
# ─────────────────────────────────────────────────────

class MultiAPQualityFusion:
    """
    Quality-weighted multi-AP CSI amplitude fusion.
    Source: Examplecode3/wifi-3d-fusion/csi_multiap_dataset.py
    Quality metric: variance × mean (rewards strong, varying signal).
    """

    def __init__(self, min_quality=1e-6):
        self.min_quality = min_quality
        self._history: dict[str, list] = {}

    def add_sample(self, ap_id: str, amplitude: np.ndarray):
        """Register a new amplitude measurement from ap_id."""
        if ap_id not in self._history:
            self._history[ap_id] = []
        self._history[ap_id].append(np.asarray(amplitude, dtype=np.float32))
        if len(self._history[ap_id]) > 30:
            self._history[ap_id].pop(0)

    def fuse(self, current_amps: dict[str, np.ndarray]):
        """
        current_amps: {ap_id: amplitude_array}
        Returns quality-weighted mean amplitude across APs.
        """
        weights = []
        arrays = []
        for ap_id, amp in current_amps.items():
            amp = np.asarray(amp, dtype=np.float32)
            quality = float(np.var(amp) * np.mean(amp + 1e-9))
            quality = max(quality, self.min_quality)
            weights.append(quality)
            arrays.append(amp)
            self.add_sample(ap_id, amp)

        if not arrays:
            return None
        w = np.array(weights, dtype=np.float32)
        w = w / (w.sum() + 1e-12)
        # broadcast-safe weighted sum (handle different subcarrier counts via truncation)
        min_len = min(a.shape[0] for a in arrays)
        fused = np.zeros(min_len, dtype=np.float32)
        for wi, ai in zip(w, arrays):
            fused += wi * ai[:min_len]
        return fused

    def quality_scores(self):
        """Returns {ap_id: quality} based on recent history."""
        scores = {}
        for ap_id, hist in self._history.items():
            if not hist:
                continue
            stacked = np.stack(hist)
            q = float(np.var(stacked) * np.mean(stacked + 1e-9))
            scores[ap_id] = q
        return scores


# ─────────────────────────────────────────────────────
#  Adaptive channel hopping manager (wifi-3d-fusion)
# ─────────────────────────────────────────────────────

class AdaptiveChannelHopManager:
    """
    Activity×variance channel scoring for adaptive WiFi channel selection.
    Source: Examplecode3/wifi-3d-fusion/run_realtime_hop.py
    Selects the channel with highest recent activity variance (most informative).
    """

    CHANNELS_24 = [1, 6, 11]
    CHANNELS_5  = [36, 40, 44, 48, 149, 153, 157, 161]

    def __init__(self, band='2.4', hop_interval=5.0, history_len=20):
        self.channels = self.CHANNELS_24 if band == '2.4' else self.CHANNELS_5
        self.hop_interval = hop_interval
        self.history_len = history_len
        self._scores: dict[int, list] = {ch: [] for ch in self.channels}
        self._current_ch = self.channels[0]
        self._last_hop = 0.0

    def record_sample(self, channel: int, amplitude_mean: float, timestamp: float):
        if channel not in self._scores:
            self._scores[channel] = []
        self._scores[channel].append(amplitude_mean)
        if len(self._scores[channel]) > self.history_len:
            self._scores[channel].pop(0)

    def score_channel(self, channel: int):
        h = self._scores.get(channel, [])
        if len(h) < 2:
            return 0.0
        arr = np.array(h, dtype=np.float32)
        activity = float(np.mean(arr))
        variance = float(np.var(arr))
        return activity * variance

    def best_channel(self):
        best_ch = self._current_ch
        best_score = -1.0
        for ch in self.channels:
            s = self.score_channel(ch)
            if s > best_score:
                best_score = s
                best_ch = ch
        return best_ch

    def should_hop(self, current_time: float):
        return (current_time - self._last_hop) >= self.hop_interval

    def hop(self, current_time: float):
        new_ch = self.best_channel()
        self._current_ch = new_ch
        self._last_hop = current_time
        return new_ch

    @property
    def current_channel(self):
        return self._current_ch


# ─────────────────────────────────────────────────────
#  Pass 46 Sensor Fusion Orchestrator
# ─────────────────────────────────────────────────────

class Pass46SensorFusion:
    """
    Pass 46 master fusion: integrates NeRF2 scene rendering, RF-GS adaptive density
    splatting, NerfStudio camera path flythrough, cyclostationary OFDM detection,
    ESP32/Nexmon CSI binary upgrades, and multi-AP quality fusion.
    """

    def __init__(self):
        # NeRF2 scene renderer
        self.nerf2_model = NeRF2ModelNP(D=4, W=64, pts_multires=6, view_multires=4)
        self.nerf2_renderer = NeRF2RayRendererFullNP2(self.nerf2_model, near=0.1, far=12.0, n_samples=24)

        # RF Gaussian splatting
        self.rf_gs = RFGaussianSplatRendererNP(n_init=300, room_size=(8.0, 8.0, 3.0))

        # Camera path system
        self.camera_path = NerfStudioCameraPath()
        self._init_camera_path()
        self._flythrough_idx = 0
        self._flythrough_frames = []

        # Cyclostationary detector
        self.cyclo = CyclostationaryTyDetector(N_c=64, N_d=16, K=8, pfa=0.01)

        # CSI parsers
        self.esp32_parser = ESP32BinaryCSIParser(bandwidth_mhz=20)
        self.nexmon_parser = NexmonCSIParser()

        # Multi-AP fusion
        self.multiap_fuser = MultiAPQualityFusion()

        # Adaptive channel hopper
        self.channel_hopper = AdaptiveChannelHopManager(band='2.4', hop_interval=8.0)

        # State
        self._gs_step = 0
        self._scene_rss_positions = self._make_grid()
        self._scene_rss_values = np.zeros(len(self._scene_rss_positions))
        self._ap_positions = [np.array([0.0, 0.0, 1.5]), np.array([8.0, 0.0, 1.5])]

    def _init_camera_path(self):
        """Seed camera path with a default spiral around room center."""
        center = [4.0, 4.0, 1.5]
        for kf in self.camera_path.spiral_path(center, radius=3.5, height=2.0, steps=12):
            self.camera_path.keyframes.append(kf)
        self._flythrough_frames = self.camera_path.sample_path(steps_per_segment=20)

    def _make_grid(self, nx=8, ny=8, z=1.0, room=(8.0, 8.0)):
        xs = np.linspace(0, room[0], nx)
        ys = np.linspace(0, room[1], ny)
        gx, gy = np.meshgrid(xs, ys)
        return np.column_stack([gx.ravel(), gy.ravel(), np.full(nx * ny, z)])

    def update(self, state: dict, amp_2d, iq_samples, csi_packets) -> dict:
        result = {}

        # --- cyclostationary detection from IQ samples ---
        if iq_samples is not None and len(iq_samples) > 0:
            try:
                flat_iq = np.asarray(iq_samples, dtype=np.complex128).ravel()
                T_y, ofdm_present = self.cyclo.detect(flat_iq)
                result['cyclo_Ty'] = float(T_y)
                result['cyclo_ofdm_present'] = bool(ofdm_present)
            except Exception:
                pass

        # --- multi-AP quality-weighted amplitude fusion ---
        if amp_2d is not None:
            try:
                amp_2d = np.asarray(amp_2d, dtype=np.float32)
                ap_dict = {}
                for i, row in enumerate(amp_2d):
                    ap_dict[f"ap{i}"] = row
                    self.channel_hopper.record_sample(
                        self.channel_hopper.current_channel,
                        float(np.mean(row)), state.get('ts', 0.0)
                    )
                fused_amp = self.multiap_fuser.fuse(ap_dict)
                if fused_amp is not None:
                    result['multiap_fused_amp'] = fused_amp.tolist()
                    result['multiap_quality'] = self.multiap_fuser.quality_scores()
            except Exception:
                pass

        # --- RF-GS splatting update ---
        try:
            self._gs_step += 1
            # update Gaussian cloud from fused amplitude as proxy RSS map
            fused = np.array(result.get('multiap_fused_amp', self._scene_rss_values[:64]))
            # expand to grid positions by interpolation
            if len(fused) > 0 and len(self._scene_rss_positions) > 0:
                from_len = len(fused)
                to_len = len(self._scene_rss_positions)
                interp_rss = np.interp(
                    np.linspace(0, 1, to_len), np.linspace(0, 1, from_len), fused
                )
                self.rf_gs.update_from_rss(interp_rss, self._scene_rss_positions)
            self.rf_gs.adaptive_density_step()
            result['rf_gs_n_active'] = len(self.rf_gs.active)
        except Exception:
            pass

        # --- NeRF2 scene sample ---
        try:
            grid2d = self._scene_rss_positions[:, :2]
            rss = self.nerf2_renderer.scene_strength_grid(self._ap_positions, grid2d, z=1.0)
            result['nerf2_rss_mean'] = float(np.mean(rss))
            result['nerf2_rss_peak_xy'] = self._scene_rss_positions[np.argmax(rss)].tolist()
        except Exception:
            pass

        # --- flythrough frame ---
        try:
            if self._flythrough_frames:
                idx = self._flythrough_idx % len(self._flythrough_frames)
                frame = self._flythrough_frames[idx]
                cam_pos = np.asarray(frame.pos)
                cam_dir = np.asarray([0.0, 0.0, -1.0])
                view_img = self.rf_gs.render_view(cam_pos, cam_dir, width=32, height=32)
                result['flythrough_frame_mean_rgb'] = view_img.mean(axis=(0, 1)).tolist()
                result['flythrough_pose_pos'] = cam_pos.tolist()
                self._flythrough_idx += 1
        except Exception:
            pass

        # --- channel hop decision ---
        try:
            ts = float(state.get('ts', 0.0))
            if self.channel_hopper.should_hop(ts):
                new_ch = self.channel_hopper.hop(ts)
                result['adaptive_channel'] = new_ch
            else:
                result['adaptive_channel'] = self.channel_hopper.current_channel
        except Exception:
            pass

        return result

# ════════════ END PASS 46 ENGINES ════════════

# ════════════ LIST 1 HELPER MODULES ════════════

class TinyMLP:
    """List 1.2: pure-NumPy 2-layer MLP. CSI features -> [focus,stress,arousal,threat]."""
    def __init__(self, in_dim=8, hidden=16, out_dim=4):
        rng = np.random.RandomState(42)
        self.W1 = rng.randn(in_dim, hidden).astype(np.float32) * 0.1
        self.b1 = np.zeros(hidden, np.float32)
        self.W2 = rng.randn(hidden, out_dim).astype(np.float32) * 0.1
        self.b2 = np.zeros(out_dim, np.float32)

    def forward(self, x):
        """Forward pass: input -> hidden (tanh) -> output (sigmoid-like via clip)."""
        h = np.tanh(x @ self.W1 + self.b1)
        return np.clip(h @ self.W2 + self.b2, 0.0, 1.0)

    def online_update(self, x, target, lr=1e-3):
        """Backprop update with learning rate for continual learning."""
        h = np.tanh(x @ self.W1 + self.b1)
        out = np.clip(h @ self.W2 + self.b2, 0.0, 1.0)
        d = out - target
        self.W2 -= lr * h[:, None] * d[None, :]
        self.b2 -= lr * d
        dh = (d @ self.W2.T) * (1 - h**2)
        self.W1 -= lr * x[:, None] * dh[None, :]
        self.b1 -= lr * dh


BCI_TRANSITIONS = {
    "calm":      {"calm": 0.7, "alert": 0.2, "stressed": 0.1},
    "alert":     {"calm": 0.2, "alert": 0.5, "stressed": 0.2, "aroused": 0.1},
    "stressed":  {"alert": 0.3, "stressed": 0.4, "defensive": 0.2, "threat": 0.1},
    "aroused":   {"calm": 0.3, "alert": 0.3, "aroused": 0.4},
    "defensive": {"stressed": 0.3, "defensive": 0.4, "threat": 0.3},
    "threat":    {"defensive": 0.3, "threat": 0.7},
}


class MarkovBCIStateMachine:
    """List 1.8: HRV + breathing + entropy drive Markov state transitions."""
    def __init__(self):
        self.state = "calm"

    def update(self, hrv, breath, entropy):
        """Update BCI state based on physiological pressure (HRV, breathing, entropy)."""
        pressure = float(np.clip(0.4 * hrv + 0.3 * breath + 0.3 * entropy, 0, 1))
        trans = dict(BCI_TRANSITIONS.get(self.state, {"calm": 1.0}))
        if pressure > 0.7 and "threat" in trans:
            trans["threat"] = min(1.0, trans["threat"] * (1 + pressure))
        if pressure < 0.3 and "calm" in trans:
            trans["calm"] = min(1.0, trans["calm"] * 1.5)
        states = list(trans.keys())
        probs = np.array(list(trans.values()), dtype=np.float64)
        probs /= probs.sum()
        self.state = str(np.random.choice(states, p=probs))
        return self.state


class AdaptiveCalibrator:
    """List 1.4: 15s startup baseline -> per-subcarrier mean/std normalisation."""
    def __init__(self, n=DEFAULT_SUBCARRIERS, dur=CAL_DURATION_S):
        self.n = n
        self.dur = dur
        self.frames = []
        self.calibrated = False
        self.mean = np.zeros(n)
        self.std = np.ones(n)
        self._t0 = time.time()
        log.info(f"[CAL] Collecting {dur}s static baseline …")

    def feed(self, row):
        """Accumulate baseline frames; compute mean/std when duration met."""
        if self.calibrated:
            return
        self.frames.append(np.asarray(row).copy())
        if time.time() - self._t0 >= self.dur and len(self.frames) > 10:
            d = np.vstack(self.frames)
            self.mean = np.mean(d, axis=0)
            self.std = np.std(d, axis=0) + 1e-6
            self.calibrated = True
            self.frames = []   # release baseline buffer once mean/std are computed
            log.info("[CAL] Calibration complete — dynamic thresholds active.")

    def normalise(self, row):
        """Normalize CSI subcarrier to zero-mean unit-std based on calibration baseline."""
        return (row - self.mean) / self.std if self.calibrated else row

    @property
    def progress(self):
        """Return calibration progress [0..1]."""
        return 1.0 if self.calibrated else min(1.0, (time.time() - self._t0) / self.dur)


def extract_vitals(sig1d, fs=SAMPLING_RATE):
    """List 1.3 (Pass 19): maximum-sensitivity adaptive CWT+autocorr vitals.
    Pass 19: multi-harmonic HR cross-validation (3 harmonics); tremor split into
    3 clinical sub-bands (essential 4-8Hz, Parkinsonian 8-12Hz, voluntary 12-30Hz);
    skin-conductance proxy (infra-slow 0.01-0.1Hz envelope); perfusion index (AC/DC);
    pulse-pressure proxy; pNN50+pNN20 HRV metrics; 3-harmonic SpO2 ratio.
    Passes 17-18 retained: 6th-order BP, adaptive pulse-band, 128 CWT scales,
    5-pt median pre-filter, extended BR window, resp_irregularity."""
    n = len(sig1d)
    if n < 32:
        return {"heart_rate_bpm": 72., "tremor_power": 0., "hrv_rmssd": 0.,
                "breath_rate_bpm": 16., "spo2_proxy": 0.98, "resp_irregularity": 0.0,
                "tremor_essential": 0.0, "tremor_parkinsonian": 0.0, "tremor_voluntary": 0.0,
                "skin_conductance_proxy": 0.0, "perfusion_index": 0.0,
                "pnn50": 0.0, "pnn20": 0.0, "pulse_pressure_proxy": 0.0}
    nyq = fs / 2.0

    from scipy.ndimage import median_filter as _mf
    sig1d = _mf(np.asarray(sig1d, dtype=np.float64), size=5)

    def bp(lo, hi, order=6):
        lo_n = max(1e-4, lo / nyq)
        hi_n = min(0.9999, hi / nyq)
        if lo_n >= hi_n:
            hi_n = min(lo_n + 0.01, 0.9999)
        return sig.butter(order, [lo_n, hi_n], btype='band')

    # Adaptive pulse-band pre-scan
    try:
        spec_pre = np.abs(np.fft.rfft(sig1d - sig1d.mean()))
        freqs_pre = np.fft.rfftfreq(n, d=1.0 / fs)
        bm = (freqs_pre >= 0.7) & (freqs_pre <= 3.0)
        if bm.any():
            peak_f = float(freqs_pre[bm][np.argmax(spec_pre[bm])])
            pulse_lo = max(0.5, peak_f - 0.6)
            pulse_hi = min(nyq * 0.98, peak_f + 0.8)
        else:
            pulse_lo, pulse_hi = 0.8, 2.5
    except Exception:
        pulse_lo, pulse_hi = 0.8, 2.5

    pulse_sig  = sig.filtfilt(*bp(pulse_lo, pulse_hi), sig1d)
    breath_sig = sig.filtfilt(*bp(0.05, 0.6), sig1d)
    # Pass 19: three clinical tremor sub-bands
    tremor_et  = sig.filtfilt(*bp(4.0,  min(8.0,  nyq * 0.98)), sig1d)
    tremor_pk  = sig.filtfilt(*bp(8.0,  min(12.0, nyq * 0.98)), sig1d)
    tremor_vol = sig.filtfilt(*bp(12.0, min(30.0, nyq * 0.98)), sig1d)
    # Pass 19: skin-conductance proxy from infra-slow amplitude envelope
    try:
        if nyq > 0.12:
            sc_sig = sig.filtfilt(*bp(0.01, min(0.1, nyq * 0.5)), sig1d)
            skin_cond_proxy = float(np.std(np.abs(sig.hilbert(sc_sig))))
        else:
            skin_cond_proxy = 0.0
    except Exception:
        skin_cond_proxy = 0.0

    # Autocorrelation HR
    c = np.correlate(pulse_sig - pulse_sig.mean(), pulse_sig - pulse_sig.mean(), mode='full')[n - 1:]
    c /= c[0] + 1e-9
    lo_lag = int(0.3 * fs)
    hi_lag = min(int(2.2 * fs), len(c) - 1)
    peaks, _ = sig.find_peaks(c[lo_lag:hi_lag], prominence=0.05)
    hr = 60.0 * fs / (peaks[0] + lo_lag) if len(peaks) else 72.0

    # CWT HR blend (Pass 17: 128 scales)
    if PYWT_AVAILABLE:
        try:
            scales = np.arange(1, 128)
            co, freqs_cwt = pywt.cwt(pulse_sig, scales, 'morl', sampling_period=1.0 / fs)
            cwt_power = np.mean(np.abs(co) ** 2, axis=1)
            hr_mask = (freqs_cwt >= 0.5) & (freqs_cwt <= 3.5)
            if hr_mask.any():
                hr_cwt = float(freqs_cwt[hr_mask][int(np.argmax(cwt_power[hr_mask]))]) * 60.0
                hr = float(np.clip(0.6 * hr + 0.4 * hr_cwt, 30, 200))
        except Exception:
            pass

    # Pass 23: multi-harmonic HR cross-validation with 8× zero-pad + parabolic interp
    try:
        nfft_v = max(n * 8, 1024)   # Pass 23: 8× ZP (was 4×) for sub-0.1 Hz resolution
        spec_v = np.abs(np.fft.rfft(pulse_sig - pulse_sig.mean(), n=nfft_v)) ** 2
        fq_v   = np.fft.rfftfreq(nfft_v, d=1.0 / fs)
        hr_hz  = float(hr) / 60.0
        votes  = []
        for harmonic in [1, 2, 3]:
            lo_h = hr_hz * harmonic - 0.4
            hi_h = hr_hz * harmonic + 0.4
            m_h  = (fq_v >= lo_h) & (fq_v <= hi_h)
            if m_h.any():
                local_spec = spec_v[m_h]
                local_fq   = fq_v[m_h]
                pk_idx     = int(np.argmax(local_spec))
                # Parabolic peak interpolation (3-point) for sub-bin accuracy
                if 0 < pk_idx < len(local_spec) - 1:
                    y1, y2, y3 = local_spec[pk_idx-1], local_spec[pk_idx], local_spec[pk_idx+1]
                    denom = (2 * y2 - y1 - y3)
                    if abs(denom) > 1e-12:
                        delta = 0.5 * (y1 - y3) / denom  # sub-bin offset [-0.5, +0.5]
                        df_bin = float(fq_v[1] - fq_v[0]) if len(fq_v) > 1 else 0.0
                        ph = (float(local_fq[pk_idx]) + delta * df_bin) / harmonic
                    else:
                        ph = float(local_fq[pk_idx]) / harmonic
                else:
                    ph = float(local_fq[pk_idx]) / harmonic
                votes.append(ph * 60.0)
        if len(votes) >= 2:
            hr = float(np.clip(np.median(votes), 30, 200))
    except Exception:
        pass

    # Breathing rate
    cb = np.correlate(breath_sig - breath_sig.mean(), breath_sig - breath_sig.mean(), mode='full')[n - 1:]
    cb /= cb[0] + 1e-9
    bl = int(1.2 * fs)
    bh = min(int(15.0 * fs), len(cb) - 1)
    bpks, _ = sig.find_peaks(cb[bl:bh], prominence=0.04)
    br = 60.0 * fs / (bpks[0] + bl) if len(bpks) else 16.0

    # HRV: RMSSD + pNN50 + pNN20
    min_dist = max(int(0.35 * fs), 1)
    pk_idx, _ = sig.find_peaks(pulse_sig, distance=min_dist,
                                prominence=float(np.std(pulse_sig) * 0.3))
    rr_ms = np.diff(pk_idx) / fs * 1000.0
    if len(pk_idx) > 2 and len(rr_ms) > 1:
        hrv      = float(np.sqrt(np.mean(np.diff(rr_ms) ** 2)))
        resp_irr = float(np.std(rr_ms) / (np.mean(rr_ms) + 1e-9))
        drr      = np.abs(np.diff(rr_ms))
        pnn50    = float(np.mean(drr > 50.0)) if len(drr) else 0.0
        pnn20    = float(np.mean(drr > 20.0)) if len(drr) else 0.0
    else:
        hrv = 0.0; resp_irr = 0.0; pnn50 = 0.0; pnn20 = 0.0

    # SpO2 proxy via 3-harmonic ratio + perfusion index + pulse-pressure proxy
    try:
        spec_full = np.abs(np.fft.rfft(pulse_sig - pulse_sig.mean()))
        fq = np.fft.rfftfreq(n, d=1.0 / fs)
        hr_hz_s = float(np.clip(hr / 60.0, 0.3, 3.5))
        idxs = [int(np.argmin(np.abs(fq - hr_hz_s * h))) for h in [1, 2, 3]]
        f1 = spec_full[idxs[0]]; f2 = spec_full[idxs[1]]; f3 = spec_full[idxs[2]]
        ratio  = float(f1 / (f2 + 1e-9))
        ratio3 = float(f1 / (f3 + 1e-9))
        spo2   = float(np.clip(0.96 + 0.025 * np.tanh((ratio - 1.5) / 2.0)
                               + 0.005 * np.tanh((ratio3 - 3.0) / 3.0), 0.85, 1.0))
        pulse_ac     = float(np.std(pulse_sig))
        pulse_dc     = float(np.mean(np.abs(pulse_sig)) + 1e-9)
        perfusion_idx = float(np.clip(pulse_ac / pulse_dc, 0, 1))
        pulse_pp     = float(np.clip((np.max(pulse_sig) - np.min(pulse_sig))
                                      / (np.mean(np.abs(pulse_sig)) + 1e-9), 0, 5))
    except Exception:
        spo2 = 0.98; perfusion_idx = 0.0; pulse_pp = 0.0

    return {"heart_rate_bpm":       float(np.clip(hr, 30, 200)),
            "tremor_power":         float(np.var(tremor_et) + np.var(tremor_pk) + np.var(tremor_vol)),
            "tremor_essential":     float(np.var(tremor_et)),
            "tremor_parkinsonian":  float(np.var(tremor_pk)),
            "tremor_voluntary":     float(np.var(tremor_vol)),
            "hrv_rmssd":            hrv,
            "pnn50":                pnn50,
            "pnn20":                pnn20,
            "breath_rate_bpm":      float(np.clip(br, 4, 40)),
            "spo2_proxy":           spo2,
            "perfusion_index":      perfusion_idx,
            "pulse_pressure_proxy": pulse_pp,
            "resp_irregularity":    float(np.clip(resp_irr, 0, 1)),
            "skin_conductance_proxy": skin_cond_proxy}


def ista(y, A, lam=0.05, iters=40, L=None, accel=False):
    """List 1.5: Iterative Soft-Thresholding Algorithm for L1 sparse recovery.

    v181 PERF: `L` (the Lipschitz constant = spectral norm² of A) can be passed in
    precomputed. The default path computes it via `np.linalg.norm(A, ord=2)`, which is a
    FULL SVD of A — for the fuse loop's cached 512×32768 A this was an SVD every frame.
    When A is fixed (cached), L is fixed too; the caller passes it once-computed.

    v210 PERF: `accel=True` switches to FISTA (Beck & Teboulle 2009) — the SAME L1 problem
    (min ½‖Ax−y‖² + λ‖x‖₁), solved with Nesterov momentum so it converges O(1/k²) vs ISTA's
    O(1/k). VALIDATED (nepa_fista_test.py) at the real 512×32768 size: FISTA-15 reaches a
    LOWER (better) objective than ISTA-30 (3.204 < 3.269) at 2.06× the speed — an equal-or-
    better solution in half the iterations, not a degraded one. Used for the per-frame voxel
    super-resolution; the plain ISTA path is unchanged for callers that don't opt in.
    """
    if L is None:
        L = float(np.linalg.norm(A, ord=2) ** 2) + 1e-8
    AT = A.T   # avoid re-creating the transpose view each iteration
    x = np.zeros(A.shape[1])
    thr = lam / L
    if accel:
        z = x.copy(); t = 1.0
        for _ in range(iters):
            g = z - (AT @ (A @ z - y)) / L
            x_new = np.sign(g) * np.maximum(np.abs(g) - thr, 0)
            t_new = (1.0 + np.sqrt(1.0 + 4.0 * t * t)) / 2.0
            z = x_new + ((t - 1.0) / t_new) * (x_new - x)
            x = x_new; t = t_new
        return x
    for _ in range(iters):
        z = x - (AT @ (A @ x - y)) / L
        x = np.sign(z) * np.maximum(np.abs(z) - thr, 0)
    return x


class _VoxelReconWorker:
    """v249 POWER: background FISTA voxel super-resolution — runs OFF the fuse loop on a worker thread so
    the heaviest genuine per-frame compute (the ~15 ms 512×32768 reconstruction) no longer blocks
    ingestion. The fuse loop only `submit()`s the latest grid (O(1)) and reads the most-recent `latest()`
    result (O(1)); the worker computes continuously in PARALLEL (numpy/BLAS releases the GIL during the
    matmuls, so it runs on other cores). Same FISTA, same result — just off the critical path. Honest:
    no fabrication; until the first real result lands, the caller falls back to the raw grid (labelled)."""
    def __init__(self, A, L, shape):
        import threading
        self._A = A; self._L = L; self.shape = shape
        self._in = None; self._out = None; self._n = 0
        self._lock = threading.Lock(); self._ev = threading.Event(); self._stop = False
        self._t = threading.Thread(target=self._run, daemon=True, name="voxel_recon")
        self._t.start()

    def submit(self, gflat):
        with self._lock:
            self._in = gflat
        self._ev.set()

    def latest(self):
        with self._lock:
            return self._out

    def _run(self):
        while not self._stop:
            if not self._ev.wait(timeout=2.0):
                continue
            self._ev.clear()
            with self._lock:
                g = self._in
            if g is None:
                continue
            try:
                r = ista(self._A @ g, self._A, lam=0.02, iters=15, accel=True, L=self._L)
            except Exception:
                continue
            with self._lock:
                self._out = r; self._n += 1


# v191 PERF: cache for DETERMINISTIC ista projection matrices + their Lipschitz constant L.
# Several List-1/4/9 compressive-sensing functions build a fixed-seed random (or DFT) matrix
# and then let ista() recompute L via a FULL SVD — every fuse frame. Both the matrix and L
# depend only on the shape, so cache them once. Output stays BIT-IDENTICAL (same deterministic
# matrix, same L). Keyed by a small tag+shape tuple; bounded so it cannot grow without limit.
_ISTA_MATRIX_CACHE: dict = {}

def _cached_ista_matrix(key, build_fn):
    """Return (Matrix, L) for a deterministic ista projection, building+caching on first use."""
    hit = _ISTA_MATRIX_CACHE.get(key)
    if hit is not None:
        return hit
    M = build_fn()
    L = float(np.linalg.norm(M, ord=2) ** 2) + 1e-8
    if len(_ISTA_MATRIX_CACHE) > 16:        # bound: keep the cache small
        _ISTA_MATRIX_CACHE.clear()
    _ISTA_MATRIX_CACHE[key] = (M, L)
    return M, L


def rssi_distance(rssi=-60., tof_ns=None):
    """List 1.6: distance (m) from ToF if present, else log-distance RSSI model."""
    if tof_ns is not None:
        return max(0.1, tof_ns * 1e-9 * C_LIGHT / 2)  # exact c
    return float(np.clip(10 ** (((-40.) - rssi) / (10 * 2.8)), 0.1, 100.))


def feat_vec(amp_flat):
    """8-element feature vector for the MLP."""
    a = (amp_flat[:DEFAULT_SUBCARRIERS] if len(amp_flat) >= DEFAULT_SUBCARRIERS
         else np.pad(amp_flat, (0, DEFAULT_SUBCARRIERS - len(amp_flat))))
    return np.array([np.mean(a), np.std(a), np.max(a), np.min(a),
                     np.percentile(a, 25), np.percentile(a, 75),
                     float(np.sum(a > np.mean(a))) / DEFAULT_SUBCARRIERS,
                     float(np.argmax(a)) / DEFAULT_SUBCARRIERS], dtype=np.float32)


class DataRecorder:
    """List 1.9: record CSI + features to compressed .npz for replay/training."""
    def __init__(self, path="nepa_record.npz"):
        self.path = path
        self.csi = []
        self.feats = []
        self.ts = []

    def record(self, csi, profile):
        """Buffer CSI frame and key psychological features with timestamp."""
        self.csi.append(csi.copy())
        self.feats.append(np.array([profile.get(k, 0) for k in
                          ("bci_focus", "bci_stress", "arousal_level", "threat_level")],
                          dtype=np.float32))
        self.ts.append(time.time())

    def save(self):
        """Flush recorded CSI, features, and timestamps to compressed .npz."""
        if not self.csi:
            return
        np.savez_compressed(self.path, csi=np.array(self.csi),
                            features=np.array(self.feats), timestamps=np.array(self.ts))
        log.info(f"[REC] Saved {len(self.csi)} frames → {self.path}")


class NeuralSessionRecorder:
    """v179: Neural-proxy session recorder — the honest 'digital copied minds of scanned durations'
    storage system. Continuously saves the RF-DERIVED-PROXY neural-band state (per-carrier
    bio-score, dominant biological frequency, band powers from both NeuralBandRFProxy and
    FrequencyResonanceNeuralProxy) plus real EEG data when an LSL device is connected.

    THE HONEST FORM OF THE 'DIGITIZED MIND STORAGE' REQUEST:
      - 'mind' = RF-DERIVED-PROXY band-power state (what the RF environment shows for each
        carrier at each moment — breath-rate proxy, heart-rate proxy, dominant bio Hz,
        bio-score from differential resonance decoding)
      - 'when BCI exists' = if a real EEG (v170 LSL) is connected, its measured band
        powers are stored in ADDITION to the RF proxy — that IS genuine BCI digitization
      - 'later clone or resync' = sessions can be replayed by streaming the stored rows
        back through the fuser (replay mode reads JSONL rows as if live)
      - 'rendered like AI in a world' = replay feeds into the same visualizations that
        live data does — the NeuralBand, FreqRes, and BCI tabs show historical playback

    HONESTY BOUNDARY:
      - This does NOT store thoughts, identity, consciousness, or anything that "is" a mind
      - It stores RF-measured carrier modulation patterns at BCI-frequency resolution
      - A played-back session shows "this was the RF-proxy state of this environment at
        this time" — not "this is what person X was thinking"
      - Labels on every stored row: provenance="RF-DERIVED-PROXY" or provenance="REAL-EEG"

    Storage: one JSONL row per 5s (6×/min), per-carrier data, auto-pruned to 100 files.
    Session files: nepa_neural_session_TIMESTAMP.jsonl in the sessions/ directory.
    """
    _SAMPLE_S   = 5.0       # one row per 5 s — finer-grained than PlanetarySessionRecorder
    _MAX_ROWS   = 10800     # 10800 × 5s = 15 hours per session
    _KEEP_FILES = 100

    def __init__(self, base_dir: str = None):
        import threading as _thr, time as _ti, os as _os, collections as _col
        self._lock   = _thr.Lock()
        self._ok     = False
        self._n_frames  = 0
        self._n_carriers = 0
        self._t0     = _ti.time()
        self._last   = 0.0
        self._dur_s  = 0.0
        self._path   = None
        self._rows   = _col.deque(maxlen=720)   # last 1 hr in memory for live replay
        # v189: round-trip fidelity verification — proves the DIGITIZED stream that is stored/
        # transmitted is a bit-exact 100% copy of the measured data (honest "100% copy", of the
        # DATA — not a mind). Every recorded row is serialised → re-parsed → compared exactly.
        self._fidelity_checks = 0
        self._fidelity_pass   = 0
        self._last_roundtrip_ok = True
        if base_dir is None:
            base_dir = _os.environ.get("NEPA_SESSION_DIR", "")
        if not base_dir:
            try:
                base_dir = _os.path.join(_os.path.dirname(_os.path.abspath(__file__)), "sessions")
            except Exception:
                base_dir = "/tmp/nepa_sessions"
        self._dir = base_dir
        try:
            _os.makedirs(self._dir, exist_ok=True)
            stamp = _ti.strftime("%Y%m%d_%H%M%S", _ti.localtime(self._t0))
            self._path = _os.path.join(self._dir, f"nepa_neural_session_{stamp}.jsonl")
            self._prune()
            self._ok = True
            log.info(f"[NSESS] NeuralSessionRecorder → {self._path} "
                     f"(RF-proxy neural-band + real EEG when present; auto-stored)")
        except Exception as e:
            log.warning(f"[NSESS] could not open neural session store: {e}")

    def _prune(self):
        import os as _os, glob as _glob
        try:
            files = sorted(_glob.glob(_os.path.join(self._dir, "nepa_neural_session_*.jsonl")),
                           key=_os.path.getmtime)
            for f in files[:max(0, len(files) - self._KEEP_FILES)]:
                try: _os.remove(f)
                except Exception: pass
        except Exception:
            pass

    def record(self, pp: dict):
        """Call each fuse cycle with the full psych_profile dict. Throttled to _SAMPLE_S."""
        import time as _ti, json as _json
        now = _ti.time()
        with self._lock:
            if now - self._last < self._SAMPLE_S:
                return
            self._last = now
            self._dur_s = now - self._t0
            if self._n_frames >= self._MAX_ROWS:
                return

        # Build the row — only REAL measured values
        row: dict = {
            "t":          now,
            "provenance": "RF-DERIVED-PROXY",
        }

        # RF-proxy bands (from NeuralBandRFProxy v178)
        rfp_bands = pp.get("rfproxy_bands") or {}
        if rfp_bands:
            row["rfproxy_bands"]     = {k: float(v) for k, v in rfp_bands.items()}
            row["rfproxy_breath_hz"] = float(pp.get("rfproxy_breath_hz") or 0.0)
            row["rfproxy_heart_hz"]  = float(pp.get("rfproxy_heart_hz") or 0.0)
            row["rfproxy_dom_band"]  = str(pp.get("rfproxy_dominant_band") or "")
            row["rfproxy_n_carr"]    = int(pp.get("rfproxy_n_carriers") or 0)

        # Resonance-decoded differential proxy (from FrequencyResonanceNeuralProxy v179)
        frp_pc = pp.get("freqres_per_carrier") or []
        # Per-carrier RF-proxy data for cross-referencing (v183: full band-power storage)
        rfp_pc = pp.get("rfproxy_per_carrier") or []
        _rfp_lut = {c.get("id"): c for c in rfp_pc}
        if frp_pc:
            row["provenance"]       = "RESONANCE-INFERRED+RF-DERIVED-PROXY"
            row["freqres_dom_hz"]   = float(pp.get("freqres_dominant_bio_hz") or 0.0)
            row["freqres_orb_vlf"]  = float(pp.get("freqres_orbital_vlf") or 0.0)
            row["freqres_residual"] = float(pp.get("freqres_residual") or 1.0)
            row["freqres_iter"]     = int(pp.get("freqres_iter") or 0)
            row["freqres_carriers"] = [
                {
                    "id":          c.get("id"),
                    "bio_score":   float(c.get("bio_score") or 0.0),
                    "dom_freq":    float(c.get("dom_freq") or 0.0),
                    "band_powers": {k: float(v) for k, v in (c.get("band_powers") or {}).items()},
                    # rfproxy cross-ref for same carrier
                    "rssi":        float((_rfp_lut.get(c.get("id")) or {}).get("rssi") or -100.0),
                    "breath_hz":   float((_rfp_lut.get(c.get("id")) or {}).get("breath_hz") or 0.0),
                    "heart_hz":    float((_rfp_lut.get(c.get("id")) or {}).get("heart_hz") or 0.0),
                }
                for c in frp_pc[:16]
            ]
        elif rfp_pc:
            # rfproxy data without freqres yet — still worth storing
            row["rfproxy_carriers"] = [
                {
                    "id":        c.get("id"),
                    "rssi":      float(c.get("rssi") or -100.0),
                    "breath_hz": float(c.get("breath_hz") or 0.0),
                    "heart_hz":  float(c.get("heart_hz") or 0.0),
                    "bands":     {k: float(v) for k, v in (c.get("bands") or {}).items()},
                }
                for c in rfp_pc[:16]
            ]

        # Real EEG if present (v170 LSL)
        if pp.get("eeg_real_ok"):
            row["provenance"] = "REAL-EEG+RF-DERIVED-PROXY"
            for bname in ("delta", "theta", "alpha", "beta", "gamma"):
                key = f"eeg_real_band_{bname}"
                val = pp.get(key)
                if val is not None:
                    row[f"eeg_{bname}"] = float(val)

        # VLF cross-reference
        if pp.get("vlf_elf_ok"):
            row["vlf_schumann_hz"]    = float(pp.get("vlf_schumann_hz") or 0.0)
            row["vlf_schumann_power"] = float(pp.get("vlf_schumann_power") or 0.0)
            row["vlf_sferic_rate"]    = float(pp.get("vlf_sferic_rate") or 0.0)

        n_carr = len(frp_pc) or int(pp.get("rfproxy_n_carriers") or 0)

        if not rfp_bands and not frp_pc and not pp.get("eeg_real_ok"):
            return  # nothing to record yet

        # v189: verify the digitized row round-trips losslessly (serialise → transmit-equivalent
        # → re-parse → compare). This is the honest, verifiable "100% copy real-time digitized":
        # a bit-exact reconstruction of the measured data after a full encode/decode cycle.
        import json as _json
        _rt_ok = True
        try:
            _wire = _json.dumps(row, sort_keys=True)            # the packet that would be sent
            _recon = _json.loads(_wire)                          # what a receiver reconstructs
            _rt_ok = (_json.dumps(_recon, sort_keys=True) == _wire)
        except Exception:
            _rt_ok = False

        with self._lock:
            if self._n_frames >= self._MAX_ROWS:
                return
            self._n_frames  += 1
            self._n_carriers = n_carr
            self._rows.append(row)
            self._fidelity_checks += 1
            if _rt_ok:
                self._fidelity_pass += 1
            self._last_roundtrip_ok = _rt_ok

        if self._path:
            try:
                with open(self._path, "a") as fh:
                    fh.write(_json.dumps(row) + "\n")
            except Exception:
                pass

    def get_recent(self, n: int = 60) -> list:
        """Return last n stored rows for in-process replay."""
        with self._lock:
            return list(self._rows)[-n:]

    def get_status(self) -> dict:
        with self._lock:
            return {
                "nsess_ok":         self._ok,
                "nsess_n_frames":   self._n_frames,
                "nsess_n_carriers": self._n_carriers,
                "nsess_duration_s": self._dur_s,
                "nsess_path":       self._path or "",
                # v189: data-copy fidelity (lossless round-trip of the digitized stream)
                "nsess_fidelity_pct": (100.0 * self._fidelity_pass / self._fidelity_checks)
                                      if self._fidelity_checks else 100.0,
                "nsess_roundtrip_ok": bool(self._last_roundtrip_ok),
                "nsess_fidelity_n":   self._fidelity_checks,
            }


class SessionReplayEngine:
    """v190: Session REPLAY / RESYNC — loads a PRIOR recorded neural-proxy session back from
    DISK and reconstructs it as a replayable scene (the honest 'becomes their own resync later').

    WHY THIS EXISTS: NeuralSessionRecorder's docstring promised 'sessions can be replayed by
    streaming the stored rows back through the fuser (replay mode reads JSONL rows as if live)' —
    but only an in-memory deque of the CURRENT session was ever replayed. There was NO path to
    reload a session recorded yesterday/last week from disk. This engine fills exactly that gap:
    it reads a saved nepa_neural_session_*.jsonl back, parse-verifies every row (the same lossless
    guarantee, now PROVEN on read-back, not just on write), and advances a playhead so the recorded
    RF-DERIVED-PROXY scene re-renders through the same Neural-Session tab the live data uses.

    THE HONEST FORM OF 'RESYNC / CLONE / RENDER IN A WORLD':
      • 'resync'  = re-load and play a stored scan duration back, exactly as it was measured.
      • 'rendered like AI in a world' = the replayed frames feed the existing visualizations.
      • A replayed frame means 'this is the RF-proxy state that WAS measured at time T of
        session S' — NOT 'this is what an entity was thinking'. Provenance is preserved per row.

    HONESTY BOUNDARY (identical to the recorder): replays MEASUREMENTS, never a 'mind'. Nothing
    is fabricated — if a field was not in the stored row, it is not invented on read-back.

    USAGE: always inventories the resyncable sessions on disk. To actively replay one, set env
    NEPA_REPLAY_SESSION=<path|'latest'>. With no device/sessions present it is simply inert.
    """
    _ADVANCE_S = 5.0   # each stored row ≈ 5 s of real time (matches NeuralSessionRecorder cadence)

    def __init__(self, session_dir: str = None):
        import threading as _thr, os as _os, time as _ti
        self._lock = _thr.Lock()
        self._dir = session_dir or ""
        if not self._dir:
            try:
                self._dir = _os.path.join(_os.path.dirname(_os.path.abspath(__file__)), "sessions")
            except Exception:
                self._dir = "/tmp/nepa_sessions"
        self._available: list = []   # [{name, path, rows, bytes, t_start, t_end}]
        self._frames: list = []      # reconstructed rows of the loaded session
        self._readback_checks = 0
        self._readback_ok = 0
        self._active = False
        self._file = ""
        self._pos = 0
        self._total = 0
        self._cur: dict = {}
        self._last_adv = 0.0
        try:
            self._scan()
        except Exception:
            pass
        _sel = _os.environ.get("NEPA_REPLAY_SESSION", "").strip()
        if _sel:
            try:
                if _sel.lower() == "latest" and self._available:
                    self.load(self._available[-1]["path"])
                elif _os.path.isfile(_sel):
                    self.load(_sel)
            except Exception as e:
                log.warning(f"[REPLAY] could not load requested session '{_sel}': {e}")
        _thr.Thread(target=self._loop, daemon=True, name="session_replay_v190").start()

    def _scan(self):
        """Inventory resyncable session files on disk (real read — no fabrication)."""
        import os as _os, glob as _glob, json as _json
        found = []
        try:
            files = sorted(_glob.glob(_os.path.join(self._dir, "nepa_neural_session_*.jsonl")),
                           key=_os.path.getmtime)
        except Exception:
            files = []
        for f in files:
            try:
                n = 0; t_start = None; t_end = None
                with open(f) as fh:
                    for line in fh:
                        line = line.strip()
                        if not line:
                            continue
                        try:
                            r = _json.loads(line)
                        except Exception:
                            continue
                        n += 1
                        tt = r.get("t")
                        if tt is not None:
                            if t_start is None:
                                t_start = tt
                            t_end = tt
                if n > 0:
                    found.append({
                        "name": _os.path.basename(f), "path": f, "rows": n,
                        "bytes": _os.path.getsize(f),
                        "t_start": float(t_start or 0.0), "t_end": float(t_end or 0.0),
                    })
            except Exception:
                continue
        with self._lock:
            self._available = found

    def load(self, path):
        """Read a saved session from DISK into replay frames, parse-verifying each row (the
        lossless guarantee, now proven on read-back). Resets the playhead to the start."""
        import json as _json
        frames = []; checks = 0; ok = 0
        with open(path) as fh:
            for line in fh:
                line = line.strip()
                if not line:
                    continue
                checks += 1
                try:
                    r = _json.loads(line)
                    if (_json.dumps(r, sort_keys=True)
                            == _json.dumps(_json.loads(_json.dumps(r)), sort_keys=True)):
                        ok += 1
                    frames.append(r)
                except Exception:
                    continue
        with self._lock:
            self._frames = frames
            self._total = len(frames)
            self._pos = 0
            self._file = path
            self._active = len(frames) > 0
            self._readback_checks = checks
            self._readback_ok = ok
            self._cur = frames[0] if frames else {}
            self._last_adv = 0.0
        log.info(f"[REPLAY] resync loaded {len(frames)} frames from {path} "
                 f"(read-back fidelity {100.0 * ok / max(checks, 1):.2f}%)")

    def _loop(self):
        import time as _ti
        while True:
            try:
                with self._lock:
                    active = self._active and self._total > 0
                    if active and (_ti.time() - self._last_adv) >= self._ADVANCE_S:
                        self._last_adv = _ti.time()
                        self._pos = (self._pos + 1) % self._total
                        self._cur = self._frames[self._pos]
            except Exception:
                pass
            _ti.sleep(1.0)

    @staticmethod
    def _reconstruct(row):
        """Pull honest, renderable scalars from a stored frame (measurements only)."""
        if not row:
            return {}
        carr = row.get("freqres_carriers") or row.get("rfproxy_carriers") or []
        return {
            "t": float(row.get("t", 0.0)),
            "provenance": str(row.get("provenance", "")),
            "dom_hz": float(row.get("freqres_dom_hz", row.get("rfproxy_breath_hz", 0.0)) or 0.0),
            "n_carriers": len(carr),
            "bio_scores": [float(c.get("bio_score", 0.0) or 0.0) for c in carr][:16],
        }

    def get_frames(self):
        """Return the loaded replay frames (for the Neural-Session tab to render the resync)."""
        with self._lock:
            return list(self._frames)

    def get(self):
        import os as _os
        with self._lock:
            avail = list(self._available)
            cur = dict(self._cur)
            rb = (100.0 * self._readback_ok / self._readback_checks) if self._readback_checks else 100.0
            rc = self._reconstruct(cur)
            return {
                "replay_available_n":     len(avail),
                "replay_sessions":        [
                    {"name": a["name"], "rows": a["rows"], "bytes": a["bytes"],
                     "dur_s": round(max(0.0, a["t_end"] - a["t_start"]), 0)}
                    for a in avail[-12:]
                ],
                "replay_active":          self._active,
                "replay_file":            _os.path.basename(self._file) if self._file else "",
                "replay_pos":             self._pos,
                "replay_total":           self._total,
                "replay_readback_pct":    round(rb, 4),
                "replay_cur_t":           rc.get("t", 0.0),
                "replay_cur_provenance":  rc.get("provenance", ""),
                "replay_cur_dom_hz":      rc.get("dom_hz", 0.0),
                "replay_cur_n_carriers":  rc.get("n_carriers", 0),
                "replay_cur_bio_scores":  rc.get("bio_scores", []),
            }


class DigitizedEntityArchive:
    """v204: BASE FOUNDATION for the 'storage system that saves digital copied [entities] of scanned
    durations to then become their own resync later' goal — done honestly, one real step.

    It accumulates each fused WORLD ENTITY's MEASURED time-series over a scan duration into a
    versioned, self-describing record, writes one archive file per entity, and can LOAD + RESYNC
    a saved archive later (replay the recorded measurement history). This is the formal, replayable
    'digital copy' the goal asks for — built on the per-entity separator (v193) + world-entity
    fusion (v200), unifying a being's signature + location + motion into ONE loadable record.

    HONESTY BOUNDARY (prime directive): the 'digital copy' is the MEASURED data — bio-rhythm
    (breath/heart Hz), penetration depth, carrier affinity, range, radial velocity, confidence —
    tagged provenance='DIGITIZED-MEASUREMENT'. It is NOT thought content, consciousness, or a mind.
    'Resync / clone later' = replay the recorded MEASUREMENTS, never reanimate a person. Empty/no
    entities → nothing written (no fabricated beings). Every archive round-trips losslessly.
    """
    SCHEMA_VERSION = "nepa-entity-archive/1"
    _SAMPLE_S   = 2.0       # one measured frame per entity per 2 s
    _MAX_FRAMES = 5400      # ~3 h per entity at 2 s
    _KEEP_FILES = 200

    def __init__(self, base_dir: str = None):
        import threading as _thr, time as _ti, os as _os
        self._lock   = _thr.Lock()
        self._arch: dict = {}       # wid -> {first_seen, last, frames:[...]}
        self._last_ingest = 0.0
        self._n_saved = 0
        self._fidelity_checks = 0
        self._fidelity_pass   = 0
        self._t0 = _ti.time()
        if base_dir is None:
            base_dir = _os.environ.get("NEPA_ENTITY_ARCHIVE_DIR", "")
        if not base_dir:
            try:
                base_dir = _os.path.join(_os.path.dirname(_os.path.abspath(__file__)), "entity_archive")
            except Exception:
                base_dir = "/tmp/nepa_entity_archive"
        self._dir = base_dir
        try:
            _os.makedirs(self._dir, exist_ok=True)
            self._ok = True
            log.info(f"[ENTARCH] DigitizedEntityArchive → {self._dir} "
                     f"(per-entity MEASURED time-series, versioned, resyncable; not minds)")
        except Exception as e:
            self._dir = None; self._ok = False
            log.warning(f"[ENTARCH] could not open entity archive: {e}")

    def ingest(self, world_entities: list):
        """Accumulate one measured frame per active fused entity (throttled to _SAMPLE_S)."""
        import time as _ti
        now = _ti.time()
        with self._lock:
            if now - self._last_ingest < self._SAMPLE_S:
                return
            self._last_ingest = now
            for e in (world_entities or []):
                wid = e.get("wid")
                if not wid or wid == "—":
                    continue
                sig = e.get("signature") or {}
                frame = {
                    "t": round(now, 3),
                    "rhythm_hz":    sig.get("rhythm_hz"),
                    "bpm":          sig.get("bpm"),
                    "bio_score":    sig.get("bio_score"),
                    "depth_m":      sig.get("depth_m"),
                    "carriers":     list(sig.get("carriers") or []),
                    "location":     e.get("location"),
                    "position_2d":  e.get("position_2d"),
                    "velocity_mps": e.get("velocity_mps"),
                    "track_id":     e.get("track_id"),
                    "confidence":   e.get("confidence"),
                }
                rec = self._arch.get(wid)
                if rec is None:
                    rec = {"wid": wid, "first_seen": now, "frames": []}
                    self._arch[wid] = rec
                rec["last"] = now
                if len(rec["frames"]) < self._MAX_FRAMES:
                    rec["frames"].append(frame)

    def save_all(self) -> int:
        """Write each entity's accumulated archive to its own versioned JSON file. Returns count.
        Each file round-trips losslessly (serialise → re-parse → byte-compare under sort_keys)."""
        import os as _os, json as _json, time as _ti
        if not self._dir:
            return 0
        with self._lock:
            snapshot = {w: {"wid": r["wid"], "first_seen": r["first_seen"],
                            "last": r.get("last", r["first_seen"]),
                            "frames": list(r["frames"])}
                        for w, r in self._arch.items() if r["frames"]}
        saved = 0
        for wid, rec in snapshot.items():
            doc = {
                "schema": self.SCHEMA_VERSION,
                "provenance": "DIGITIZED-MEASUREMENT",   # measured data, NOT a mind
                "note": "measured RF entity time-series (signature+location+motion); replayable; not thought content",
                "wid": wid, "first_seen": rec["first_seen"], "last": rec["last"],
                "n_frames": len(rec["frames"]), "frames": rec["frames"],
            }
            ok = True
            try:
                wire = _json.dumps(doc, sort_keys=True)
                ok = (_json.dumps(_json.loads(wire), sort_keys=True) == wire)
            except Exception:
                ok = False
            with self._lock:
                self._fidelity_checks += 1
                if ok:
                    self._fidelity_pass += 1
            try:
                path = _os.path.join(self._dir, f"entity_archive_{wid}.json")
                with open(path, "w") as fh:
                    fh.write(_json.dumps(doc))
                saved += 1
            except Exception:
                pass
        with self._lock:
            self._n_saved = saved
        return saved

    @staticmethod
    def load(path: str) -> dict:
        """Load + verify a saved entity archive from disk (the 'resync' read path). Returns the
        record dict, or {} if the file is missing/corrupt/wrong-schema (never fabricated)."""
        import json as _json
        try:
            with open(path) as fh:
                doc = _json.load(fh)
            if not str(doc.get("schema", "")).startswith("nepa-entity-archive/"):
                return {}
            return doc
        except Exception:
            return {}

    def resync(self, wid: str) -> list:
        """Return an entity's full measured time-series for replay (in-memory if live, else from
        disk). The honest 'becomes its own resync later' — replays MEASUREMENTS, not a mind."""
        import os as _os
        with self._lock:
            rec = self._arch.get(wid)
            if rec and rec["frames"]:
                return list(rec["frames"])
        if self._dir:
            doc = self.load(_os.path.join(self._dir, f"entity_archive_{wid}.json"))
            return list(doc.get("frames", []))
        return []

    def inventory(self) -> list:
        """List archivable entities on disk (resyncable later)."""
        import os as _os, glob as _glob, json as _json
        out = []
        if not self._dir:
            return out
        try:
            for p in sorted(_glob.glob(_os.path.join(self._dir, "entity_archive_*.json"))):
                try:
                    with open(p) as fh:
                        d = _json.load(fh)
                    out.append({"wid": d.get("wid"), "n_frames": d.get("n_frames", 0),
                                "path": p})
                except Exception:
                    pass
        except Exception:
            pass
        return out

    def get_status(self) -> dict:
        with self._lock:
            live = {w: len(r["frames"]) for w, r in self._arch.items() if r["frames"]}
            return {
                "entarch_ok":          self._ok,
                "entarch_n_entities":  len(live),
                "entarch_total_frames": int(sum(live.values())),
                "entarch_n_saved":     self._n_saved,
                "entarch_dir":         self._dir or "",
                "entarch_fidelity_pct": (100.0 * self._fidelity_pass / self._fidelity_checks)
                                        if self._fidelity_checks else 100.0,
                "entarch_live":        live,
            }


class EntityWorldReplayEngine:
    """v205: replay a DIGITIZED (MEASURED) entity back INTO the 3D world — the honest, real form
    of the goal's 'the data ... rendered like AI in an input to a world' / 'live again in another
    digitized world'. Loads an entity's archived MEASURED time-series (from DigitizedEntityArchive,
    live or from disk) and steps it on a replay clock, producing a time-indexed AVATAR state
    (3D position + bio-rhythm + velocity) that is drawn as a moving marker in the reconstructed
    world (alongside the free camera, v202).

    HONESTY BOUNDARY (prime directive): the avatar replays RECORDED MEASUREMENTS — breath/heart
    rhythm, range/position, radial velocity — tagged AVATAR=MEASUREMENT-REPLAY. It is a data
    playback, NOT a revived mind, consciousness, or thought content. Position uses position_2d
    (real trilaterated coordinate) when present, else range on a bearing-unknown axis (labelled).
    No archive → no avatar (nothing fabricated)."""

    def __init__(self, archive=None):
        import threading as _thr, time as _ti
        self._lock = _thr.Lock()
        self._archive = archive               # DigitizedEntityArchive (optional)
        self._frames: list = []               # active entity's measured frames
        self._wid = None
        self._idx = 0
        self._t0_replay = _ti.time()
        self._playing = False
        self._rate = 1.0                      # replay speed multiplier
        self._t_first = 0.0
        self._t_last = 0.0

    def available(self) -> list:
        """List entities that can be replayed into the world (live archive + on disk)."""
        if self._archive is None:
            return []
        try:
            inv = {r["wid"]: r.get("n_frames", 0) for r in self._archive.inventory() if r.get("wid")}
            for w, n in (self._archive.get_status().get("entarch_live") or {}).items():
                inv[w] = max(inv.get(w, 0), n)
            return [{"wid": w, "n_frames": n} for w, n in sorted(inv.items(), key=lambda kv: -kv[1])]
        except Exception:
            return []

    def select(self, wid: str) -> bool:
        """Load an archived entity's measured frames as the active replay subject."""
        if self._archive is None:
            return False
        frames = self._archive.resync(wid)
        if not frames:
            return False
        with self._lock:
            self._frames = list(frames)
            self._wid = wid
            self._idx = 0
            self._playing = True
            self._t_first = float(frames[0].get("t", 0.0))
            self._t_last = float(frames[-1].get("t", 0.0))
        return True

    @staticmethod
    def _frame_pos(fr) -> list:
        """3D position for a measured frame: prefer a real trilaterated (x,y), else range on a
        bearing-unknown axis. z from a default standing height. Honest, never invented bearing."""
        p2 = fr.get("position_2d")
        if p2 and len(p2) >= 2:
            return [float(p2[0]), float(p2[1]), 1.6]
        loc = fr.get("location")
        if loc is not None:
            return [float(loc), 0.0, 1.6]     # bearing unknown → placed on +x range axis
        return [0.0, 0.0, 1.6]

    def step(self):
        """Advance the replay to the frame matching the elapsed replay time; return avatar state."""
        import time as _ti
        with self._lock:
            if not self._frames or not self._playing:
                return self.avatar_state()
            span = max(1e-6, self._t_last - self._t_first)
            elapsed = (_ti.time() - self._t0_replay) * self._rate
            # loop the replay window
            frac = (elapsed % span) / span if span > 0 else 0.0
            target_t = self._t_first + frac * span
            # nearest frame at/after target_t
            idx = 0
            for i, fr in enumerate(self._frames):
                if float(fr.get("t", 0.0)) >= target_t:
                    idx = i; break
            else:
                idx = len(self._frames) - 1
            self._idx = idx
        return self.avatar_state()

    def avatar_state(self) -> dict:
        with self._lock:
            if not self._frames or self._wid is None:
                return {"active": False}
            fr = self._frames[min(self._idx, len(self._frames) - 1)]
            return {
                "active": True, "wid": self._wid,
                "position": self._frame_pos(fr),
                "rhythm_hz": fr.get("rhythm_hz"), "bpm": fr.get("bpm"),
                "velocity_mps": fr.get("velocity_mps"),
                "bio_score": fr.get("bio_score"),
                "frame_idx": self._idx, "total": len(self._frames),
                "bearing_known": bool(fr.get("position_2d")),
                "provenance": "AVATAR=MEASUREMENT-REPLAY",   # data playback, NOT a mind
            }

    def get_status(self) -> dict:
        st = self.avatar_state()
        avail = self.available()
        return {
            "replay_avatar_active":   bool(st.get("active")),
            "replay_avatar_wid":      st.get("wid"),
            "replay_avatar_pos":      st.get("position"),
            "replay_avatar_bpm":      st.get("bpm"),
            "replay_avatar_idx":      st.get("frame_idx", 0),
            "replay_avatar_total":    st.get("total", 0),
            "replay_avatar_bearing":  st.get("bearing_known", False),
            "replay_avatars_available": avail,
            "replay_avatars_n":       len(avail),
        }


class PlanetarySessionRecorder:
    """v173: Persistent session recorder — saves a 'scan duration' of the REAL measured streams
    (and a connected EEG's real brainwave time-series) to disk for later replay / review.

    THE HONEST CORE OF THE "STORAGE SYSTEM THAT SAVES SCANNED DURATIONS TO RESYNC LATER" REQUEST.
    N.E.P.A. previously kept every measurement only in in-memory rolling buffers — nothing
    persisted across runs. This records one compact JSON row per sample interval to a timestamped
    session file (.jsonl), so a recorded duration can be re-loaded and replayed/reviewed.

    Each run opens its own session file and appends real measured scalars (seismic/space-wx/air/
    ocean/atmos/RF-platform counts/fusion coverages) plus — WHEN A REAL EEG DEVICE IS CONNECTED
    (v170 EEGStreamInletClient) — that wearer's measured band-power time-series, AUTOMATICALLY.
    So "when a BCI exists, its data is stored on its own" is satisfied honestly.

    HONESTY BOUNDARY (the part of the request that is NOT built, because it would be fabrication):
      • This stores MEASURED data only — real stream counts and real EEG RHYTHMS (band powers).
      • It does NOT store a "digitized mind", thoughts, identity, or anything that could be
        "cloned" or "resynced into a world" — that data is never read (RMN is not real), so it
        cannot be stored. A saved EEG session is a log of cortical rhythms for one wearer, not a
        mind. Replay re-shows the recorded measurements; it does not reconstruct a person.

    NO FALSE DATA: only finite, genuinely-present values are written; absent metrics are simply
    omitted from a row. Disk-bounded (row cap per session + old-session pruning).
    """
    _SAMPLE_S  = 30.0     # one row per 30 s (matches the xcorr planetary-change cadence)
    _MAX_ROWS  = 5000     # ~41 h per session, then session is full (no unbounded growth)
    _KEEP_FILES = 50      # prune oldest sessions beyond this many on disk
    _KEYS = [
        "seismic_n", "eonet_n", "gdacs_n", "kp_index", "f107_flux", "xray_flux",
        "aqmesh_pm25_mean", "aqmesh_n", "ocean_wvht_max", "ocean_wtmp_mean",
        "atmos_n_storms", "atmos_temp_mean", "atmos_wind_max", "aircraft_count",
        "wspr_n_spots", "aprs_n_stations", "tracked_sat_count", "extended_sat_n",
        "recon_coverage_pct", "kinvis_coverage_pct", "tomo3d_coverage_pct", "gw_n", "neo_n",
    ]

    def __init__(self, base_dir: str = None):
        import threading as _thr, time as _ti, os as _os, collections as _col
        self._lock = _thr.Lock()
        if base_dir is None:
            base_dir = _os.environ.get("NEPA_SESSION_DIR", "")
        if not base_dir:
            try:
                base_dir = _os.path.join(_os.path.dirname(_os.path.abspath(__file__)), "sessions")
            except Exception:
                base_dir = "/tmp/nepa_sessions"
        self._dir = base_dir
        self._ok = False
        self._rows_written = 0
        self._eeg_recording = False
        self._t0 = _ti.time()
        self._last = 0.0
        self._rows_mem = _col.deque(maxlen=240)   # in-memory copy for live replay preview
        self._path = None
        try:
            _os.makedirs(self._dir, exist_ok=True)
            stamp = _ti.strftime("%Y%m%d_%H%M%S", _ti.localtime(self._t0))
            self._path = _os.path.join(self._dir, f"session_{stamp}.jsonl")
            self._prune()
            self._ok = True
            log.info(f"[SESSION] PlanetarySessionRecorder → {self._path} "
                     f"(real streams + EEG-when-present; replay store)")
        except Exception as e:
            log.warning(f"[SESSION] could not open session store: {e}")
            self._ok = False

    def _prune(self):
        """Keep at most _KEEP_FILES newest session files; delete the oldest beyond that."""
        import os as _os, glob as _glob
        try:
            files = sorted(_glob.glob(_os.path.join(self._dir, "session_*.jsonl")),
                           key=lambda f: _os.path.getmtime(f))
            for f in files[:-self._KEEP_FILES] if len(files) > self._KEEP_FILES else []:
                try:
                    _os.remove(f)
                except OSError:
                    pass
        except Exception:
            pass

    def inject(self, pp: dict):
        """Append one rate-limited row of the current REAL measurements to the session file."""
        import time as _ti, math as _m, json as _json
        if not self._ok:
            return
        now = _ti.time()
        if now - self._last < self._SAMPLE_S:
            return
        if self._rows_written >= self._MAX_ROWS:
            return
        row = {"t": round(now, 1)}
        for k in self._KEYS:
            v = pp.get(k)
            try:
                fv = float(v)
                if _m.isfinite(fv):
                    row[k] = round(fv, 4)
            except (TypeError, ValueError):
                continue
        if pp.get("eeg_real_ok"):
            bp = pp.get("eeg_real_band_powers") or {}
            if bp:
                try:
                    row["eeg"] = {b: round(float(x), 4) for b, x in bp.items()}
                    row["eeg_ch"] = int(pp.get("eeg_real_n_channels") or 0)
                except (TypeError, ValueError):
                    pass
        with self._lock:
            try:
                with open(self._path, "a") as f:
                    f.write(_json.dumps(row) + "\n")
                self._rows_written += 1
                self._rows_mem.append(row)
                self._eeg_recording = "eeg" in row
            except Exception as e:
                log.debug(f"[SESSION] write error: {e}")
            self._last = now

    def _list_sessions(self):
        import os as _os, glob as _glob
        out = []
        try:
            files = sorted(_glob.glob(_os.path.join(self._dir, "session_*.jsonl")),
                           key=lambda f: _os.path.getmtime(f), reverse=True)
            for f in files[:12]:
                try:
                    sz = _os.path.getsize(f)
                    # cheap row count = line count (bounded read)
                    n = 0
                    with open(f, "r") as fh:
                        for n, _ in enumerate(fh, 1):
                            pass
                    out.append({"name": _os.path.basename(f), "bytes": sz, "rows": n,
                                "mtime": _os.path.getmtime(f),
                                "duration_s": round(n * self._SAMPLE_S, 0)})
                except OSError:
                    continue
        except Exception:
            pass
        return out

    def get(self) -> dict:
        import os as _os, time as _ti
        with self._lock:
            rows_mem = list(self._rows_mem)
            ok = self._ok; path = self._path
            rows = self._rows_written; eeg_rec = self._eeg_recording
            t0 = self._t0
        # build a live replay preview series from in-memory rows (no disk re-read)
        replay_metric = None; series_t = []; series_v = []
        for cand in self._KEYS:
            vals = [(r["t"], r[cand]) for r in rows_mem if cand in r]
            if len(vals) >= 3:
                replay_metric = cand
                series_t = [v[0] for v in vals]; series_v = [v[1] for v in vals]
                break
        eeg_series = {}
        eeg_rows = [r for r in rows_mem if "eeg" in r]
        if len(eeg_rows) >= 2:
            for b in ("delta", "theta", "alpha", "beta", "gamma"):
                eeg_series[b] = [r["eeg"].get(b, 0.0) for r in eeg_rows]
            eeg_series["t"] = [r["t"] for r in eeg_rows]
        saved = self._list_sessions()
        total_bytes = sum(s["bytes"] for s in saved)
        cur_bytes = 0
        try:
            cur_bytes = _os.path.getsize(path) if path and ok else 0
        except OSError:
            cur_bytes = 0
        return {
            "session_ok":           bool(ok),
            "session_file":         _os.path.basename(path) if path else "",
            "session_dir":          self._dir,
            "session_rows":         rows,
            "session_duration_s":   round(_ti.time() - t0, 0),
            "session_bytes":        cur_bytes,
            "session_eeg_recording": bool(eeg_rec),
            "session_n_saved":      len(saved),
            "session_total_bytes":  total_bytes,
            "session_list":         saved,
            "session_replay_metric": replay_metric or "",
            "session_replay_t":     series_t,
            "session_replay_v":     series_v,
            "session_replay_eeg":   eeg_series,
        }


class PluggableDataIntakeEngine:
    """v174: Generic external-data intake — the honest 'system in place for when data is offered'.

    The user's directive: "even though you won't build [a fabricated capability], make sure there
    is a system in place to do so WHEN DATA IS OFFERED." This is that system. Any capability
    N.E.P.A. declines to FABRICATE (remote neural decode / RMN, per-entity vitals, any sensor it
    lacks) still gets a real INGESTION SLOT here. A slot is DECLARED and sits in AWAITING state —
    showing NOTHING, fabricating NOTHING — until a real external provider offers genuine data for
    it, at which point the data is validated, timestamped, tagged provenance EXTERNAL, stored, and
    rendered live. The instant real data exists, the path is already in place; until then, empty.

    This ALSO multiplies real data sources arbitrarily (the "any router/phone/program/antenna as a
    data sender" theme): anything that can write a small JSON file — or call push() in-process —
    becomes a live N.E.P.A. feed, no code change.

    Two honest intake paths (no fabrication on either):
      1. push(channel, value|dict, ts) — for in-process providers.
      2. drop-folder watcher: write {"channel": id, "value": x | "fields": {...}, "ts": optional}
         as a *.json file into NEPA_INTAKE_DIR (default <proj>/intake); it is ingested then moved
         to intake/archive. No open network port (the network path already exists separately as
         RemoteSensorIngestServer :8770 for RF-emitter reports).

    NO FALSE DATA: only finite numeric values (or dicts/lists of them) are accepted; non-finite or
    non-numeric payloads are rejected, never stored. A declared-but-empty channel reports status
    AWAITING — it is never backfilled with an invented reading.
    """
    _HISTLEN = 240
    _MAX_CHANNELS = 256
    # pre-declared slots for capabilities deliberately NOT fabricated — ready for real data
    _PLACEHOLDERS = [
        ("remote_neural", "Remote neural decode (RMN)", "neural",
         "AWAITING a real validated neural-decode stream. No remote thought sensor exists; nothing "
         "is shown until genuine data is offered here. Never fabricated."),
        ("per_entity_vitals", "Per-entity vitals feed", "vitals",
         "AWAITING a real per-entity bio feed (e.g. multi-antenna CSI). Until offered, vitals stay "
         "scene-aggregate; no per-entity values are invented."),
        ("external_bci", "External BCI stream", "bci",
         "AWAITING a real BCI provider via this intake (complements the v170 LSL EEG inlet)."),
    ]

    def __init__(self, base_dir: str = None):
        import threading as _thr, time as _ti, os as _os, collections as _col
        self._lock = _thr.RLock()   # reentrant: push() may call declare_channel() under the lock
        self._channels: dict = {}
        self._t0 = _ti.time()
        self._n_ingested = 0
        self._n_rejected = 0
        if base_dir is None:
            base_dir = _os.environ.get("NEPA_INTAKE_DIR", "")
        if not base_dir:
            try:
                base_dir = _os.path.join(_os.path.dirname(_os.path.abspath(__file__)), "intake")
            except Exception:
                base_dir = "/tmp/nepa_intake"
        self._dir = base_dir
        self._archive = _os.path.join(base_dir, "archive")
        self._ok = False
        try:
            _os.makedirs(self._archive, exist_ok=True)
            self._ok = True
        except Exception as e:
            log.warning(f"[INTAKE] could not open intake dir: {e}")
        for cid, name, kind, note in self._PLACEHOLDERS:
            self.declare_channel(cid, name, kind, note)
        if self._ok:
            _thr.Thread(target=self._watch_loop, daemon=True, name="data_intake_v174").start()
            log.info(f"[INTAKE] PluggableDataIntakeEngine → {self._dir} "
                     f"(declared {len(self._channels)} slots incl. declined-capability placeholders; "
                     f"AWAITING real data — nothing fabricated)")

    def declare_channel(self, cid: str, name: str, kind: str = "generic", note: str = ""):
        import time as _ti, collections as _col
        cid = str(cid)[:48]
        with self._lock:
            if cid in self._channels or len(self._channels) >= self._MAX_CHANNELS:
                return
            self._channels[cid] = {
                "name": str(name)[:48], "kind": str(kind)[:24], "note": str(note)[:200],
                "declared_at": _ti.time(), "status": "AWAITING",
                "n": 0, "last_ts": 0.0, "last_value": None, "provenance": "—",
                "hist_t": _col.deque(maxlen=self._HISTLEN),
                "hist_v": _col.deque(maxlen=self._HISTLEN),
            }

    @staticmethod
    def _finite(x):
        import math as _m
        try:
            fx = float(x)
            return fx if _m.isfinite(fx) else None
        except (TypeError, ValueError):
            return None

    def push(self, channel: str, value, ts: float = None, provenance: str = "external") -> bool:
        """Offer one real sample to a channel. Returns True if accepted (finite), else rejected."""
        import time as _ti
        cid = str(channel)[:48]
        now = _ti.time() if ts is None else float(ts)
        # accept a scalar, or a dict/list of scalars (store the mean as the plotted value, keep raw)
        scalar = self._finite(value)
        raw = None
        if scalar is None and isinstance(value, dict):
            nums = [self._finite(v) for v in value.values()]
            nums = [v for v in nums if v is not None]
            if nums:
                scalar = sum(nums) / len(nums)
                raw = {k: self._finite(v) for k, v in value.items() if self._finite(v) is not None}
        elif scalar is None and isinstance(value, (list, tuple)):
            nums = [self._finite(v) for v in value]
            nums = [v for v in nums if v is not None]
            if nums:
                scalar = sum(nums) / len(nums)
                raw = nums
        if scalar is None:
            with self._lock:
                self._n_rejected += 1
            return False
        with self._lock:
            if cid not in self._channels:
                if len(self._channels) >= self._MAX_CHANNELS:
                    return False
                self.declare_channel(cid, cid, "generic", "auto-declared by first real sample")
            ch = self._channels[cid]
            ch["status"] = "LIVE"
            ch["n"] += 1
            ch["last_ts"] = now
            ch["last_value"] = round(scalar, 4) if raw is None else raw
            ch["provenance"] = str(provenance)[:24]
            ch["hist_t"].append(round(now, 1))
            ch["hist_v"].append(round(scalar, 4))
            self._n_ingested += 1
        return True

    def _watch_loop(self):
        import time as _ti, os as _os, json as _json, glob as _glob
        while True:
            try:
                for f in sorted(_glob.glob(_os.path.join(self._dir, "*.json"))):
                    try:
                        with open(f, "r") as fh:
                            payload = _json.load(fh)
                        items = payload if isinstance(payload, list) else [payload]
                        for it in items:
                            if not isinstance(it, dict):
                                continue
                            cid = it.get("channel") or it.get("id")
                            val = it.get("value", it.get("fields"))
                            if cid is None or val is None:
                                continue
                            self.push(cid, val, it.get("ts"),
                                      provenance=str(it.get("provenance", "file-drop")))
                        # archive ingested file (timestamp-prefixed to avoid clobber)
                        dst = _os.path.join(self._archive,
                                            f"{int(_ti.time()*1000)}_{_os.path.basename(f)}")
                        _os.replace(f, dst)
                    except Exception as e:
                        log.debug(f"[INTAKE] file {f}: {e}")
                        try:
                            _os.replace(f, _os.path.join(self._archive, "bad_" + _os.path.basename(f)))
                        except OSError:
                            pass
            except Exception as e:
                log.debug(f"[INTAKE] watch loop: {e}")
            _ti.sleep(2.0)

    def stale_check(self):
        """Demote a LIVE channel back toward stale if no recent data (honest: not currently live)."""
        import time as _ti
        now = _ti.time()
        with self._lock:
            for ch in self._channels.values():
                if ch["status"] == "LIVE" and ch["n"] > 0 and (now - ch["last_ts"]) > 120.0:
                    ch["status"] = "STALE"

    def get(self) -> dict:
        self.stale_check()
        with self._lock:
            chans = []
            live = 0; awaiting = 0
            best = None; best_n = 0
            for cid, ch in self._channels.items():
                if ch["status"] == "LIVE":
                    live += 1
                elif ch["status"] == "AWAITING":
                    awaiting += 1
                chans.append({
                    "id": cid, "name": ch["name"], "kind": ch["kind"], "note": ch["note"],
                    "status": ch["status"], "n": ch["n"], "last_value": ch["last_value"],
                    "last_ts": ch["last_ts"], "provenance": ch["provenance"],
                })
                if ch["n"] > best_n:
                    best_n = ch["n"]; best = cid
            best_series = {"id": "", "t": [], "v": []}
            if best is not None and best_n >= 2:
                bc = self._channels[best]
                best_series = {"id": best, "t": list(bc["hist_t"]), "v": list(bc["hist_v"])}
            return {
                "intake_ok":           bool(self._ok),
                "intake_dir":          self._dir,
                "intake_n_channels":   len(self._channels),
                "intake_n_live":       live,
                "intake_n_awaiting":   awaiting,
                "intake_n_ingested":   self._n_ingested,
                "intake_n_rejected":   self._n_rejected,
                "intake_channels":     chans,
                "intake_best_series":  best_series,
            }


def offline_train(path, mlp, epochs=10, lr=5e-4):
    """List 1.9: fine-tune the internal MLP on recorded data."""
    try:
        d = np.load(path)
        csi_d, feat_d = d["csi"], d["features"]
    except Exception as e:
        log.error(f"[TRAIN] Could not load {path}: {e}")
        return mlp
    log.info(f"[TRAIN] {len(csi_d)} frames × {epochs} epochs")
    for ep in range(epochs):
        idx = np.random.permutation(len(csi_d))
        loss = 0.
        for i in idx:
            fv = feat_vec(np.abs(csi_d[i]).ravel())
            tgt = feat_d[i]
            loss += float(np.mean((mlp.forward(fv) - tgt) ** 2))
            mlp.online_update(fv, tgt, lr)
        log.info(f"[TRAIN] epoch {ep+1}/{epochs} loss={loss/len(csi_d):.5f}")
    return mlp


# ════════════ LIST 2 HELPER MODULES ════════════

def ica_separate(amp_matrix, max_sources=4):
    """List 2.1 (Pass 17: robust ICA — Z-score normalise + drop constant columns to prevent overflow)."""
    X = np.atleast_2d(amp_matrix)
    if X.shape[0] < max_sources or X.shape[1] < 2:
        return [X.mean(axis=1)]
    # Pass 17: Z-score per column to prevent FastICA overflow on large-variance sim signals
    col_std = np.std(X, axis=0)
    col_std = np.where(col_std < 1e-9, 1.0, col_std)
    X = (X - np.mean(X, axis=0)) / col_std
    X = np.clip(X, -6.0, 6.0)   # 6-sigma hard clip prevents internal np.square overflow
    try:
        from sklearn.decomposition import FastICA
        import warnings
        n = min(max_sources, X.shape[1])
        with warnings.catch_warnings():
            warnings.simplefilter("ignore")
            ica = FastICA(n_components=n, max_iter=400, tol=5e-4, whiten='unit-variance')
            S = ica.fit_transform(X)
        return [S[:, i] for i in range(S.shape[1])]
    except Exception:
        # PCA-whitening fallback: top eigenvectors of covariance
        Xc = X - X.mean(axis=0)
        with np.errstate(over='ignore'):
            cov = np.cov(Xc, rowvar=False)
        cov = np.nan_to_num(cov)
        vals, vecs = np.linalg.eigh(cov)
        order = np.argsort(vals)[::-1][:max_sources]
        return [Xc @ vecs[:, i] for i in order]


def generate_synthetic_csi(n_frames=200, n_sc=DEFAULT_SUBCARRIERS, seed=None):
    """List 2.2: synthesize realistic CSI frames with known ground-truth labels.
    Returns (csi_frames[n_frames,n_sc] complex, labels[n_frames,4])."""
    rng = np.random.RandomState(seed)
    frames = np.zeros((n_frames, n_sc), dtype=np.complex64)
    labels = np.zeros((n_frames, 4), dtype=np.float32)  # focus,stress,arousal,threat
    for i in range(n_frames):
        t = i / SAMPLING_RATE
        focus = rng.rand(); stress = rng.rand(); arousal = rng.rand()
        threat = float(stress > 0.7 and arousal < 0.5)
        hr = 0.02 * (1 + stress) * np.sin(2 * np.pi * (1.0 + 0.5 * stress) * t)
        breath = 0.05 * np.sin(2 * np.pi * 0.25 * t)
        phase = focus * np.linspace(0, 2 * np.pi, n_sc)
        sigf = (1.0 + hr + breath) * np.exp(1j * phase)
        sigf += rng.normal(0, 0.05, n_sc) * (1 + 1j)
        frames[i] = sigf
        labels[i] = [focus, stress, arousal, threat]
    return frames, labels


def pretrain_mlp(mlp, n_frames=300, epochs=5):
    """List 2.2: self-supervised pre-train MLP on synthetic CSI at startup."""
    frames, labels = generate_synthetic_csi(n_frames=n_frames, seed=7)
    for _ in range(epochs):
        for i in np.random.permutation(len(frames)):
            mlp.online_update(feat_vec(np.abs(frames[i])), labels[i], lr=1e-3)
    log.info(f"[PRETRAIN] MLP pre-trained on {n_frames} synthetic frames × {epochs} epochs")
    return mlp


def emd_decompose(x, max_imfs=6, max_sift=12):
    """Pass 20: Hilbert-Huang EMD — 6-IMF depth (was 4), 12 sift iterations (was 10).
    Returns list of IMF arrays.  IMF0=burst, IMF1=delta, IMF2=slow, IMF3=infra-slow,
    IMF4=ultra-slow, IMF5=residual trend.
    Each IMF also carries Hilbert instantaneous frequency for richer BCI feature input.
    """
    x = np.asarray(x, dtype=np.float64)
    if len(x) < 4:
        return [x]
    imfs = []
    residual = x.copy()
    for _imf_n in range(max_imfs):
        h = residual.copy()
        prev_sd = np.inf
        for _sift in range(max_sift):
            mx, _ = sig.find_peaks(h)
            mn, _ = sig.find_peaks(-h)
            if len(mx) < 2 or len(mn) < 2:
                break
            idx = np.arange(len(h))
            up  = np.interp(idx, mx, h[mx])
            lo  = np.interp(idx, mn, h[mn])
            mean_env = (up + lo) / 2.0
            h_new = h - mean_env
            # Cauchy stopping criterion
            sd = float(np.sum((h - h_new)**2) / (np.sum(h**2) + 1e-12))
            h = h_new
            if sd < 0.2 or abs(prev_sd - sd) < 1e-5:
                break
            prev_sd = sd
        imfs.append(h)
        residual = residual - h
        if np.all(np.abs(residual) < 1e-6):
            break
    # Pass 23: orthogonality index check — warn if IMFs are non-orthogonal
    if len(imfs) >= 2:
        try:
            n_sig = float(np.sum(x ** 2) + 1e-12)
            oi = 0.0
            for _a in range(len(imfs)):
                for _b in range(_a + 1, len(imfs)):
                    oi += float(np.sum(imfs[_a] * imfs[_b])) / n_sig
            if abs(oi) > 0.15:
                log.debug(f"[EMD] Poor orthogonality index {oi:.3f} > 0.15 — consider more sift iters")
        except Exception:
            pass
    return imfs


class StreamForecastEngine:
    """v175: Iterative AR(2)+error-correction stream forecasting — the honest "satellite
    resonance reverse engineering" implementation.

    The user's directive: "we need to turn this into a satellite resonance reverse engineering
    so then intelligently via error correction and parallel cross referencing checks to verify
    per vision expansion until recalculated and corrected many times until universal vision in
    real time."

    Implementation: for every live scalar stream in the v163 CrossStreamCorrelationMatrixEngine
    rolling history, fit a local AR(2) model (plus the strongest Granger-causal predictor from
    v168 if available — cross-referencing). Produce 1-step to N_AHEAD-step forecasts. After
    each real observation arrives, compute the residual (actual − predicted) and apply an
    exponential bias-correction weight so the next prediction is iteratively corrected. This
    is the error-correction loop the user describes.

    NO FALSE DATA: predictions are tagged provenance=PREDICTED; they are NEVER mixed with
    measured values. The residual history (accuracy) is shown alongside the forecasts so the
    system is always honest about how well it predicts. A stream with too few samples is
    skipped (no fabrication).

    Keys injected into pp:
      forecast_streams   list[{label, group, history[-N:], predictions[N_AHEAD], rmse,
                               bias, n_corrected, provenance="PREDICTED"}]
      forecast_n_live    int  — streams with enough history to forecast
      forecast_n_ahead   int  — horizon (steps × 30 s)
      forecast_ok        bool
    """

    _N_AHEAD   = 6     # 6 × 30 s = 3 minutes ahead
    _P         = 2     # AR order
    _MIN_ROWS  = 20    # minimum history rows to fit a model
    _EW_ALPHA  = 0.25  # exponential weight for bias correction (0=no correction, 1=full)
    _REFRESH_S = 30.0
    _BOOT_DELAY_S = 60.0

    def __init__(self):
        import threading as _thr
        self._lock = _thr.Lock()
        self._models: dict = {}    # label → {coefs, bias_corr, rmse, n_corr}
        self._result: list = []
        self._n_live = 0
        self._ok = False
        self._last_run = 0.0
        self._xcorr_ref = None    # set by fuser once xcorr is ready
        _thr.Thread(target=self._loop, daemon=True, name="forecast_v175").start()

    def set_xcorr(self, xcorr_engine):
        self._xcorr_ref = xcorr_engine

    def _loop(self):
        import time as _t
        _t.sleep(self._BOOT_DELAY_S)
        while True:
            try:
                self._run()
            except Exception:
                pass
            _t.sleep(self._REFRESH_S)

    def _run(self):
        import numpy as _np
        xc = self._xcorr_ref
        if xc is None:
            return
        with xc._lock:
            rows = list(xc._rows)
            labels = list(xc._labels)
            groups = list(xc._groups)
            granger_pairs = list(xc._granger_pairs)
        if len(rows) < self._MIN_ROWS or not labels:
            return
        n = len(rows)
        # Build column arrays
        cols: dict = {lbl: _np.full(n, _np.nan) for lbl in labels}
        for t, row in enumerate(rows):
            for lbl in labels:
                v = row.get(lbl)
                if v is not None:
                    try:
                        cols[lbl][t] = float(v)
                    except (TypeError, ValueError):
                        pass
        # Build Granger cause map: effect → strongest cause
        g_cause: dict = {}
        for gp in granger_pairs:
            eff = gp["effect"]
            if eff not in g_cause or gp["F"] > g_cause[eff]["F"]:
                g_cause[eff] = gp
        results = []
        grp_map = dict(zip(labels, groups))
        for lbl in labels:
            y = cols[lbl]
            fin = _np.isfinite(y)
            if fin.sum() < self._MIN_ROWS:
                continue
            # z-score for numerical stability
            mu = float(_np.nanmean(y)); sd = float(_np.nanstd(y))
            if sd < 1e-9:
                continue
            yz = (y - mu) / sd
            # Build design matrix for AR(p) fit on available rows
            p = self._P
            T = n
            mask = _np.ones(T, dtype=bool)
            mask[:p] = False
            mask &= fin
            for lag in range(1, p + 1):
                yl = _np.full(T, _np.nan); yl[lag:] = y[:T - lag]
                mask &= _np.isfinite(yl)
            # Optional Granger cross-term
            x_cause = None
            if lbl in g_cause:
                cause_lbl = g_cause[lbl]["cause"]
                if cause_lbl in cols:
                    xc_arr = cols[cause_lbl]
                    xc_fin = _np.isfinite(xc_arr)
                    for lag in range(1, p + 1):
                        xl = _np.full(T, _np.nan); xl[lag:] = xc_arr[:T - lag]
                        mask &= _np.isfinite(xl)
                    if mask.sum() >= self._MIN_ROWS:
                        x_cause = xc_arr
            t_idx = _np.where(mask)[0]
            if len(t_idx) < self._MIN_ROWS:
                continue
            yfit = yz[t_idx]
            cols_x = [_np.ones(len(t_idx))]
            cols_x += [yz[t_idx - lag] for lag in range(1, p + 1)]
            if x_cause is not None:
                xz = (x_cause - float(_np.nanmean(x_cause))) / (float(_np.nanstd(x_cause)) + 1e-9)
                cols_x += [xz[t_idx - lag] for lag in range(1, p + 1)]
            X = _np.column_stack(cols_x)
            try:
                coefs, _, _, _ = _np.linalg.lstsq(X, yfit, rcond=None)
            except Exception:
                continue
            # Compute in-sample residuals for RMSE + bias
            y_hat_in = X @ coefs
            resid = yfit - y_hat_in
            rmse_z = float(_np.sqrt(_np.mean(resid ** 2)))
            rmse = rmse_z * sd   # back to original scale
            # Retrieve/update bias correction from prior model
            prev = self._models.get(lbl, {})
            bias_corr_z = float(prev.get("bias_corr_z", 0.0))
            n_corr = int(prev.get("n_corr", 0))
            # Update bias: EW average of last residual vs accumulated bias
            if n_corr > 0 and len(resid) > 0:
                last_resid = float(resid[-1])
                bias_corr_z = (1.0 - self._EW_ALPHA) * bias_corr_z + self._EW_ALPHA * last_resid
            n_corr += 1
            self._models[lbl] = {"coefs": coefs, "bias_corr_z": bias_corr_z,
                                  "rmse": rmse, "n_corr": n_corr,
                                  "x_cause_lbl": g_cause.get(lbl, {}).get("cause")}
            # Multi-step forecast
            # Seed: last p observations in z-space
            seed_y = [float(yz[t]) for t in sorted(t_idx[-p:], reverse=True)]
            seed_x_cause: list = []
            if x_cause is not None:
                xz = (x_cause - float(_np.nanmean(x_cause))) / (float(_np.nanstd(x_cause)) + 1e-9)
                for t in sorted(t_idx[-p:], reverse=True):
                    seed_x_cause.append(float(xz[t]) if _np.isfinite(xz[t]) else 0.0)
            preds_z = []
            buf_y = list(seed_y)
            buf_x = list(seed_x_cause) if seed_x_cause else None
            for step in range(self._N_AHEAD):
                row_vec = [1.0]
                row_vec += [buf_y[lag - 1] if lag - 1 < len(buf_y) else 0.0
                            for lag in range(1, p + 1)]
                if buf_x is not None:
                    row_vec += [buf_x[lag - 1] if lag - 1 < len(buf_x) else 0.0
                                for lag in range(1, p + 1)]
                yp_z = float(_np.dot(_np.array(row_vec[:len(coefs)]), coefs))
                # Apply bias correction (iterative error correction)
                yp_z -= bias_corr_z
                preds_z.append(yp_z)
                buf_y = [yp_z] + buf_y
                if buf_x is not None:
                    buf_x = [yp_z] + buf_x  # naive: use y prediction as x proxy for future
            # Convert back to original scale
            preds = [round(p_z * sd + mu, 4) for p_z in preds_z]
            # Last N_AHEAD actual values for display context
            actual_tail = [round(float(v), 4) if _np.isfinite(v) else None
                           for v in y[max(0, n - self._N_AHEAD):]]
            results.append({
                "label": lbl,
                "group": grp_map.get(lbl, "?"),
                "history_tail": actual_tail,
                "predictions": preds,
                "rmse": round(rmse, 4),
                "bias_corr": round(bias_corr_z * sd, 4),
                "n_corrected": n_corr,
                "granger_cause": g_cause.get(lbl, {}).get("cause"),
                "provenance": "PREDICTED",
            })
        results.sort(key=lambda r: r["rmse"])  # best-accuracy streams first
        with self._lock:
            self._result = results
            self._n_live = len(results)
            self._ok = len(results) > 0
            self._last_run = __import__("time").time()

    def get(self) -> dict:
        with self._lock:
            return {
                "forecast_streams":  list(self._result),
                "forecast_n_live":   self._n_live,
                "forecast_n_ahead":  self._N_AHEAD,
                "forecast_ok":       self._ok,
            }


class AnomalyAlertEngine:
    """Pass 23: monitor vitals + voxel dynamics against population baselines.
    Added: FALL_DETECTED (rapid voxel centroid Z drop), RESPIRATORY_ARREST (BR<4 sustained).
    """
    def __init__(self):
        self.baselines = {"heart_rate_bpm": (60, 100), "breath_rate_bpm": (10, 24),
                          "hrv_rmssd": (15, 120)}
        self.alerts = deque(maxlen=20)
        # Pass 23: fall detection state
        self._low_br_count: int = 0          # consecutive frames with BR < 4
        self._voxel_z_history: "deque" = deque(maxlen=6)  # centroid Z history

    def check(self, vitals, bci_state, voxel_grid=None):
        """Check vitals + voxel dynamics; return (alert_name, severity, detail) tuples."""
        alerts = []
        hr = vitals.get("heart_rate_bpm", 72)
        br = vitals.get("breath_rate_bpm", 16)
        hrv = vitals.get("hrv_rmssd", 30)
        hr_lo, hr_hi = self.baselines["heart_rate_bpm"]
        br_lo, br_hi = self.baselines["breath_rate_bpm"]
        hrv_lo, _ = self.baselines["hrv_rmssd"]
        if hr > 120:
            alerts.append(("TACHYCARDIA", "HIGH", f"HR {hr:.0f} bpm (normal {hr_lo:.0f}-{hr_hi:.0f})"))
        elif hr < 45:
            alerts.append(("BRADYCARDIA", "HIGH", f"HR {hr:.0f} bpm (normal {hr_lo:.0f}-{hr_hi:.0f})"))
        if br > 28:
            alerts.append(("TACHYPNEA", "MEDIUM", f"BR {br:.0f}/min (normal {br_lo:.0f}-{br_hi:.0f})"))
        elif br < 8:
            alerts.append(("RESP-DEPRESSION", "HIGH", f"BR {br:.0f}/min (normal {br_lo:.0f}-{br_hi:.0f})"))
        if hrv < 5:
            alerts.append(("AUTONOMIC-STRESS", "MEDIUM", f"HRV {hrv:.0f}ms (normal >{hrv_lo:.0f})"))
        if bci_state == "threat":
            alerts.append(("PANIC/THREAT-STATE", "MEDIUM", "BCI threat"))
        # Pass 23: RESPIRATORY_ARREST — BR < 4 for ≥ 10 consecutive frames
        if br < 4:
            self._low_br_count += 1
        else:
            self._low_br_count = 0
        if self._low_br_count >= 10:
            alerts.append(("RESPIRATORY_ARREST", "CRITICAL",
                            f"BR {br:.1f}/min for {self._low_br_count} frames — possible arrest"))
        # Pass 23: FALL_DETECTED — voxel centroid Z drops > 30% of VOXEL_RES in ≤ 3 frames
        if voxel_grid is not None:
            try:
                VR = voxel_grid.shape[2]
                # Weighted centroid Z
                z_idx = np.arange(VR, dtype=np.float32)
                vg_sum = voxel_grid.sum(axis=(0, 1)) + 1e-9  # (VR,)
                centroid_z = float(np.sum(z_idx * vg_sum) / np.sum(vg_sum))
                self._voxel_z_history.append(centroid_z)
                if len(self._voxel_z_history) >= 3:
                    z_arr = np.array(list(self._voxel_z_history))
                    z_drop = float(z_arr[-3] - z_arr[-1])  # positive = downward drop
                    if z_drop > VR * 0.30:
                        alerts.append(("FALL_DETECTED", "CRITICAL",
                                        f"Centroid Z dropped {z_drop:.1f} voxels in 3 frames"))
            except Exception:
                pass
        for a in alerts:
            self.alerts.append((time.time(),) + a)
        return alerts


def graph_diffusion(subcarrier_matrix, steps=3, alpha=0.5):
    """List 2.6 (Pass 17: pre-clamp + errstate to suppress corrcoef zero-std warning)."""
    X = np.atleast_2d(subcarrier_matrix)
    if X.shape[0] < 2:
        return X.ravel()
    X = np.clip(np.nan_to_num(X, nan=0.0, posinf=1e4, neginf=-1e4), -1e4, 1e4)
    with np.errstate(invalid='ignore', divide='ignore'):
        C = np.corrcoef(X.T)
    C = np.nan_to_num(C)
    np.fill_diagonal(C, 0)
    deg = np.abs(C).sum(axis=1) + 1e-9
    A_norm = C / deg[:, None]
    h = X.mean(axis=0)
    for _ in range(steps):
        h = (1 - alpha) * h + alpha * (A_norm @ h)
    return h


class ProfileStore:
    """List 2.7: persist & recognize returning individuals across runs."""
    def __init__(self, path="nepa_profiles.pkl"):
        self.path = path
        self.profiles = {}
        if os.path.exists(path):
            try:
                with open(path, "rb") as fh:
                    self.profiles = pickle.load(fh)
                log.info(f"[PROFILE] Loaded {len(self.profiles)} profiles from {path}")
            except Exception as e:
                log.warning(f"[PROFILE] Load failed: {e}")

    def signature(self, voxel_grid):
        """Extract 4-D biometric signature from voxel grid (mean, std, max, p90)."""
        g = np.asarray(voxel_grid)
        return np.array([g.mean(), g.std(), float(np.max(g)),
                         float(np.percentile(g, 90))], dtype=np.float32)

    def match_or_create(self, sig_vec, tol=0.08):
        """v112 STABILITY FIX: match by NEAREST stored profile (not first-within-tol), use an
        adaptive tolerance that scales with signature magnitude, and EMA-track the matched
        profile so it follows slow drift. The old logic (first match < fixed 0.08) never
        re-matched as the scene signature varied frame-to-frame, so it spawned a NEW id every
        frame (person_1→4→8 flicker = a visible miscorrelation). Now the same scene keeps ONE
        stable id."""
        sig_vec = np.asarray(sig_vec, dtype=np.float32)
        best_pid, best_d = None, float("inf")
        for pid, prof in self.profiles.items():
            d = float(np.linalg.norm(np.asarray(prof["sig"], dtype=np.float32) - sig_vec))
            if d < best_d:
                best_pid, best_d = pid, d
        thr = max(tol, 0.18 * (float(np.linalg.norm(sig_vec)) + 1e-6))
        if best_pid is not None and best_d < thr:
            p = self.profiles[best_pid]
            p["sig"] = 0.85 * np.asarray(p["sig"], dtype=np.float32) + 0.15 * sig_vec
            p["last_seen"] = time.time()
            return best_pid, False
        pid = f"person_{len(self.profiles) + 1}"
        self.profiles[pid] = {"sig": sig_vec, "first_seen": time.time(),
                              "last_seen": time.time(), "baseline_stress": 0.5}
        return pid, True

    def save(self):
        """Persist all recognized profiles to disk."""
        try:
            with open(self.path, "wb") as fh:
                pickle.dump(self.profiles, fh)
            log.info(f"[PROFILE] Saved {len(self.profiles)} profiles")
        except Exception as e:
            log.warning(f"[PROFILE] Save failed: {e}")


def cross_modal_consistency(profile):
    """List 2.8: compare CSI-vitals vs mind signals, return confidence multiplier 0-1."""
    stress = profile.get("bci_stress", 0)
    arousal = profile.get("arousal_level", 0)
    hr = profile.get("heart_rate_bpm", 72)
    body = profile.get("body_language", "neutral")
    inconsistency = 0.0
    # High arousal but calm body language → inconsistent
    if arousal > 0.7 and body == "relaxed":
        inconsistency += 0.4
    # High stress but low heart rate → inconsistent
    if stress > 0.7 and hr < 70:
        inconsistency += 0.4
    # Threat body language but low stress
    if body == "defensive" and stress < 0.3:
        inconsistency += 0.2
    return float(np.clip(1.0 - inconsistency, 0.0, 1.0))


def export_clinical_report(profile, voxel_stats, path=None, fmt="md"):
    """List 2.9: one-click clean Markdown/HTML clinical report."""
    ts = time.strftime("%Y-%m-%d %H:%M:%S")
