                    bar_c = (int(0 + conf * 100), int(100 + conf * 155), int(150 + conf * 105))
                    pygame.draw.rect(screen, (6, 16, 36), (rpx + 145, row_y + 2, 30, 8))
                    pygame.draw.rect(screen, bar_c, (rpx + 145, row_y + 2, int(conf * 30), 8))
