def _safe(fn, default='—'):
    """Call fn(), return default on any error."""
    try:
        return fn()
    except Exception:
        return default


def _fmt(val, decimals=4):
    """Format a numeric value safely."""
    try:
        return f"{float(val):.{decimals}f}"
    except (TypeError, ValueError):
        return '—'


def _safe_scalar(fn, default=0.0):
    """Call fn(), collapse result to a bounded scalar, return default on error."""
    try:
        v = fn()
        if v is None:
            return default
        arr = np.asarray(v, dtype=np.float64).flatten()
        if arr.size == 0:
            return default
        if arr.size == 1:
            return arr[0]
        return np.tanh(np.linalg.norm(arr) / (arr.size ** 0.5 + 1e-6))
    except Exception:
        return default


class _VoiceChatManager:
    """Voice I/O helper for AI Chat: microphone -> Whisper STT -> AI -> TTS."""

    def __init__(self, dashboard):
        self.dash = dashboard
        self._stop = threading.Event()
        self._ptt_stop = threading.Event()
        self._ptt_thread = None
        self._vad_thread = None
        self._lock = threading.Lock()
        self._state = 'idle'
        self._last_error = None

    def _set_state(self, state):
        with self._lock:
            self._state = state
        try:
            self.dash.win.after(0, lambda: self.dash._set_voice_status(state))
        except Exception:
            pass

    @property
    def state(self):
        with self._lock:
            return self._state

    def _is_ready(self):
        return (HAS_AUDIO and HAS_WHISPER and HAS_TTS and
                bool(CONFIG.get('voice_enabled', False)))

    def status_text(self):
        parts = []
        if not HAS_AUDIO:
            parts.append('microphone unavailable')
        if not HAS_WHISPER:
            parts.append('Whisper STT not installed')
        if not HAS_TTS:
            parts.append('TTS unavailable')
        if not CONFIG.get('voice_enabled', False):
            parts.append('voice disabled in CONFIG')
        return ', '.join(parts) if parts else 'voice ready'

    # ---------------------------------------------------------------
    # Push-to-talk
    # ---------------------------------------------------------------
    def start_ptt(self):
        if self._ptt_thread is not None and self._ptt_thread.is_alive():
            return
        if not self._is_ready():
            self.dash._append_chat(f"[system] {self.status_text()}.\n", 'system')
            return
        self._ptt_stop.clear()
        self._ptt_thread = threading.Thread(target=self._ptt_record, daemon=True)
        self._ptt_thread.start()

    def stop_ptt(self):
        self._ptt_stop.set()

    def _ptt_record(self):
        import sounddevice as sd
        sample_rate = 16000
        block_size = 1024
        buffer = []
        def callback(indata, frames, time_info, status):
            buffer.append(indata[:, 0].astype(np.float32).copy())
        self._set_state('listening')
        try:
            with sd.InputStream(samplerate=sample_rate, blocksize=block_size,
                                channels=1, dtype=np.float32, callback=callback):
                while not self._ptt_stop.is_set():
                    time.sleep(0.05)
        except Exception as e:
            self._set_state('error')
            self.dash.win.after(0, lambda: self.dash._append_chat(
                f"[system] Microphone error: {e}\n", 'system'))
            return
        if not buffer:
            self._set_state('idle')
            return
        audio = np.concatenate(buffer)
        self._set_state('transcribing')
        text = self._transcribe(audio, sample_rate)
        self._set_state('idle')
        if text:
            self.dash.win.after(0, lambda: self.dash._send_voice_text(text))

    # ---------------------------------------------------------------
    # Continuous VAD "call" mode
    # ---------------------------------------------------------------
    def start_call(self):
        if self._vad_thread is not None and self._vad_thread.is_alive():
            return
        if not self._is_ready():
            self.dash._append_chat(f"[system] {self.status_text()}.\n", 'system')
            return
        self._stop.clear()
        self._vad_thread = threading.Thread(target=self._vad_loop, daemon=True)
        self._vad_thread.start()

    def stop_call(self):
        self._stop.set()
        self._vad_thread = None
        self._set_state('idle')

    def _vad_loop(self):
        import sounddevice as sd
        sample_rate = 16000
        block_size = 1024
        q = deque()
        def callback(indata, frames, time_info, status):
            q.append(indata[:, 0].astype(np.float32).copy())
        try:
            stream = sd.InputStream(samplerate=sample_rate, blocksize=block_size,
                                    channels=1, dtype=np.float32, callback=callback)
        except Exception as e:
            self._set_state('error')
            self.dash.win.after(0, lambda: self.dash._append_chat(
                f"[system] Microphone error: {e}\n", 'system'))
            return
        stream.start()
        buffer = []
        state = 'idle'
        silence_sec = 0.0
        energy_threshold = 0.015
        silence_required = 1.2
        try:
            while not self._stop.is_set():
                while q and not self._stop.is_set():
                    frame = q.popleft()
                    rms = float(np.sqrt(np.mean(frame ** 2)))
                    if state == 'idle':
                        if rms > energy_threshold:
                            state = 'listening'
                            buffer = [frame]
                            self._set_state('listening')
                            silence_sec = 0.0
                    elif state == 'listening':
                        buffer.append(frame)
                        if rms > energy_threshold:
                            silence_sec = 0.0
                        else:
                            silence_sec += len(frame) / sample_rate
                            if silence_sec >= silence_required:
                                audio = np.concatenate(buffer)
                                state = 'processing'
                                self._set_state('processing')
                                threading.Thread(target=self._process_vad_audio,
                                                 args=(audio, sample_rate), daemon=True).start()
                                buffer = []
                                silence_sec = 0.0
                                state = 'idle'
                time.sleep(0.05)
        finally:
            stream.stop()
            stream.close()
        self._set_state('idle')

    def _process_vad_audio(self, audio, sample_rate):
        text = self._transcribe(audio, sample_rate)
        if text:
            self.dash.win.after(0, lambda: self.dash._send_voice_text(text))

    # ---------------------------------------------------------------
    # STT
    # ---------------------------------------------------------------
    def _transcribe(self, audio, sample_rate):
        model = _load_whisper_model()
        if model is None:
            return ""
        try:
            # Whisper expects float32, 16kHz, [-1, 1]
            wav = audio.astype(np.float32)
            result = model.transcribe(wav, fp16=False)
            return result.get("text", "").strip()
        except Exception as e:
            self._last_error = str(e)
            self.dash.win.after(0, lambda: self.dash._append_chat(
                f"[system] STT error: {e}\n", 'system'))
            return ""


class _SoundSpectrumAnalyzer:
    """Real-time audio spectrum analyzer backed by cs_reference_bridge.

    Wraps the NEPA-style SensoryAwarenessOrganizer (FFT + per-band powers +
    VAD + spectrogram history + reality-recognition score).  The public
    interface is preserved so existing callers in ConsciousnessSimulator keep
    working, but the internal signal pipeline now uses the richer bridge.
    """
    _FS = 16000
    _NFFT = 2048
    _HOP = 1024
    _BANDS = {
        'sub': (20, 80), 'bass': (80, 250), 'mid': (250, 2000),
        'hi-mid': (2000, 6000), 'hi': (6000, 8000)
    }

    def __init__(self):
        self._organizer = None
        self._lock = threading.Lock()
        self.ok = False
        self._ensure_organizer()

    def _ensure_organizer(self):
        if self._organizer is None:
            toolkit = _get_cs_ref_toolkit()
            if toolkit:
                try:
                    self._organizer = toolkit.sensory
                except Exception:
                    self._organizer = None

    def start(self):
        self._ensure_organizer()
        if self._organizer is None:
            self.ok = False
            return
        self.ok = self._organizer.start()

    def stop(self):
        if self._organizer is not None:
            self._organizer.stop()
        self.ok = False

    def get_spectrum(self):
        if self._organizer is None:
            return np.zeros(self._NFFT // 2 + 1, dtype=np.float32)
        return self._organizer.get_spectrum()

    def get_bands(self):
        if self._organizer is None:
            return {k: -90.0 for k in self._BANDS}
        # Map the richer organizer band set onto this class's 5-band contract
        rich = self._organizer.get_bands()
        mapped = {}
        mapped['sub'] = rich.get('sub', -90.0)
        mapped['bass'] = rich.get('bass', -90.0)
        mapped['mid'] = max(rich.get('low_mid', -90.0), rich.get('mid', -90.0))
        mapped['hi-mid'] = rich.get('hi_mid', -90.0)
        mapped['hi'] = rich.get('hi', -90.0)
        return mapped

    def is_voice_active(self):
        if self._organizer is None:
            return False
        return self._organizer.is_voice_active()

    def get_features(self):
        """Return a fixed-length feature vector for the cognition pipeline."""
        bands = self.get_bands()
        return np.array([bands[k] for k in self._BANDS] +
                        [float(self.is_voice_active())], dtype=np.float32)

    def get_reality_state(self):
        """Extended sensory-awareness / reality-recognition summary."""
        if self._organizer is None:
            return {"ok": False, "error": "bridge unavailable"}
        return self._organizer.get_reality_state()


def _try_engineering_query(text):
    """Route plain-English engineering requests through the AIEG toolkit.
    Returns rendered text if AIEG successfully handles the query; otherwise
    returns None so the normal language-model path can answer.

    The reference bridge exposes the full EEToolkit, Router and all 69
    RoadmapEngine capabilities, so CS.py can leverage AIEG's real engineering
    engine whenever the request is about circuits, components, RF or design.
    """
    toolkit = _get_cs_ref_toolkit()
    if toolkit and toolkit.engineering.available:
        try:
            answer = toolkit.engineering.query(text)
            if answer:
                return answer
            # If the router did not match, try the high-level design-for-need fallback
            answer = toolkit.engineering.design_for_need(text)
            if answer and not answer.startswith("[AIEG] No specific"):
                return answer
        except Exception:
            pass
    # Legacy fallback using direct AIEG import
    if not _HAS_AIEG or _AIEG is None:
        return None
    try:
        tk = _AIEG.EEToolkit()
        router = _AIEG.Router(tk)
        result = router.handle(text)
        if hasattr(result, 'render'):
            return result.render()
        return str(result)
    except Exception:
        return None


