                    if cycle % 100 == 0 and cycle > 0:
                        try:
                            _tk = _get_cs_ref_toolkit()
                            if _tk and hasattr(_tk, 'knowledge_base'):
                                _thought = self._last_thought_info or {}
                                _text = _thought.get('text', '')
                                if _text:
                                    _tk.knowledge_base.add(f'cycle_{cycle}', _text)
                                self._last_sensory_awareness['tfidf_status'] = _tk.knowledge_base.status()
                        except Exception:
                            pass
                    # --- NEPA correlation organizer: every 200 cycles, compute
