                    if cycle % 200 == 0 and cycle > 0:
                        try:
                            _tk = _get_cs_ref_toolkit()
                            if _tk and hasattr(_tk, 'reliability'):
                                _re = _tk.reliability
                                _cycle_t = float(cycle)
                                _eta = max(1.0, _cycle_t * 2.0)
                                _beta = 1.5
                                _rel = _re.weibull_reliability(_cycle_t, _eta, _beta)
                                _mtbf = _re.mtbf_hours(1.0 / max(_cycle_t, 1.0))
                                self._last_sensory_awareness['reliability'] = {
                                    'weibull_R': round(_rel, 6),
                                    'mtbf_hours': round(_mtbf, 2),
                                }
                        except Exception:
                            pass
                    # --- AIEG Monte Carlo: every 200 cycles, sample the AI's
                    # reality score under perturbation of its sensory weights
