def _wave34_corpus_growth_gate(sim, barrier):
    """#14: gate corpus ingestion through a filter."""
    try:
        filter = Wave33CorpusFilter(sim) if hasattr(sim, '_wave33_corpus_filter') else Wave34Resolver._sim  # not used
        # Use the existing CorpusGrowthEngine files and filter them
        cge = Wave33CorpusFilter(sim)
        root = os.path.dirname(os.path.abspath(__file__))
        cands = [os.path.join(root, f) for f in os.listdir(root)
                 if f.endswith(('.md','.txt','.py','.json')) and os.path.getsize(os.path.join(root, f)) < 8_000_000]
        filtered = cge.filter_files(cands)
        sim._wave34_corpus_gate_files = filtered[:8]
        sim._wave34_corpus_gate_active = True
        return True
    except Exception:
        return False


def _wave34_lora(sim, barrier):
    """#15: attach low-rank adapter plans to selected modules."""
    try:
        lora = Wave34LoRAAdapter(sim)
        ok = lora.add(target='lm_head', rank=4)
        sim._wave34_lora = lora
        sim._wave34_lora_added = ok
        return True
    except Exception:
        return False


def _wave34_surrogate(sim, barrier):
    """#16: install the surrogate and predict this tick's resolver success."""
    try:
        s = Wave34Surrogate(sim)
        sim._wave34_surrogate = s
        # predict against a few known resolver names
        arms = ['TuneLRResolver', 'QuantizeInt8Resolver', 'CorpusGrowthEngine']
        sim._wave34_surrogate_predictions = {
            a: s.predict(barrier, a) for a in arms
        }
        return True
    except Exception:
        return False


def _wave34_torch_compile(sim, barrier):
    """#17: attempt torch.compile and keep a compiled container if it works."""
    try:
        if not hasattr(torch, 'compile'):
            sim._wave34_torch_compile_available = False
            return True
        compiled = torch.compile(sim, mode='default')
        toks = sim.simple_tokenizer("compile probe")
        with torch.no_grad():
            _ = compiled(toks, task_category='compile_probe')
        sim._wave34_compiled_container = (compiled,)
        sim._wave34_torch_compile_ok = True
        return True
    except Exception:
        sim._wave34_torch_compile_ok = False
        return False


def _wave34_distill(sim, barrier):
    """#18: distillation flag + one sample from the symbolic engine."""
    try:
        laws = list(PHYSICS_LAWS.values())
        if laws:
            sample = f"Q: state the law. A: {laws[0].get('desc','')}"
            toks = sim.simple_tokenizer(sample)
            sim.process_input(toks, task_category='distill', raw_text=sample)
            sim._wave34_distill_samples = 1
        sim._wave34_distill_active = True
        return True
    except Exception:
        return False


def _wave34_multi_gpu(sim, barrier):
    """#19: enable DataParallel if multiple GPUs are present."""
    try:
        if torch.cuda.device_count() > 1:
            dp = nn.DataParallel(sim)
            sim._wave34_multi_gpu_container = (dp,)
            sim._wave34_multi_gpu_enabled = True
        else:
            sim._wave34_multi_gpu_enabled = False
        return True
    except Exception:
        return False


def _wave34_dashboard(sim, barrier):
    """#20: post an evolution event to an in-memory dashboard log."""
    try:
        d = Wave34Dashboard(sim)
        d.post({
            'barrier': barrier.get('type'),
            'time': time.time(),
            'resolvers_available': 295,
        })
        sim._wave34_dashboard = d
        return True
    except Exception:
        return False


