_wave34_prev_build_barrier_resolvers = _build_barrier_resolvers


def _wave34_build_barrier_resolvers(sim):
    r = _wave34_prev_build_barrier_resolvers(sim)
    wave34_resolvers = [
        Wave34Resolver(sim, kind, risk=_WAVE34_RISKS.get(kind, 'low'))
        for kind in _WAVE34_ACTIONS.keys()
    ]
    for k in r:
        r[k].extend(wave34_resolvers)
    # target specific barriers
    r['loss_plateau'].insert(0, Wave34Resolver(sim, 'growth_surgery', 'high'))
    r['oom_risk'].insert(0, Wave34Resolver(sim, 'quantize_switch', 'medium'))
    r['latency_breach'].insert(0, Wave34Resolver(sim, 'torch_compile', 'high'))
    r['corpus_starved'].insert(0, Wave34Resolver(sim, 'corpus_growth_gate', 'low'))
    r['context_exhausted'].insert(0, Wave34Resolver(sim, 'growth_surgery', 'high'))
    r['subtree_silent_failure'].insert(0, Wave34Resolver(sim, 'verifier_registry', 'low'))
    return r


_build_barrier_resolvers = _wave34_build_barrier_resolvers


