_wave36_prev_build = _build_barrier_resolvers


def _wave36_build_barrier_resolvers(sim):
    r = _wave36_prev_build(sim)
    # Neuro-symbolic training is the highest-leverage for corpus_starved
    r['corpus_starved'].insert(0, Wave36NeuroSymbolicTrainingLoop(sim))
    # Thought-to-training for corpus_starved and loss_plateau
    r['corpus_starved'].insert(1, Wave36ThoughtToTrainingBridge(sim))
    r['loss_plateau'].insert(0, Wave36ThoughtToTrainingBridge(sim))
    # Self-mod reinforcement for loss_plateau and benchmark_regression
    r['loss_plateau'].insert(1, Wave36SelfModReinforcement(sim))
    r['benchmark_regression'].insert(0, Wave36SelfModReinforcement(sim))
    # Verified synergy for loss_plateau and corpus_starved
    r['loss_plateau'].insert(0, Wave36VerifiedSynergyResolver(sim))
    r['corpus_starved'].insert(0, Wave36VerifiedSynergyResolver(sim))
    # Add all Wave 36 resolvers to every barrier type as low-risk options
    w36 = [
        Wave36NeuroSymbolicTrainingLoop(sim),
        Wave36ThoughtToTrainingBridge(sim),
        Wave36SelfModReinforcement(sim),
    ]
    for k in r:
        r[k].extend(w36)
    return r


_build_barrier_resolvers = _wave36_build_barrier_resolvers


