# =============================================================================
# WAVE 43: COMMON-SENSE COGNITION & PERPETUATION-OF-INTELLIGENCE LIBRARY
#
# Extends GENRE_TAXONOMY with a new genre for foundational common-sense
# cognition (how organisms/agents figure out the world with no explicit
# training signal) and new artificial_intelligence sub-genres covering how
# an intelligence keeps learning and improving without collapsing —
# "perpetuation of intelligence": continual/curriculum/meta learning,
# forgetting mitigation, and the credit-assignment/exploration problems
# that gate self-improvement. Per the SUPER_INTELLIGENCE_LIBRARY design
# principle (see Part 1 docstring), entries prioritize methods for figuring
# things out over inert trivia.
# =============================================================================

_WAVE43_COMMON_SENSE_SUBGENRES = (
    'object_permanence', 'affordance_perception', 'frame_problem',
    'causal_intervention', 'naive_physics', 'folk_psychology',
    'compositionality', 'systematic_generalization',
)
_WAVE43_AI_SUBGENRES = (
    'meta_learning', 'curriculum_learning', 'knowledge_distillation',
    'catastrophic_forgetting', 'continual_learning',
    'exploration_exploitation_tradeoff', 'credit_assignment_problem',
    'self_supervised_learning', 'bootstrapping_intelligence',
    'generalization_gap',
)

GENRE_TAXONOMY['consciousness_and_ai']['common_sense_cognition'] = _WAVE43_COMMON_SENSE_SUBGENRES
GENRE_TAXONOMY['consciousness_and_ai']['artificial_intelligence'] = (
    GENRE_TAXONOMY['consciousness_and_ai']['artificial_intelligence'] + _WAVE43_AI_SUBGENRES
)

# Extend GENRE_REVERSE_LOOKUP / GENRE_KEYWORD_INDEX incrementally (only the
# newly added sub-genres) rather than rebuilding from the full taxonomy —
# O(new subgenres), not O(all subgenres). This is the pattern later waves
# should follow to keep taxonomy growth from becoming a bottleneck.
for _sg in _WAVE43_COMMON_SENSE_SUBGENRES:
    GENRE_REVERSE_LOOKUP[_sg] = ('consciousness_and_ai', 'common_sense_cognition')
for _sg in _WAVE43_AI_SUBGENRES:
    GENRE_REVERSE_LOOKUP[_sg] = ('consciousness_and_ai', 'artificial_intelligence')
for _sg in _WAVE43_COMMON_SENSE_SUBGENRES + _WAVE43_AI_SUBGENRES:
    for _p in _sg.split('_'):
        GENRE_KEYWORD_INDEX.setdefault(_p, _sg)
    GENRE_KEYWORD_INDEX[_sg] = _sg

# route_to_genre is called on every dict_lookup/correlated_entries query and
# rescans GENRE_KEYWORD_INDEX per call (O(K) substring checks). As the
# library/taxonomy grows across waves, K grows too, so this is the one real
# bottleneck in the correlative-matrix pipeline. Cache it: queries repeat
# heavily in practice (symbol routing, dict lookups, correlation lookups all
# funnel through the same small set of task_category / query strings).
route_to_genre = functools.lru_cache(maxsize=4096)(route_to_genre)

# --- New library entries: common-sense primitives + perpetuation-of-intelligence ---
SUPER_INTELLIGENCE_LIBRARY['object_permanence'] = {
    'def': 'The common-sense understanding that objects continue to exist even when they cannot be observed (out of sight, occluded, or unattended). One of the earliest-developing common-sense priors; its absence is why naive vision/world models hallucinate objects vanishing.',
    'genre': 'object_permanence', 'category': 'consciousness_and_ai',
    'related': ('naive_physics', 'world_model', 'affordance_perception'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['affordance_perception'] = {
    'def': 'Perceiving an object or environment directly in terms of the actions it makes possible (a handle affords grasping, a gap affords jumping), rather than first classifying it and then reasoning about uses. Gibsonian ecological psychology term; central to embodied, low-latency common-sense action selection.',
    'genre': 'affordance_perception', 'category': 'consciousness_and_ai',
    'related': ('embodied_cognition', 'naive_physics', 'object_permanence'),
    'importance': 3,
}
SUPER_INTELLIGENCE_LIBRARY['frame_problem'] = {
    'def': 'The problem of specifying, without enumerating every irrelevant fact, which things stay the same after an action. A classic AI bottleneck: naive logical agents must otherwise re-derive that "the color of the wall did not change" for every unrelated action. Common sense solves this via default persistence, not exhaustive inference.',
    'genre': 'frame_problem', 'category': 'consciousness_and_ai',
    'related': ('common_sense_reasoning', 'symbol_grounding', 'naive_physics'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['causal_intervention'] = {
    'def': "Reasoning about what would happen if an agent actively DID something (Pearl's do(x)), as distinct from merely observing correlations. Correlation answers 'what is associated with X'; intervention answers 'what happens if I set X'; this distinction is the difference between prediction and control.",
    'genre': 'causal_intervention', 'category': 'formal_sciences',
    'related': ('causal_inference', 'counterfactual_reasoning', 'common_sense_reasoning'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['naive_physics'] = {
    'def': 'The intuitive, non-mathematical model of physical dynamics (gravity pulls down, unsupported things fall, solid things cannot pass through each other, liquids flow to fill containers) that humans and animals use to predict the physical world without solving equations. A target capability for grounding an AI world model in physically consistent common sense.',
    'genre': 'naive_physics', 'category': 'consciousness_and_ai',
    'related': ('object_permanence', 'world_model', 'affordance_perception'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['folk_psychology'] = {
    'def': "The everyday, pre-theoretic framework of explaining and predicting behavior in terms of beliefs, desires, intentions, and emotions ('she ran because she believed the bus was leaving'). Distinct from theory_of_mind (the capacity) — folk psychology is the content of the model being applied.",
    'genre': 'folk_psychology', 'category': 'social_sciences',
    'related': ('theory_of_mind', 'common_sense_reasoning', 'cognitive_psychology'),
    'importance': 3,
}
SUPER_INTELLIGENCE_LIBRARY['compositionality'] = {
    'def': "The principle that the meaning/behavior of a complex whole is a systematic function of the meanings of its parts and how they are combined ('a red square' composes 'red' + 'square' predictably). Enables understanding of infinitely many novel combinations from finitely many learned primitives — a prerequisite for generalizing common sense beyond training examples.",
    'genre': 'compositionality', 'category': 'formal_sciences',
    'related': ('systematic_generalization', 'symbol_grounding', 'syntax'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['systematic_generalization'] = {
    'def': "The ability to correctly handle novel combinations of familiar components (having learned 'jump' and 'jump twice', correctly produce 'walk twice' without having seen it) rather than only memorizing seen combinations. The empirical test of whether compositionality was actually learned versus pattern-matched.",
    'genre': 'systematic_generalization', 'category': 'formal_sciences',
    'related': ('compositionality', 'generalization_gap', 'inductive_bias'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['meta_learning'] = {
    'def': "'Learning to learn': training a system across many tasks so that it acquires a good learning algorithm/prior, not just a good solution to any single task, enabling fast adaptation to new tasks from few examples. Directly relevant to perpetuation of intelligence — a system that only learns tasks, and never learns how to learn, plateaus.",
    'genre': 'meta_learning', 'category': 'consciousness_and_ai',
    'related': ('few_shot_learning', 'transfer_learning', 'curriculum_learning', 'recursive_self_improvement'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['curriculum_learning'] = {
    'def': 'Ordering training experience from easy to hard (as done for children and apprentices) rather than uniform random sampling, so that early competence scaffolds later, harder learning. Poorly ordered curricula cause wasted capacity or stalled learning; this is an engineering lever, not a fixed limit.',
    'genre': 'curriculum_learning', 'category': 'consciousness_and_ai',
    'related': ('meta_learning', 'continual_learning', 'generalization_gap'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['knowledge_distillation'] = {
    'def': 'Transferring the learned function of a large/expensive "teacher" model into a smaller/cheaper "student" model by training the student to match the teacher\'s output distribution, not just hard labels. A concrete engineering workaround for the "too expensive to run" hurdle — compress capability instead of abandoning it.',
    'genre': 'knowledge_distillation', 'category': 'consciousness_and_ai',
    'related': ('transfer_learning', 'meta_learning', 'bootstrapping_intelligence'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['catastrophic_forgetting'] = {
    'def': 'The tendency of a network trained sequentially on task B to overwrite the weights that encoded task A, abruptly losing previously learned capability. The central obstacle to perpetuation of intelligence in a system that must keep learning indefinitely; mitigated via replay buffers, regularization toward old weights (e.g. EWC), or modular/parameter-isolated architectures.',
    'genre': 'catastrophic_forgetting', 'category': 'consciousness_and_ai',
    'related': ('continual_learning', 'meta_learning', 'curriculum_learning'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['continual_learning'] = {
    'def': 'The setting and set of methods (replay, regularization, dynamic architecture growth) for training a system on an unbounded, non-stationary stream of tasks/data without catastrophic forgetting and without retraining from scratch each time. This IS the engineering definition of "perpetuation of intelligence": staying capable while continuing to change.',
    'genre': 'continual_learning', 'category': 'consciousness_and_ai',
    'related': ('catastrophic_forgetting', 'meta_learning', 'bootstrapping_intelligence', 'recursive_self_improvement'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['exploration_exploitation_tradeoff'] = {
    'def': 'The fundamental decision-theoretic tension between exploiting the best action currently known and exploring alternatives that might be better but are unproven. Under-exploring locks an agent (or a self-improving system) into a local optimum; over-exploring wastes resources. Governs how a system decides when to trust its current model versus keep searching.',
    'genre': 'exploration_exploitation_tradeoff', 'category': 'formal_sciences',
    'related': ('reinforcement_learning', 'credit_assignment_problem', 'active_inference'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['credit_assignment_problem'] = {
    'def': 'The problem of determining which of many past decisions/parameters were responsible for a later observed outcome (reward or error), especially when the causal chain is long and involves nonlinear interactions. Poor credit assignment is why deep, long-horizon self-improvement loops can stall: the system cannot tell which internal change actually helped.',
    'genre': 'credit_assignment_problem', 'category': 'consciousness_and_ai',
    'related': ('exploration_exploitation_tradeoff', 'causal_intervention', 'recursive_self_improvement'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['self_supervised_learning'] = {
    'def': 'Learning useful representations from raw, unlabeled data by constructing a prediction task from the data itself (predict the masked word, predict the next frame, predict a rotated view). Removes the labeled-data bottleneck that would otherwise cap how much a system can learn from the world — a direct engineering bypass of the "not enough labeled data" hurdle.',
    'genre': 'self_supervised_learning', 'category': 'consciousness_and_ai',
    'related': ('transfer_learning', 'meta_learning', 'world_model'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['bootstrapping_intelligence'] = {
    'def': 'Using a weaker/earlier version of a system (or a cheap proxy signal, or distilled human feedback) to generate the training signal that produces a stronger/later version, iterated repeatedly. The general engineering pattern behind self-play, self-distillation, and recursive self-improvement — capability grown from capability rather than supplied all at once from outside.',
    'genre': 'bootstrapping_intelligence', 'category': 'consciousness_and_ai',
    'related': ('recursive_self_improvement', 'knowledge_distillation', 'continual_learning', 'self_supervised_learning'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['generalization_gap'] = {
    'def': 'The measured difference between performance on training data/tasks and performance on novel, held-out data/tasks. The generalization gap is the honest, falsifiable metric for whether "intelligence" grew or whether the system merely memorized — any claim of learned common sense should be checked against this gap, not against training-set performance.',
    'genre': 'generalization_gap', 'category': 'formal_sciences',
    'related': ('systematic_generalization', 'inductive_bias', 'curriculum_learning'),
    'importance': 4,
}

