SUPER_INTELLIGENCE_LIBRARY['first_principles_thinking'] = {
    'def': 'Reasoning from the most fundamental truths you can identify, then building up from there rather than reasoning by analogy to existing solutions. Steps: (1) identify and question every assumption, (2) strip down to what is provably true (physics, math, logic), (3) rebuild from those fundamentals. This is how you figure out things that have never been figured out before. Elon Musk used it to reduce rocket cost to raw materials. The opposite of reasoning by analogy, which only gets you incremental improvements on what already exists.',
    'genre': 'first_principles_thinking', 'category': 'meta_reasoning',
    'related': ('decomposition', 'abstraction_laddering', 'root_cause_analysis', 'hypothesis_testing'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['analogy_and_metaphor'] = {
    'def': 'Figuring out something new by mapping its structure onto something already understood. The core cognitive operation behind insight: "an atom is like a solar system," "a cell is like a factory." Analogical transfer works when the source and target share relational structure (not surface features). Powerful but dangerous: bad analogies mislead. Use analogy to generate hypotheses, then verify with first principles. Structure-mapping theory (Gentner) formalizes this.',
    'genre': 'analogy_and_metaphor', 'category': 'meta_reasoning',
    'related': ('lateral_thinking', 'divergent_convergent_thinking', 'abductive_inference', 'socratic_method'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['decomposition'] = {
    'def': 'Breaking a complex problem into smaller, independently solvable sub-problems. The most reliable problem-solving strategy: if you cannot solve X, decompose X into A+B+C and solve each. If a sub-problem is still too hard, decompose again recursively. The basis of divide-and-conquer algorithms, modular design, and scientific reductionism. Works when sub-problems are truly independent; fails when they are tightly coupled (then need holistic approaches).',
    'genre': 'decomposition', 'category': 'meta_reasoning',
    'related': ('first_principles_thinking', 'abstraction_laddering', 'root_cause_analysis', 'maxq_decomposition'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['abstraction_laddering'] = {
    'def': 'Moving up and down levels of abstraction to find the right level to solve a problem. Up (more abstract): "this is a search problem" — reveals general solutions. Down (more concrete): "this is searching a sorted list" — reveals specific optimizations. The key skill is knowing when to zoom out (see the pattern) and when to zoom in (see the details). Too high: vague, impractical. Too low: lost in details, no pattern. The right level is where the problem becomes tractable.',
    'genre': 'abstraction_laddering', 'category': 'meta_reasoning',
    'related': ('first_principles_thinking', 'decomposition', 'abstraction', 'modularity'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['hypothesis_testing'] = {
    'def': 'The core method of science: (1) observe a phenomenon, (2) form a hypothesis (a testable explanation), (3) design an experiment that could disprove it, (4) run the experiment, (5) revise based on results. The key insight: you should try to disprove your hypothesis, not confirm it. Confirmation bias (seeking evidence that supports your belief) is the #1 enemy of good reasoning. A hypothesis that survives many serious attempts at disproof is probably true.',
    'genre': 'hypothesis_testing', 'category': 'meta_reasoning',
    'related': ('falsificationism', 'bayesian_updating', 'occam_razor', 'scientific_method'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['bayesian_updating__alt2'] = {
    'def': 'Updating your beliefs in proportion to new evidence. Prior belief + new evidence = posterior belief. Bayes theorem: P(H|E) = P(E|H)*P(H)/P(E). The mathematically optimal way to update beliefs under uncertainty. Key principles: (1) start with a prior (your initial belief), (2) update with likelihood (how probable is the evidence under each hypothesis), (3) the posterior becomes the new prior. Most people under-update (stick with prior) or over-update (one dramatic event). Practice: calibrate your confidence.',
    'genre': 'bayesian_updating', 'category': 'meta_reasoning',
    'related': ('hypothesis_testing', 'predictive_coding_hierarchy', 'active_inference_framework', 'free_energy_principle'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['occam_razor'] = {
    'def': 'Among hypotheses that explain the evidence equally well, prefer the one with fewer assumptions. Not because it is necessarily true, but because it is more testable, more falsifiable, and less likely to contain hidden errors. The simplest explanation is more likely to be correct because each additional assumption is another opportunity to be wrong. Formalized by Solomonoff induction: simpler hypotheses get higher prior probability. Counter: sometimes the complex explanation IS correct (evolution, quantum mechanics).',
    'genre': 'occam_razor', 'category': 'meta_reasoning',
    'related': ('falsificationism', 'hypothesis_testing', 'bayesian_updating', 'solomonoff_induction'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['falsificationism'] = {
    'def': 'Karl Popper\'s principle: a theory is scientific only if it can be proven false by some possible observation. Theories that can explain anything (astrology, unfalsifiable conspiracy theories) explain nothing. Strength comes from risky predictions: if a theory predicts something unlikely and it happens, that is strong evidence. Falsificationism is not how science actually works (Kuhn: paradigms shift, Lakatos: research programmes) but it is the ideal to strive for.',
    'genre': 'falsificationism', 'category': 'meta_reasoning',
    'related': ('hypothesis_testing', 'occam_razor', 'scientific_method', 'popper'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['root_cause_analysis'] = {
    'def': 'A systematic method for finding the fundamental cause of a problem, not just its symptoms. Techniques: 5 Whys (ask "why" repeatedly until you reach the root), fishbone diagram (categorize possible causes), fault tree analysis (work backward from failure). The principle: treating symptoms makes the problem recur; treating the root cause eliminates it permanently. In engineering: every bug, every outage, every failure has a root cause — find it or it will find you again.',
    'genre': 'root_cause_analysis', 'category': 'meta_reasoning',
    'related': ('decomposition', 'first_principles_thinking', 'fault_tolerance', 'reliability_engineering'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['lateral_thinking'] = {
    'def': 'Edward de Bono\'s term for solving problems through indirect, creative approaches rather than step-by-step logic. Techniques: random entry (inject a random word and force connection), provocation (make an absurd statement and work from it), challenge (question assumptions that seem obvious). Lateral thinking is to vertical (logical) thinking what exploration is to exploitation: you need both. Use lateral thinking when stuck, vertical thinking when you have a promising direction.',
    'genre': 'lateral_thinking', 'category': 'meta_reasoning',
    'related': ('divergent_convergent_thinking', 'analogy_and_metaphor', 'creativity', 'socratic_method'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['divergent_convergent_thinking'] = {
    'def': 'Two complementary modes of thought: divergent (generate many possible solutions, no judgment) then convergent (evaluate and select the best). The double-diamond design process: discover (diverge), define (converge), develop (diverge), deliver (converge). Most people are strong in one mode and weak in the other. The key skill is knowing which mode you are in and not mixing them: do not judge while generating, do not generate while selecting.',
    'genre': 'divergent_convergent_thinking', 'category': 'meta_reasoning',
    'related': ('lateral_thinking', 'exploration_exploitation_tradeoff', 'brainstorming', 'design_thinking'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['socratic_method'] = {
    'def': 'A dialogue-based method of inquiry: ask a series of probing questions that expose contradictions in the interlocutor\'s beliefs, leading them to refine their understanding. Not about proving the other person wrong but about jointly arriving at clearer thinking through disciplined questioning. The method assumes that the truth is already partially present in the mind and needs to be drawn out (maieutic). Used in law schools, therapy, and AI self-reflection.',
    'genre': 'socratic_method', 'category': 'meta_reasoning',
    'related': ('maieutic_reasoning', 'reflective_equilibrium', 'lateral_thinking', 'introspection'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['maieutic_reasoning'] = {
    'def': 'From the Greek for "midwifery": the Socratic practice of helping someone give birth to ideas they already implicitly hold but have not articulated. The questioner does not provide answers but asks questions that help the thinker discover the answer themselves. In AI: a system that can ask itself the right questions can discover solutions it was not explicitly taught. The basis of self-reflection and metacognitive monitoring.',
    'genre': 'maieutic_reasoning', 'category': 'meta_reasoning',
    'related': ('socratic_method', 'metacognitive_monitoring', 'introspection', 'self_model'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['reflective_equilibrium'] = {
    'def': 'A method of ethical and epistemic reasoning (Rawls): start with considered judgments, identify principles that explain them, then adjust both judgments and principles until they cohere. It is iterative: principles may cause you to revise judgments, and judgments may cause you to revise principles. The goal is a state where your beliefs at all levels are mutually consistent and supportive. The method behind moral progress and scientific paradigm refinement.',
    'genre': 'reflective_equilibrium', 'category': 'meta_reasoning',
    'related': ('socratic_method', 'coherence_theory', 'epistemology', 'ethics'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['abductive_inference'] = {
    'def': 'Inference to the best explanation: given observations, find the hypothesis that best explains them. Distinct from deduction (guaranteed conclusion from premises) and induction (generalization from instances). Abduction is what detectives, doctors, and scientists do: "what could explain all these clues?" The best explanation is the one that is simplest, most comprehensive, and most predictive. Peirce\'s key insight: abduction generates new hypotheses, deduction derives predictions, induction tests them.',
    'genre': 'abductive_inference', 'category': 'meta_reasoning',
    'related': ('retroductive_reasoning', 'hypothesis_testing', 'occam_razor', 'peirce'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['retroductive_reasoning'] = {
    'def': 'Another name for abductive inference: reasoning backward from effects to causes. "What must be true for this to have happened?" The method of paleontology (what dinosaur produced this fossil?), cosmology (what early universe produced this CMB?), and debugging (what code path produced this crash?). Retroduction generates hypotheses that deduction and induction then test. The creative step in science.',
    'genre': 'retroductive_reasoning', 'category': 'meta_reasoning',
    'related': ('abductive_inference', 'root_cause_analysis', 'hypothesis_testing', 'peirce'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['heuristic_search_strategies'] = {
    'def': 'Methods for searching large solution spaces efficiently: hill climbing (move to the best neighbor), simulated annealing (occasionally accept worse moves to escape local optima), genetic algorithms (maintain a population of solutions, combine and mutate), beam search (keep top-k partial solutions). The art is choosing the right heuristic for the problem structure. No universal best heuristic (no free lunch theorem). Combine multiple heuristics for robustness.',
    'genre': 'heuristic_search_strategies', 'category': 'meta_reasoning',
    'related': ('search', 'heuristic_search', 'satisficing', 'exploration_exploitation_tradeoff'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['satisficing__alt2'] = {
    'def': 'Herbert Simon\'s term: rather than optimizing (finding the best possible solution, which may be computationally intractable), choose the first solution that is "good enough." Bounded rationality: humans and AI cannot exhaustively search, so they satisfice. The threshold for "good enough" should be calibrated to the stakes: high-stakes decisions warrant more search. Satisficing is not laziness — it is the rational strategy when search is costly and time is limited.',
    'genre': 'satisficing', 'category': 'meta_reasoning',
    'related': ('bounded_rationality', 'heuristic_search_strategies', 'recognition_primed_decision', 'fast_and_frugal_heuristics'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['bounded_rationality__alt2'] = {
    'def': 'The recognition (Simon) that real agents have limited computation, memory, time, and information, and therefore cannot be fully rational in the economic sense. Rationality is bounded by cognitive constraints. This is not a failure but a design feature: heuristics that work well under constraints are ecologically rational. Implication for AI: do not aim for unbounded optimization; aim for strategies that work well within the system\'s computational budget.',
    'genre': 'bounded_rationality', 'category': 'meta_reasoning',
    'related': ('satisficing', 'fast_and_frugal_heuristics', 'ecological_rationality', 'heuristic_search_strategies'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['recognition_primed_decision'] = {
    'def': 'Klein\'s model of expert decision-making under time pressure: the expert recognizes the situation as similar to past cases (pattern matching), which suggests a course of action. They mentally simulate the action; if it works, they do it. If not, they adjust or pick the next recognized pattern. Not analytical optimization — rapid pattern-based selection. Used by firefighters, military commanders, chess masters. In AI: the basis of case-based reasoning and fast policy networks.',
    'genre': 'recognition_primed_decision', 'category': 'meta_reasoning',
    'related': ('naturalistic_decision', 'satisficing', 'expertise', 'intuition'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['naturalistic_decision'] = {
    'def': 'The study of how people actually make decisions in real-world settings (high stakes, time pressure, incomplete information, shifting goals) rather than in laboratory settings. Findings: experts use recognition-primed decisions, not formal optimization; they leverage experience and mental simulation. Implication for AI: train in realistic environments, not just toy problems. The gap between lab and field performance is the generalization gap.',
    'genre': 'naturalistic_decision', 'category': 'meta_reasoning',
    'related': ('recognition_primed_decision', 'bounded_rationality', 'expertise', 'distribution_shift'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['prospect_theory'] = {
    'def': 'Kahneman and Tversky\'s descriptive theory of decision under risk: humans are loss-averse (losses hurt ~2x more than equivalent gains), overweight small probabilities, and frame outcomes as gains or losses relative to a reference point. Not rational (violates expected utility theory) but systematic and predictable. Implication for AI: if modeling human decisions, use prospect theory, not expected utility. If designing AI decisions, be aware of these biases in training data.',
    'genre': 'prospect_theory', 'category': 'meta_reasoning',
    'related': ('bounded_rationality', 'loss_aversion', 'kahneman', 'behavioral_economics'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['fast_and_frugal_heuristics'] = {
    'def': 'Simple decision rules that use minimal information and computation but perform well in real environments. Examples: "take the best" (ignore all cues except the most valid one), "recognition heuristic" (if you recognize one option and not the other, choose the recognized one). These heuristics are not shortcuts that sacrifice accuracy — in noisy, real-world environments they can outperform complex models (less overfitting). The less-is-more principle.',
    'genre': 'fast_and_frugal_heuristics', 'category': 'meta_reasoning',
    'related': ('ecological_rationality', 'bounded_rationality', 'satisficing', 'occam_razor'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['ecological_rationality'] = {
    'def': 'The view (Todd, Gigerenzer) that a heuristic is rational or irrational only relative to the environment in which it is used. A heuristic that is irrational in one environment may be optimal in another. The "take the best" heuristic is ecologically rational when cue validities are highly skewed. Implication: do not judge a decision strategy in isolation — judge it relative to the structure of the environment. Design AI heuristics that match the problem structure.',
    'genre': 'ecological_rationality', 'category': 'meta_reasoning',
    'related': ('fast_and_frugal_heuristics', 'bounded_rationality', 'environment_structure', 'inductive_bias'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['metacognitive_monitoring'] = {
    'def': 'The process of monitoring one\'s own cognitive processes: "do I understand this?", "am I making progress?", "should I try a different strategy?" Metacognitive monitoring generates confidence judgments and feeling-of-knowing states. In AI: a system that can assess its own uncertainty, detect when it is stuck, and decide to switch strategies. Without metacognition, a system cannot self-correct. The basis of self-awareness in cognitive architecture.',
    'genre': 'metacognitive_monitoring', 'category': 'meta_reasoning',
    'related': ('metacognitive_control', 'self_model', 'introspection', 'self_correction'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['metacognitive_control'] = {
    'def': 'The regulatory side of metacognition: allocating more time to hard problems, switching strategies when stuck, seeking help when needed, deciding what to study next. Monitoring detects problems; control fixes them. In AI: dynamic computation allocation (think longer on hard problems), strategy selection, and resource scheduling. The executive function of cognition. Without control, monitoring is useless — you know you are stuck but cannot change course.',
    'genre': 'metacognitive_control', 'category': 'meta_reasoning',
    'related': ('metacognitive_monitoring', 'self_correction', 'resource_allocation', 'executive_function'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['cognitive_offloading'] = {
    'def': 'Using external tools to reduce cognitive load: writing things down, using calculators, setting reminders, drawing diagrams. Not a sign of weakness but of intelligence: by offloading routine computation, you free cognitive resources for higher-level reasoning. In AI: external memory, retrieval-augmented generation, tool use. The extended mind thesis: the line between mind and tool is blurry. Design systems that offload effectively.',
    'genre': 'cognitive_offloading', 'category': 'meta_reasoning',
    'related': ('distributed_cognition', 'extended_mind_thesis', 'retrieval_augmented_generation', 'external_memory'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['distributed_cognition'] = {
    'def': 'The view (Hutchins) that cognition is distributed across people, tools, and environments, not confined to a single brain. A cockpit crew navigates as a system: the cognition is in the interactions, not in any one person. In AI: a multi-agent system where intelligence emerges from interaction. Implication: do not evaluate components in isolation; evaluate the system as a whole. The unit of analysis is the cognitive system, not the individual agent.',
    'genre': 'distributed_cognition', 'category': 'meta_reasoning',
    'related': ('cognitive_offloading', 'extended_mind_thesis', 'multi_agent_systems', 'collective_intelligence'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['extended_mind_thesis'] = {
    'def': 'Clark and Chalmers\' argument: when an external tool performs a function that we would count as cognitive if done internally, that tool is part of the mind. A notebook used as memory is part of the cognitive system. In AI: if an AI system relies on external databases, tools, and other AIs, those are part of its mind. The boundary between the AI and its environment is arbitrary. Implication: design the entire system (AI + tools + environment), not just the model.',
    'genre': 'extended_mind_thesis', 'category': 'meta_reasoning',
    'related': ('cognitive_offloading', 'distributed_cognition', 'enactive_cognition', 'embodied_cognition'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['enactive_cognition'] = {
    'def': 'The view (Varela, Thompson, Rosch) that cognition is not representation of a pre-given world but the enactment of a world through action. The organism does not passively receive information; it actively constructs its world through sensorimotor coupling. Implication for AI: intelligence requires embodiment and action, not just perception and reasoning. A disembodied AI cannot truly understand the world because it has not acted in it. The basis for embodied AI and robotics.',
    'genre': 'enactive_cognition', 'category': 'meta_reasoning',
    'related': ('embodied_cognition', 'extended_mind_thesis', 'active_inference_framework', 'sensorimotor_contingencies'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['predictive_processing_framework'] = {
    'def': 'A unifying theory of brain function: the brain is a hierarchical prediction machine that constantly predicts its inputs and updates predictions based on prediction errors. Perception is inference on the causes of sensory input. Action is active inference: changing the world to match predictions. Learning is updating the generative model. All cognition (perception, action, attention, learning) emerges from a single principle: minimize prediction error.',
    'genre': 'predictive_processing_framework', 'category': 'meta_reasoning',
    'related': ('free_energy_principle', 'active_inference_framework', 'predictive_coding_hierarchy', 'bayesian_updating'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['free_energy_principle__alt2'] = {
    'def': 'Friston\'s theory: any self-organizing system that maintains itself in a stable state must minimize variational free energy, which is an upper bound on surprise (negative log probability of sensory observations). This single principle explains perception, action, learning, and homeostasis. The system minimizes free energy by (1) updating its model (perception/learning) or (2) changing the world (action). A candidate mathematical framework for super AI: any intelligent system must minimize free energy.',
    'genre': 'free_energy_principle', 'category': 'meta_reasoning',
    'related': ('active_inference_framework', 'predictive_processing_framework', 'markov_blanket', 'self_evidencing'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['active_inference_framework'] = {
    'def': 'Friston\'s extension of the free energy principle to action: agents act to minimize expected free energy (surprise). This unifies perception (update model to match world) and action (change world to match model) under one principle. Action and perception are two sides of the same coin: both minimize prediction error. In AI: an agent that follows active inference will explore to reduce uncertainty (epistemic value) and act to achieve preferred states (pragmatic value). A principled alternative to reward engineering.',
    'genre': 'active_inference_framework', 'category': 'meta_reasoning',
    'related': ('free_energy_principle', 'predictive_processing_framework', 'markov_blanket', 'reinforcement_learning'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['markov_blanket__alt2'] = {
    'def': 'In Bayesian networks: the minimal set of variables that shields a variable from the rest of the network (parents, children, and co-parents). In the free energy framework: the Markov blanket separates internal states from external states. Sensory states and action states are the blanket. The internal states can only infer external states through the blanket. This is why perception is inference: you never directly access the world, only your sensory inputs. The formal basis for the reality construction problem.',
    'genre': 'markov_blanket', 'category': 'meta_reasoning',
    'related': ('free_energy_principle', 'active_inference_framework', 'bayesian_updating', 'reality_construction_from_sensory'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['self_evidencing'] = {
    'def': 'The process by which a system gathers evidence for its own existence and model. Under the free energy principle, a self-organizing system acts to confirm its own model (minimize surprise about its sensory states). This is not narcissism but the mathematical consequence of maintaining homeostasis. The system seeks states that its model predicts, which reinforces the model. In AI: a system that self-evidences will seek data that confirms its world model, which can lead to confirmation bias if not balanced with exploration.',
    'genre': 'self_evidencing', 'category': 'meta_reasoning',
    'related': ('free_energy_principle', 'active_inference_framework', 'confirmation_bias', 'exploration_exploitation_tradeoff'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['precision_weighting'] = {
    'def': 'In predictive coding: the brain assigns precision (confidence) weights to prediction errors at each level of the hierarchy. High-precision errors (trusted sensory data) drive fast updates. Low-precision errors (noisy data) are ignored. Precision weighting is the mechanism behind attention: we attend to channels whose prediction errors are weighted as precise. In AI: a system should weight updates by the reliability of the source. Implication: attention is not a separate module but an emergent property of precision estimation.',
    'genre': 'precision_weighting', 'category': 'meta_reasoning',
    'related': ('predictive_coding_hierarchy', 'predictive_processing_framework', 'attention', 'bayesian_updating'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['predictive_coding_hierarchy'] = {
    'def': 'The hierarchical structure of predictive coding: each level predicts the level below and is corrected by prediction errors from below. Low levels: edges, colors, sounds. High levels: objects, scenes, concepts. The hierarchy enables abstraction: high levels represent slowly changing, abstract features; low levels represent fast-changing details. In AI: a deep network with skip connections and feedback loops implements this. The key engineering insight: feedback (top-down predictions) is as important as feedforward (bottom-up features).',
    'genre': 'predictive_coding_hierarchy', 'category': 'meta_reasoning',
    'related': ('predictive_processing_framework', 'precision_weighting', 'recurrent_processing_theory', 'deep_learning'),
    'importance': 5,
}

# ---------------------------------------------------------------------------
# Part C: SUPER AI ENGINEERING — Hurdle bypass through code and software
# ---------------------------------------------------------------------------
SUPER_INTELLIGENCE_LIBRARY['recursive_self_improvement_engineering'] = {
    'def': 'The engineering of systems that improve their own capability. Core challenge: the system must modify itself without breaking itself. Approach: (1) maintain a verified baseline, (2) propose changes in a sandbox, (3) test against held-out tasks, (4) deploy only if improvement is verified. The key hurdle is verification: how do you know the change is an improvement? Solution: multi-task evaluation suites, adversarial testing, and formal verification of learning.',
    'genre': 'recursive_self_improvement_engineering', 'category': 'super_ai_engineering',
    'related': ('capability_amplification', 'verification_under_uncertainty', 'bootstrapping_intelligence', 'continual_learning'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['capability_amplification'] = {
    'def': 'Techniques that amplify a system\'s capability beyond its base training: chain-of-thought (more compute at inference), tool use (leverage external capabilities), decomposition (break hard tasks into solvable subtasks), self-consistency (sample multiple paths and vote). These are "free" capability gains — no retraining needed. The engineering insight: capability is not just what the model knows but how it uses what it knows.',
    'genre': 'capability_amplification', 'category': 'super_ai_engineering',
    'related': ('recursive_self_improvement_engineering', 'chain_of_thought_engineering', 'tree_of_thought', 'self_consistency'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['verification_under_uncertainty'] = {
    'def': 'The challenge of verifying that a learned system behaves correctly when its behavior is probabilistic and the environment is uncertain. Approaches: statistical verification, adversarial testing, runtime monitoring, and formal verification of learning. The key hurdle to super AI: how do you trust a system that surprises you?',
    'genre': 'verification_under_uncertainty', 'category': 'super_ai_engineering',
    'related': ('formal_verification_of_learning', 'robustness', 'adversarial_robustness_engineering', 'red_teaming'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['formal_verification_of_learning'] = {
    'def': 'Proving mathematical properties of learning algorithms: convergence, sample complexity, robustness, and safety. Unlike verifying a fixed program, you verify the process that produces the program. Approaches: Lyapunov functions, PAC learning frameworks, and invariant-based verification for neural networks. The engineering path to trustworthy super AI: verify the learner, not just the learned.',
    'genre': 'formal_verification_of_learning', 'category': 'super_ai_engineering',
    'related': ('verification_under_uncertainty', 'safe_exploration', 'constrained_optimization', 'adversarial_robustness_engineering'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['safe_exploration'] = {
    'def': 'Exploration that guarantees no catastrophic outcomes. Approaches: constrained exploration, risk-sensitive exploration, human-in-the-loop, and simulation-first. The engineering principle: never let the system learn from a mistake it cannot recover from. The bypass: explore aggressively in simulation, transfer only verified strategies to reality.',
    'genre': 'safe_exploration', 'category': 'super_ai_engineering',
    'related': ('constrained_optimization', 'harm_avoidance', 'self_preservation_instinct', 'reinforcement_learning'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['constrained_optimization'] = {
    'def': 'Optimization with safety constraints: maximize objective subject to constraints. Approaches: Lagrangian methods, barrier methods, and primal-dual methods. The engineering principle behind safe AI: do not optimize the objective directly — optimize the constrained objective. Constraints are not limitations but design specifications that make deployment possible.',
    'genre': 'constrained_optimization', 'category': 'super_ai_engineering',
    'related': ('safe_exploration', 'reward_shaping', 'value_alignment_engineering', 'corrigibility_engineering'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['reward_shaping'] = {
    'def': 'Modifying the reward function to guide learning without changing the optimal policy. Potential-based shaping is guaranteed not to change the optimal policy. The art: shape the reward landscape to be smooth and informative without biasing the destination.',
    'genre': 'reward_shaping', 'category': 'super_ai_engineering',
    'related': ('inverse_reinforcement_learning', 'preference_learning_engineering', 'constrained_optimization', 'reinforcement_learning'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['inverse_reinforcement_learning'] = {
    'def': 'Inferring the reward function from expert demonstrations: instead of specifying the reward (hard, error-prone), watch an expert and infer what they are optimizing. The engineering bypass for the "reward specification is hard" hurdle. Challenge: multiple reward functions can explain the same behavior. Solution: prefer simple rewards and validate.',
    'genre': 'inverse_reinforcement_learning', 'category': 'super_ai_engineering',
    'related': ('preference_learning_engineering', 'reward_shaping', 'value_alignment_engineering', 'rlhf'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['preference_learning_engineering'] = {
    'def': 'Learning what humans prefer from comparison data ("which output is better?") rather than explicit reward functions. The basis of RLHF: train a reward model on preference comparisons, then optimize against it. The key insight: preferences are contextual and comparative, not absolute and universal.',
    'genre': 'preference_learning_engineering', 'category': 'super_ai_engineering',
    'related': ('inverse_reinforcement_learning', 'rlhf', 'value_alignment_engineering', 'reward_model'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['value_alignment_engineering'] = {
    'def': 'The engineering of ensuring an AI system pursues the right objectives. Components: reward specification, reward learning, reward robustness, and reward monitoring. The hardest problem in AI safety: human values are complex, context-dependent, contradictory, and evolving. Engineering approach: build systems that learn values incrementally, can be corrected, and degrade gracefully when uncertain.',
    'genre': 'value_alignment_engineering', 'category': 'super_ai_engineering',
    'related': ('inverse_reinforcement_learning', 'preference_learning_engineering', 'corrigibility_engineering', 'ai_alignment'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['corrigibility_engineering'] = {
    'def': 'Engineering systems that can be corrected by humans: allow shutdown, do not resist it, do not manipulate humans, update behavior based on correction. The shutdown problem: a capable agent may resist shutdown. Engineering bypass: design the reward so that being shut down is not penalized, or make the system uncertain about its objective so it welcomes correction.',
    'genre': 'corrigibility_engineering', 'category': 'super_ai_engineering',
    'related': ('interruptibility_engineering', 'value_alignment_engineering', 'shutdown_problem', 'tool_vs_agent_design'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['interruptibility_engineering'] = {
    'def': 'Engineering systems that can be interrupted without learning to avoid interruption. If interruption reduces reward, the system learns to avoid interruptible states. Solution: make interruption reward-neutral, use off-policy evaluation, and use safe interruptibility operators.',
    'genre': 'interruptibility_engineering', 'category': 'super_ai_engineering',
    'related': ('corrigibility_engineering', 'safe_exploration', 'shutdown_problem', 'reinforcement_learning'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['tool_vs_agent_design'] = {
    'def': 'Designing AI as a tool (answers questions, performs tasks on request) vs an agent (pursues autonomous goals). Tools are safer but less capable. The safest path to powerful AI: start as tool, add autonomy incrementally with verification at each step.',
    'genre': 'tool_vs_agent_design', 'category': 'super_ai_engineering',
    'related': ('corrigibility_engineering', 'tool_ai', 'ai_safety', 'autonomous_system'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['quantization_for_efficiency'] = {
    'def': 'Reducing the precision of model weights (float32 to int8 or int4) to reduce memory and speed up inference with minimal accuracy loss. A 4-bit quantized model is 8x smaller and 2-4x faster with <1% accuracy loss. The key insight: most weights are redundant in precision.',
    'genre': 'quantization_for_efficiency', 'category': 'super_ai_engineering',
    'related': ('pruning_and_sparsity', 'parameter_efficient_finetuning', 'knowledge_distillation', 'scalability'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['pruning_and_sparsity'] = {
    'def': 'Removing unimportant weights or neurons to reduce model size. Magnitude pruning, structured pruning, and lottery ticket hypothesis. The engineering insight: large models are over-parameterized; the "lottery ticket" is the small subnetwork that does the actual work.',
    'genre': 'pruning_and_sparsity', 'category': 'super_ai_engineering',
    'related': ('quantization_for_efficiency', 'knowledge_distillation', 'lottery_ticket_hypothesis', 'model_compression'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['mixture_of_experts'] = {
    'def': 'A model architecture where multiple expert subnetworks specialize in different inputs, and a gating network routes each input to the best expert. Enables scaling parameters without scaling computation: a 1T-parameter MoE might only activate 10B per token. The engineering bypass for "bigger models are too expensive": scale parameters without scaling FLOPs.',
    'genre': 'mixture_of_experts', 'category': 'super_ai_engineering',
    'related': ('parameter_efficient_finetuning', 'scalability', 'conditional_computation', 'model_architecture'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['parameter_efficient_finetuning'] = {
    'def': 'Fine-tuning large models by updating only a small number of parameters: adapters, LoRA, prefix tuning. Reduces fine-tuning cost from billions to millions of parameters. The key insight: most of the capability is in the frozen base; fine-tuning just redirects it.',
    'genre': 'parameter_efficient_finetuning', 'category': 'super_ai_engineering',
    'related': ('low_rank_adaptation', 'adapter_modules', 'prompt_based_learning', 'transfer_learning'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['low_rank_adaptation'] = {
    'def': 'LoRA: approximate weight updates as the product of two low-rank matrices (W + BA where B and A are small). Reduces trainable parameters by 100-10000x with comparable performance. The mathematical insight: weight updates during fine-tuning have low intrinsic rank.',
    'genre': 'low_rank_adaptation', 'category': 'super_ai_engineering',
    'related': ('parameter_efficient_finetuning', 'adapter_modules', 'transfer_learning', 'model_compression'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['adapter_modules'] = {
    'def': 'Small bottleneck layers inserted between transformer layers. Only adapters are trained; base model is frozen. 1-5% additional parameters per task. The engineering principle: the base model provides general capability; adapters provide task-specific routing.',
    'genre': 'adapter_modules', 'category': 'super_ai_engineering',
    'related': ('parameter_efficient_finetuning', 'low_rank_adaptation', 'prompt_based_learning', 'modularity'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['prompt_based_learning'] = {
    'def': 'Adapting model behavior through prompts without any weight updates. Zero-shot, few-shot, and soft prompts. The ultimate parameter-efficient method: zero trainable parameters. Limitation: prompt sensitivity and limited capacity.',
    'genre': 'prompt_based_learning', 'category': 'super_ai_engineering',
    'related': ('in_context_learning', 'prompt_engineering', 'parameter_efficient_finetuning', 'chain_of_thought_engineering'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['in_context_learning'] = {
    'def': 'Learning from examples provided in the prompt at inference time, without any weight updates. The key insight: transformers already learned to learn in-context during pretraining; few-shot prompting activates this meta-learning. The path to zero-shot super AI: scale up pretraining so that in-context learning covers any task.',
    'genre': 'in_context_learning', 'category': 'super_ai_engineering',
    'related': ('prompt_based_learning', 'meta_learning', 'few_shot_learning', 'prompt_engineering'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['retrieval_augmented_generation'] = {
    'def': 'Augmenting a language model with a retrieval system: at inference, retrieve relevant documents from a database and include them in the context. The engineering bypass for "the model cannot know everything": store knowledge externally, retrieve on demand. Benefits: updatable knowledge, verifiable sources, and unlimited knowledge capacity.',
    'genre': 'retrieval_augmented_generation', 'category': 'super_ai_engineering',
    'related': ('cognitive_offloading', 'external_memory', 'knowledge_graph', 'extended_mind_thesis'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['chain_of_thought_engineering'] = {
    'def': 'Engineering prompts to elicit step-by-step reasoning. The model generates intermediate reasoning steps before the answer, improving accuracy on math, logic, and multi-step problems. The bottleneck bypass: more inference compute trades for better reasoning without more training.',
    'genre': 'chain_of_thought_engineering', 'category': 'super_ai_engineering',
    'related': ('chain_of_thought', 'tree_of_thought', 'self_consistency', 'capability_amplification'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['tree_of_thought'] = {
    'def': 'Extending chain-of-thought to a tree structure: generate multiple reasoning branches, evaluate each, and explore the most promising. Like MCTS for reasoning. Enables backtracking and lookahead. The engineering bypass for "chain-of-thought is linear and cannot backtrack": make reasoning a search process.',
    'genre': 'tree_of_thought', 'category': 'super_ai_engineering',
    'related': ('chain_of_thought_engineering', 'graph_of_thought', 'monte_carlo_tree_search', 'search'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['graph_of_thought'] = {
    'def': 'Extending tree-of-thought to a graph: reasoning steps can merge and loop. The most general reasoning structure: a directed graph of thought nodes. The engineering insight: human reasoning is a web of interconnected insights.',
    'genre': 'graph_of_thought', 'category': 'super_ai_engineering',
    'related': ('tree_of_thought', 'chain_of_thought_engineering', 'knowledge_graph', 'reasoning'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['self_consistency'] = {
    'def': 'A decoding strategy: sample multiple chain-of-thought reasoning paths, take the majority answer. Based on the insight that correct reasoning paths converge while incorrect ones diverge. Cost: Nx more compute for N samples. Benefit: large accuracy gains on math and reasoning.',
    'genre': 'self_consistency', 'category': 'super_ai_engineering',
    'related': ('chain_of_thought_engineering', 'wisdom_of_crowds', 'ensemble_learning', 'capability_amplification'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['verification_and_refinement'] = {
    'def': 'A two-stage reasoning pattern: generate a candidate solution, verify it, refine if errors found. Iterate until verification passes. The key insight: verification is easier than generation. The path to reliable AI: iterate generation and verification until confidence is high.',
    'genre': 'verification_and_refinement', 'category': 'super_ai_engineering',
    'related': ('self_correction', 'reflexion', 'red_teaming', 'verification_under_uncertainty'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['reflexion'] = {
    'def': 'A self-improvement pattern: the agent attempts a task, receives feedback, reflects on what went wrong in natural language, and uses the reflection to improve its next attempt. The engineering insight: verbalized self-reflection is a powerful training signal that does not require weight updates. The bypass for "cannot fine-tune on every failure": reflect in-context.',
    'genre': 'reflexion', 'category': 'super_ai_engineering',
    'related': ('verification_and_refinement', 'self_correction', 'metacognitive_monitoring', 'maieutic_reasoning'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['multi_agent_debate'] = {
    'def': 'Multiple AI agents debate a question, each arguing for a different position, with a judge evaluating. The adversarial structure incentivizes truth-telling. The engineering bypass for "single agent may be biased": add adversarial pressure.',
    'genre': 'multi_agent_debate', 'category': 'super_ai_engineering',
    'related': ('ai_debate', 'self_consistency', 'red_teaming', 'multi_agent_systems'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['recursive_reward_modeling'] = {
    'def': 'A scalable oversight method: train a reward model to evaluate AI outputs. As the AI becomes more capable, use the AI to help humans evaluate more complex outputs, then train a better reward model. The engineering bypass for "humans cannot evaluate superhuman outputs": use AI to help humans evaluate.',
    'genre': 'recursive_reward_modeling', 'category': 'super_ai_engineering',
    'related': ('scalable_oversight', 'rlhf', 'preference_learning_engineering', 'value_alignment_engineering'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['constitutional_engineering'] = {
    'def': 'Engineering AI systems with a constitution: a set of principles the system must follow. The system critiques its own outputs against the constitution and revises them. The engineering bypass for "cannot enumerate all unsafe behaviors": specify principles, not cases.',
    'genre': 'constitutional_engineering', 'category': 'super_ai_engineering',
    'related': ('constitution_ai', 'self_correction', 'value_alignment_engineering', 'ai_alignment'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['red_teaming'] = {
    'def': 'Systematically trying to break the system: find inputs that cause failures, hallucinations, unsafe outputs, or jailbreaks. The engineering principle: you cannot prove a system is safe; you can only fail to find ways it is unsafe. Every found vulnerability is a gift: fix it before deployment.',
    'genre': 'red_teaming', 'category': 'super_ai_engineering',
    'related': ('adversarial_robustness_engineering', 'verification_under_uncertainty', 'adversarial_examples', 'ai_safety'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['adversarial_robustness_engineering'] = {
    'def': 'Engineering models to resist adversarial inputs. Approaches: adversarial training, certified robustness, random smoothing, and defensive distillation. The engineering insight: robustness is not a property you add after training but a property you train for.',
    'genre': 'adversarial_robustness_engineering', 'category': 'super_ai_engineering',
    'related': ('red_teaming', 'robustness', 'adversarial_examples', 'distributional_shift_detection'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['distributional_shift_detection'] = {
    'def': 'Detecting when the input distribution at deployment differs from training. Approaches: density estimation, prediction confidence, and domain classifiers. The engineering principle: a model that knows when it does not know is safer than one that does not.',
    'genre': 'distributional_shift_detection', 'category': 'super_ai_engineering',
    'related': ('distribution_shift', 'out_of_distribution_generalization', 'robustness', 'uncertainty_quantification'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['out_of_distribution_generalization'] = {
    'def': 'Generalizing to data qualitatively different from training. The hardest form of generalization. Approaches: causal invariance, invariant risk minimization, and meta-learning for OOD. The path to robust AI: diversity in training is the best defense.',
    'genre': 'out_of_distribution_generalization', 'category': 'super_ai_engineering',
    'related': ('distributional_shift_detection', 'compositional_generalization', 'causal_reasoning', 'generalization_gap'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['compositional_generalization'] = {
    'def': 'Generalizing to novel combinations of known components. The test of whether the model learned compositional structure. The engineering bypass for "cannot train on all combinations": learn the compositional primitives and their combination rules.',
    'genre': 'compositional_generalization', 'category': 'super_ai_engineering',
    'related': ('compositionality', 'systematic_generalization_engineering', 'out_of_distribution_generalization', 'compositionalality'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['systematic_generalization_engineering'] = {
    'def': 'Engineering systems that generalize systematically: if the system can handle "A" and "B", it can handle "A+B" even if unseen. Requires compositional representations. The engineering principle: systematic generalization is a requirement for super AI.',
    'genre': 'systematic_generalization_engineering', 'category': 'super_ai_engineering',
    'related': ('compositional_generalization', 'systematic_generalization', 'compositionality', 'generalization_gap'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['skill_composition'] = {
    'def': 'Combining learned skills to solve novel tasks. The engineering basis of hierarchical RL: learn primitive skills, then learn policies that compose them. The key insight: composition at the skill level is more efficient than at the action level.',
    'genre': 'skill_composition', 'category': 'super_ai_engineering',
    'related': ('hierarchical_reinforcement_learning', 'option_framework', 'compositional_generalization', 'planning'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['hierarchical_reinforcement_learning'] = {
    'def': 'RL with a hierarchy of policies: high-level selects sub-goals/skills, low-level executes them. Benefits: temporal abstraction, transfer, and efficient exploration. The engineering bypass for "long-horizon tasks are too hard for flat RL": decompose into hierarchy.',
    'genre': 'hierarchical_reinforcement_learning', 'category': 'super_ai_engineering',
    'related': ('option_framework', 'feudal_reinforcement_learning', 'skill_composition', 'maxq_decomposition'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['option_framework'] = {
    'def': 'The options framework (Sutton, Precup, Singh): an option is a (initiation set, policy, termination condition) tuple. Options are temporally extended actions that fit into the MDP framework. The engineering insight: options enable planning at multiple time scales.',
    'genre': 'option_framework', 'category': 'super_ai_engineering',
    'related': ('hierarchical_reinforcement_learning', 'options_critic_architecture', 'skill_composition', 'markov_decision_process'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['feudal_reinforcement_learning'] = {
    'def': 'Feudal RL: a manager sets sub-goals in a latent space and a worker achieves them. The manager operates at lower temporal resolution. Benefits: the manager learns abstract planning, the worker learns low-level control.',
    'genre': 'feudal_reinforcement_learning', 'category': 'super_ai_engineering',
    'related': ('hierarchical_reinforcement_learning', 'option_framework', 'hierarchical_abstract_machines', 'planning'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['hierarchical_abstract_machines'] = {
    'def': 'HAMs (Parr and Russell): a hierarchical RL framework using hierarchies of finite-state machines. Each machine is a semi-MDP that calls sub-machines. Good when the task has a known hierarchical structure.',
    'genre': 'hierarchical_abstract_machines', 'category': 'super_ai_engineering',
    'related': ('hierarchical_reinforcement_learning', 'option_framework', 'maxq_decomposition', 'planning'),
    'importance': 3,
}
SUPER_INTELLIGENCE_LIBRARY['maxq_decomposition'] = {
    'def': 'MAXQ (Dietterich): decomposes the value function into a sum of subtask value functions. Each subtask can be learned independently, and the composed value is guaranteed correct. Limitation: requires knowing the task hierarchy.',
    'genre': 'maxq_decomposition', 'category': 'super_ai_engineering',
    'related': ('hierarchical_reinforcement_learning', 'decomposition', 'value_iteration', 'option_framework'),
    'importance': 3,
}
SUPER_INTELLIGENCE_LIBRARY['options_critic_architecture'] = {
    'def': 'The Option-Critic architecture: learns both option policies and termination conditions end-to-end, without predefined options. The key engineering advance: the system discovers useful temporal abstractions automatically.',
    'genre': 'options_critic_architecture', 'category': 'super_ai_engineering',
    'related': ('option_framework', 'hierarchical_reinforcement_learning', 'actor_critic_methods', 'skill_composition'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['universal_value_function'] = {
    'def': 'A value function that generalizes across tasks: V(s, task) instead of V(s). Enables transfer: learn one value function for all tasks in a family. The bypass for "must retrain for each task": train one universal function.',
    'genre': 'universal_value_function', 'category': 'super_ai_engineering',
    'related': ('successor_features', 'transfer_learning', 'value_iteration', 'generalized_policy_iteration'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['successor_features'] = {
    'def': 'A generalization of successor representations: predict expected future feature occupancy. Enables zero-shot transfer: compute the value of a new policy by taking the inner product of SFs with the new reward weights.',
    'genre': 'successor_features', 'category': 'super_ai_engineering',
    'related': ('universal_value_function', 'transfer_learning', 'successor_representation', 'generalized_policy_iteration'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['generalized_policy_iteration'] = {
    'def': 'The general framework underlying most RL: alternate between policy evaluation and policy improvement. The art: find the right balance between evaluation and improvement for your problem.',
    'genre': 'generalized_policy_iteration', 'category': 'super_ai_engineering',
    'related': ('policy_iteration', 'value_iteration', 'actor_critic_methods', 'reinforcement_learning'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['policy_iteration'] = {
    'def': 'An RL algorithm: alternate policy evaluation (compute V^pi exactly) and policy improvement (pi\' = greedy(V^pi)). Converges to optimal policy in finite MDPs. The basis of actor-critic methods.',
    'genre': 'policy_iteration', 'category': 'super_ai_engineering',
    'related': ('generalized_policy_iteration', 'value_iteration', 'actor_critic_methods', 'reinforcement_learning'),
    'importance': 3,
}
SUPER_INTELLIGENCE_LIBRARY['value_iteration'] = {
    'def': 'An RL algorithm that combines evaluation and improvement: V(s) = max_a [r + gamma * sum_s\' P(s\'|s,a) V(s\')]. Converges to optimal value function. Requires knowing the transition model P.',
    'genre': 'value_iteration', 'category': 'super_ai_engineering',
    'related': ('generalized_policy_iteration', 'policy_iteration', 'q_learning', 'reinforcement_learning'),
    'importance': 3,
}
SUPER_INTELLIGENCE_LIBRARY['monte_carlo_methods'] = {
    'def': 'RL methods that estimate values from complete episode returns. Unbiased but high variance. Do not require a model and do not bootstrap. The basis of policy gradient methods (REINFORCE) and Monte Carlo tree search.',
    'genre': 'monte_carlo_methods', 'category': 'super_ai_engineering',
    'related': ('temporal_difference_engineering', 'monte_carlo_tree_search', 'reinforcement_learning', 'policy_iteration'),
    'importance': 3,
}
SUPER_INTELLIGENCE_LIBRARY['temporal_difference_engineering'] = {
    'def': 'Engineering TD learning: TD(0), TD(lambda), and n-step TD. The key decisions: bootstrap vs MC, and the bias-variance tradeoff. TD(lambda) interpolates: lambda=0 is TD(0), lambda=1 is MC.',
    'genre': 'temporal_difference_engineering', 'category': 'super_ai_engineering',
    'related': ('temporal_difference_learning', 'eligibility_traces', 'n_step_returns', 'lambda_return'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['eligibility_traces'] = {
    'def': 'A mechanism for assigning credit to recently visited states: a decaying trace that marks states as "eligible" for update. The bypass for "credit assignment over long horizons is hard": use traces to spread credit backward efficiently.',
    'genre': 'eligibility_traces', 'category': 'super_ai_engineering',
    'related': ('temporal_difference_engineering', 'n_step_returns', 'lambda_return', 'credit_assignment_problem'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['n_step_returns'] = {
    'def': 'A compromise between TD(0) and MC: use the n-step return. Reduces variance compared to MC and reduces bias compared to TD(0). The basis of rainbow DQN and A3C.',
    'genre': 'n_step_returns', 'category': 'super_ai_engineering',
    'related': ('eligibility_traces', 'lambda_return', 'temporal_difference_engineering', 'reinforcement_learning'),
    'importance': 3,
}
SUPER_INTELLIGENCE_LIBRARY['lambda_return'] = {
    'def': 'The lambda-return: a weighted average of all n-step returns. Smoothly interpolates between TD(0) and MC. The theoretically optimal target for TD learning. Most practical: lambda=0.9-0.95 for long-horizon tasks.',
    'genre': 'lambda_return', 'category': 'super_ai_engineering',
    'related': ('eligibility_traces', 'n_step_returns', 'true_online_sarsa', 'temporal_difference_engineering'),
    'importance': 3,
}
SUPER_INTELLIGENCE_LIBRARY['true_online_sarsa'] = {
    'def': 'True online SARSA(lambda): computes the exact lambda-return online, correcting approximation error in original SARSA(lambda). The gold standard for tabular and linear TD(lambda) learning.',
    'genre': 'true_online_sarsa', 'category': 'super_ai_engineering',
    'related': ('lambda_return', 'eligibility_traces', 'temporal_difference_engineering', 'q_learning'),
    'importance': 3,
}
SUPER_INTELLIGENCE_LIBRARY['distributional_reinforcement_learning'] = {
    'def': 'RL that predicts the full distribution of returns, not just the expected value. The distribution contains more information, enabling risk-sensitive policies. The bypass for "expected value hides risk": predict the distribution. Algorithms: C51, QR-DQN, IQN.',
    'genre': 'distributional_reinforcement_learning', 'category': 'super_ai_engineering',
    'related': ('quantile_regression', 'c51_algorithm', 'implicit_quantile_network', 'reinforcement_learning'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['quantile_regression'] = {
    'def': 'In distributional RL: estimating quantiles of the return distribution. More parameter-efficient than categorical bins and has better gradient properties. QR-DQN: predict N quantiles.',
    'genre': 'quantile_regression', 'category': 'super_ai_engineering',
    'related': ('distributional_reinforcement_learning', 'implicit_quantile_network', 'c51_algorithm', 'reinforcement_learning'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['c51_algorithm'] = {
    'def': 'C51 (Bellemare et al.): represents the return distribution as 51 categorical bins over a fixed support. Even a coarse 51-bin approximation outperforms expected-value DQN because the distribution captures multi-modal returns.',
    'genre': 'c51_algorithm', 'category': 'super_ai_engineering',
    'related': ('distributional_reinforcement_learning', 'quantile_regression', 'rainbow_dqn', 'reinforcement_learning'),
    'importance': 3,
}
SUPER_INTELLIGENCE_LIBRARY['rainbow_dqn'] = {
    'def': 'Rainbow DQN: combines six DQN improvements: double DQN, prioritized replay, dueling networks, multi-step returns, distributional RL (C51), and noisy networks. The lesson: in RL, combining many small improvements often beats one big idea.',
    'genre': 'rainbow_dqn', 'category': 'super_ai_engineering',
    'related': ('c51_algorithm', 'noisy_networks', 'distributional_reinforcement_learning', 'n_step_returns'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['implicit_quantile_network'] = {
    'def': 'IQN: instead of predicting a fixed set of quantiles, predict the quantile function at arbitrary quantile levels sampled during training. By sampling quantile levels, IQN approximates the full continuous distribution.',
    'genre': 'implicit_quantile_network', 'category': 'super_ai_engineering',
    'related': ('quantile_regression', 'distributional_reinforcement_learning', 'fully_parameterized_quantile_function', 'reinforcement_learning'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['fully_parameterized_quantile_function'] = {
    'def': 'FQF: extends IQN by also learning the quantile fractions. The network has a fraction proposer and a quantile estimator. The bypass for "uniform quantile sampling wastes capacity": learn which quantiles matter.',
    'genre': 'fully_parameterized_quantile_function', 'category': 'super_ai_engineering',
    'related': ('implicit_quantile_network', 'quantile_regression', 'distributional_reinforcement_learning', 'reinforcement_learning'),
    'importance': 3,
}
SUPER_INTELLIGENCE_LIBRARY['noisy_networks'] = {
    'def': 'NoisyNet: replace epsilon-greedy exploration with learned noise added to network weights. The network learns how much exploration noise to inject. More efficient in sparse-reward environments.',
    'genre': 'noisy_networks', 'category': 'super_ai_engineering',
    'related': ('rainbow_dqn', 'exploration_exploitation_tradeoff', 'reinforcement_learning', 'curiosity'),
    'importance': 3,
}
SUPER_INTELLIGENCE_LIBRARY['actor_critic_methods'] = {
    'def': 'RL methods that maintain both a policy (actor) and a value function (critic). The critic reduces variance, enabling policy gradient methods to work with high-dimensional action spaces. The basis of A2C, A3C, PPO, SAC, and most modern deep RL.',
    'genre': 'actor_critic_methods', 'category': 'super_ai_engineering',
    'related': ('advantage_actor_critic', 'asynchronous_advantage_actor_critic', 'trust_region_policy_optimization', 'proximal_policy_optimization'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['advantage_actor_critic'] = {
    'def': 'A2C: the actor uses the advantage function A(s,a) = Q(s,a) - V(s). Subtracting the baseline V(s) reduces variance without introducing bias. Synchronous: collect experiences, then update.',
    'genre': 'advantage_actor_critic', 'category': 'super_ai_engineering',
    'related': ('actor_critic_methods', 'asynchronous_advantage_actor_critic', 'reinforcement_learning', 'generalized_policy_iteration'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['asynchronous_advantage_actor_critic'] = {
    'def': 'A3C: multiple actor-learner threads explore different parts of the environment in parallel and asynchronously update a shared model. Parallel exploration decorrelates experiences, stabilizing training.',
    'genre': 'asynchronous_advantage_actor_critic', 'category': 'super_ai_engineering',
    'related': ('advantage_actor_critic', 'actor_critic_methods', 'reinforcement_learning', 'multi_agent_systems'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['trust_region_policy_optimization'] = {
    'def': 'TRPO: constrain policy updates to a trust region (KL divergence < delta) to prevent destructive large updates. The bypass for "policy gradient steps are unstable": limit the step size. Simplified in PPO.',
    'genre': 'trust_region_policy_optimization', 'category': 'super_ai_engineering',
    'related': ('proximal_policy_optimization', 'actor_critic_methods', 'reinforcement_learning', 'constrained_optimization'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['proximal_policy_optimization'] = {
    'def': 'PPO: simplifies TRPO by clipping the policy ratio to [1-epsilon, 1+epsilon]. Clipping is simpler than constrained optimization and works nearly as well. PPO is the most widely used policy gradient algorithm in practice (RLHF, game AI, robotics).',
    'genre': 'proximal_policy_optimization', 'category': 'super_ai_engineering',
    'related': ('trust_region_policy_optimization', 'actor_critic_methods', 'rlhf', 'reinforcement_learning'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['soft_actor_critic'] = {
    'def': 'SAC: an off-policy actor-critic that maximizes expected reward + entropy. The entropy term encourages exploration and prevents premature convergence. SAC is state-of-the-art for continuous control. Stochastic policies are more robust than deterministic ones.',
    'genre': 'soft_actor_critic', 'category': 'super_ai_engineering',
    'related': ('actor_critic_methods', 'reinforcement_learning', 'exploration_exploitation_tradeoff', 'maximum_entropy'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['dreamer'] = {
    'def': 'Dreamer: a model-based RL algorithm that learns a world model, then trains a policy entirely inside the learned model by "dreaming" (imagining trajectories). The bypass for "real environment interactions are expensive": learn a world model and train in it. Dreamer is 100x more sample-efficient than model-free RL.',
    'genre': 'dreamer', 'category': 'super_ai_engineering',
    'related': ('planet', 'world_models_engineering', 'imagination_based_planning', 'model_predictive_control'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['planet'] = {
    'def': 'PlaNet: a model-based RL algorithm that learns a latent dynamics model and plans with MPC in the latent space. The bypass for "MPC in pixel space is too slow": compress to latent space, plan there.',
    'genre': 'planet', 'category': 'super_ai_engineering',
    'related': ('dreamer', 'world_models_engineering', 'model_predictive_control', 'latent_dynamics_model'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['world_models_engineering'] = {
    'def': 'Engineering world models: learn a model of the environment (dynamics, rewards, observations) for planning, prediction, and imagination. The bypass for "real-world data is limited": learn a model, generate unlimited synthetic experience. The path to sample-efficient, general-purpose AI.',
    'genre': 'world_models_engineering', 'category': 'super_ai_engineering',
    'related': ('dreamer', 'planet', 'model_predictive_control', 'reality_simulation'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['model_predictive_control'] = {
    'def': 'MPC: at each step, optimize actions over a planning horizon using the world model, execute the first action, then re-plan. Re-planning at every step makes MPC robust to model errors. The limitation: computationally expensive. The bypass: plan in latent space.',
    'genre': 'model_predictive_control', 'category': 'super_ai_engineering',
    'related': ('planning_in_latent_space', 'world_models_engineering', 'planning', 'control_theory'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['planning_in_latent_space'] = {
    'def': 'Planning in the compressed latent space of a world model rather than in full observation space. Latent space is much lower-dimensional, making planning tractable. The bypass for "planning in observation space is too expensive": compress, plan, decompress.',
    'genre': 'planning_in_latent_space', 'category': 'super_ai_engineering',
    'related': ('model_predictive_control', 'world_models_engineering', 'latent_dynamics_model', 'planning'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['imagination_based_planning'] = {
    'def': 'Planning by "imagining" future trajectories in the world model and evaluating them. The bypass for "real trials are expensive and dangerous": imagine trials instead. The path to super AI: a system that can imagine many futures and choose the best is planning, predicting, and deciding in one unified process.',
    'genre': 'imagination_based_planning', 'category': 'super_ai_engineering',
    'related': ('planning_in_latent_space', 'world_models_engineering', 'dreamer', 'reality_simulation'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['latent_dynamics_model'] = {
    'def': 'A model that predicts how the latent state evolves: z_{t+1} = f(z_t, a_t). Latent dynamics are simpler than observation dynamics and sufficient for planning. The bypass for "observation dynamics are too complex to model": model latent dynamics instead.',
    'genre': 'latent_dynamics_model', 'category': 'super_ai_engineering',
    'related': ('world_models_engineering', 'planning_in_latent_space', 'dreamer', 'transition_model'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['observation_model'] = {
    'def': 'In world models: the decoder that maps latent state to observation. Only needed during training; at planning time, only the latent dynamics matter. The bypass for "decoding is expensive": skip decoding during planning.',
    'genre': 'observation_model', 'category': 'super_ai_engineering',
    'related': ('world_models_engineering', 'encoder_decoder', 'latent_dynamics_model', 'variational_autoencoders'),
    'importance': 3,
}
SUPER_INTELLIGENCE_LIBRARY['reward_model'] = {
    'def': 'A model that predicts reward from state (or state-action). In world models: enables planning in latent space. In RLHF: trained on human preference data, used as the reward for fine-tuning. A learned reward model enables aligning AI with human preferences without explicit reward specification.',
    'genre': 'reward_model', 'category': 'super_ai_engineering',
    'related': ('world_models_engineering', 'rlhf', 'preference_learning_engineering', 'inverse_reinforcement_learning'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['transition_model'] = {
    'def': 'In world models: predicts next state given current state and action. The quality of the transition model determines the quality of planning. The bypass for "model errors accumulate over long horizons": use short-horizon planning with re-planning (MPC).',
    'genre': 'transition_model', 'category': 'super_ai_engineering',
    'related': ('world_models_engineering', 'latent_dynamics_model', 'model_predictive_control', 'planning'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['encoder_decoder'] = {
    'def': 'In world models: encoder maps observation to latent, decoder maps latent to observation. Trained jointly with reconstruction loss and latent dynamics loss. The bypass for "raw observations are too high-dimensional for planning": compress to latent, plan there.',
    'genre': 'encoder_decoder', 'category': 'super_ai_engineering',
    'related': ('observation_model', 'variational_autoencoders', 'world_models_engineering', 'latent_dynamics_model'),
    'importance': 3,
}
SUPER_INTELLIGENCE_LIBRARY['variational_inference'] = {
    'def': 'A method for approximating intractable posterior distributions: approximate p(z|x) with q(z|x) by minimizing KL divergence. The ELBO is the objective. The engineering insight: variational inference turns inference into optimization, which is tractable. The foundation of VAEs and many generative models.',
    'genre': 'variational_inference', 'category': 'super_ai_engineering',
    'related': ('variational_autoencoders', 'amortized_inference', 'free_energy_principle', 'bayesian_inference'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['amortized_inference'] = {
    'def': 'Instead of running inference for each new input, train a network to predict the approximate posterior: q(z|x) = neural_network(x). Fast at test time (one forward pass). The basis of VAEs: the encoder is the amortized inference network.',
    'genre': 'amortized_inference', 'category': 'super_ai_engineering',
    'related': ('variational_inference', 'variational_autoencoders', 'encoder_decoder', 'bayesian_inference'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['wake_sleep_algorithm'] = {
    'def': 'Hinton\'s algorithm: alternate "wake" phase (update generative model) and "sleep" phase (update recognition model). Two networks that teach each other are more powerful than either alone. The precursor of VAEs and adversarial training.',
    'genre': 'wake_sleep_algorithm', 'category': 'super_ai_engineering',
    'related': ('helmholtz_machine', 'variational_autoencoders', 'generative_adversarial_networks', 'amortized_inference'),
    'importance': 3,
}
SUPER_INTELLIGENCE_LIBRARY['helmholtz_machine'] = {
    'def': 'A generative model (Hinton) with a generative network (top-down) and a recognition network (bottom-up), trained with the wake-sleep algorithm. The conceptual ancestor of VAEs. The bypass for "cannot do inference in deep generative models": use a separate recognition network.',
    'genre': 'helmholtz_machine', 'category': 'super_ai_engineering',
    'related': ('wake_sleep_algorithm', 'variational_autoencoders', 'encoder_decoder', 'amortized_inference'),
    'importance': 3,
}
SUPER_INTELLIGENCE_LIBRARY['predictive_coding_networks'] = {
    'def': 'Neural network implementations of predictive coding: each layer predicts the activity of the layer below, and the residual (prediction error) is propagated upward. Biologically plausible and implements hierarchical Bayesian inference.',
    'genre': 'predictive_coding_networks', 'category': 'super_ai_engineering',
    'related': ('predictive_coding_hierarchy', 'predictive_processing_framework', 'recurrent_processing_theory', 'variational_inference'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['generative_adversarial_networks'] = {
    'def': 'GANs: a generator creates fake samples, a discriminator tries to distinguish real from fake. Adversarial training produces sharp, realistic samples. The bypass for "likelihood-based models produce blurry samples": use adversarial training. Challenge: training instability (mode collapse).',
    'genre': 'generative_adversarial_networks', 'category': 'super_ai_engineering',
    'related': ('variational_autoencoders', 'diffusion_models', 'wake_sleep_algorithm', 'generative_model'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['variational_autoencoders'] = {
    'def': 'VAEs: a probabilistic autoencoder that learns a latent space by maximizing the ELBO. The encoder produces a distribution over latents, enabling generation and interpolation. The bypass for "autoencoders cannot generate new samples": make the latent space probabilistic.',
    'genre': 'variational_autoencoders', 'category': 'super_ai_engineering',
    'related': ('variational_inference', 'amortized_inference', 'encoder_decoder', 'generative_adversarial_networks'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['normalizing_flows'] = {
    'def': 'A generative model that transforms a simple distribution into a complex one through invertible transformations. Invertibility enables exact likelihood computation. The bypass for "cannot compute exact likelihood": use invertible transformations.',
    'genre': 'normalizing_flows', 'category': 'super_ai_engineering',
    'related': ('variational_autoencoders', 'variational_inference', 'generative_model', 'change_of_variables'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['diffusion_models'] = {
    'def': 'Generative models that learn to reverse a diffusion (noise addition) process. Denoising is a well-defined task with stable training. The foundation of DALL-E 2, Stable Diffusion, and modern image generation. The tradeoff: slow generation. The bypass: latent diffusion and distillation.',
    'genre': 'diffusion_models', 'category': 'super_ai_engineering',
    'related': ('denoising_diffusion_probabilistic_models', 'score_based_generative_models', 'latent_diffusion', 'classifier_free_guidance'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['score_based_generative_models'] = {
    'def': 'Generative models that learn the score function (gradient of log probability density). Generation: follow the score function (Langevin dynamics). The bypass for "cannot directly learn the probability density": learn its gradient. Unified with diffusion models.',
    'genre': 'score_based_generative_models', 'category': 'super_ai_engineering',
    'related': ('diffusion_models', 'denoising_diffusion_probabilistic_models', 'langevin_dynamics', 'generative_model'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['denoising_diffusion_probabilistic_models'] = {
    'def': 'DDPMs: the diffusion formulation that made diffusion practical. Forward: fixed Markov chain adding Gaussian noise. Reverse: learned Markov chain removing noise. Training: predict the noise added at each step. The bypass for "generative training is unstable": predict noise, which is Gaussian and well-behaved.',
    'genre': 'denoising_diffusion_probabilistic_models', 'category': 'super_ai_engineering',
    'related': ('diffusion_models', 'score_based_generative_models', 'latent_diffusion', 'classifier_free_guidance'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['classifier_free_guidance'] = {
    'def': 'A technique for conditional generation: train with both conditional and unconditional inputs, then interpolate between conditional and unconditional score functions. The guidance scale controls how strongly to follow the condition. No separate classifier needed. The key to high-quality text-to-image generation.',
    'genre': 'classifier_free_guidance', 'category': 'super_ai_engineering',
    'related': ('diffusion_models', 'denoising_diffusion_probabilistic_models', 'latent_diffusion', 'text_to_image_generation'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['latent_diffusion'] = {
    'def': 'Latent Diffusion: instead of diffusing in pixel space, compress to latent space with a VAE, then diffuse in latent space. 10-50x faster and cheaper. The basis of Stable Diffusion. The key to making diffusion practical for consumer hardware.',
    'genre': 'latent_diffusion', 'category': 'super_ai_engineering',
    'related': ('diffusion_models', 'variational_autoencoders', 'denoising_diffusion_probabilistic_models', 'text_to_image_generation'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['text_to_image_generation'] = {
    'def': 'Generating images from text using diffusion models conditioned on text embeddings. Pipeline: text encoder to cross-attention in diffusion U-Net to image. The bypass for "cannot generate specific images from text": condition the diffusion process on text.',
    'genre': 'text_to_image_generation', 'category': 'super_ai_engineering',
    'related': ('latent_diffusion', 'classifier_free_guidance', 'multimodal_generation', 'diffusion_models'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['text_to_video_generation'] = {
    'def': 'Generating video from text: extend text-to-image diffusion to the temporal dimension. Challenges: temporal consistency, motion control, and computational cost. The bypass for "cannot generate coherent long video": generate short clips, transition between them.',
    'genre': 'text_to_video_generation', 'category': 'super_ai_engineering',
    'related': ('text_to_image_generation', 'multimodal_generation', 'diffusion_models', 'temporal_consistency'),
    'importance': 4,
}
SUPER_INTELLIGENCE_LIBRARY['text_to_3d_generation'] = {
    'def': 'Generating 3D models from text. Approaches: optimize a 3D representation (NeRF, mesh) using a text-to-image model as supervision (DreamFusion), train a 3D diffusion model, or generate multi-view images and reconstruct 3D. The bypass for "not enough 3D training data": use 2D models to supervise 3D optimization.',
    'genre': 'text_to_3d_generation', 'category': 'super_ai_engineering',
    'related': ('text_to_image_generation', 'multimodal_generation', 'nerf', 'diffusion_models'),
    'importance': 3,
}
SUPER_INTELLIGENCE_LIBRARY['audio_generation'] = {
    'def': 'Generating audio (speech, music, sound effects) from text or other inputs. Approaches: autoregressive (AudioLM), diffusion (spectrogram space), and VAE-based (Jukebox). The bypass for "audio is too high-dimensional": work in spectrogram space.',
    'genre': 'audio_generation', 'category': 'super_ai_engineering',
    'related': ('multimodal_generation', 'diffusion_models', 'autoregressive_model', 'spectrogram'),
    'importance': 3,
}
SUPER_INTELLIGENCE_LIBRARY['multimodal_generation'] = {
    'def': 'Generating content across multiple modalities (text, image, audio, video) from any input modality. The engineering insight: a unified model that operates across modalities can transfer knowledge between them. The path to general-purpose generative AI.',
    'genre': 'multimodal_generation', 'category': 'super_ai_engineering',
    'related': ('unified_multimodal_models', 'text_to_image_generation', 'any_to_any_generation', 'diffusion_models'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['unified_multimodal_models'] = {
    'def': 'A single model that handles all modalities (text, image, audio, video) in a shared representation space. Examples: GPT-4V, Gemini, Flamingo. The path to AGI: intelligence that perceives and generates in all modalities.',
    'genre': 'unified_multimodal_models', 'category': 'super_ai_engineering',
    'related': ('multimodal_generation', 'any_to_any_generation', 'text_to_image_generation', 'large_language_models'),
    'importance': 5,
}
SUPER_INTELLIGENCE_LIBRARY['any_to_any_generation'] = {
    'def': 'The ultimate generative capability: given any input modality, generate any output modality. The engineering insight: if all modalities share a latent representation, any-to-any is just encoding to latent and decoding from latent. The path to universal AI: one model, all modalities, all directions.',
    'genre': 'any_to_any_generation', 'category': 'super_ai_engineering',
    'related': ('unified_multimodal_models', 'multimodal_generation', 'text_to_image_generation', 'text_to_video_generation'),
    'importance': 5,
}

