                    pp["esp32_csi_method"] = _csi._method
                    pp["esp32_csi_n_subcarriers"] = _csi._n_subcarriers
                    if _csi.ok:
                        _lat = _csi.get_latest()
                        pp["esp32_csi_latest"] = _lat
