    def _gather_receptions(self):
        try:
            h = getattr(self.fuser, "history", None)
            if h is None or len(h) < 8:
                return None
            X = np.asarray(list(h)[-200:], dtype=float).T   # (subcarriers, time)
            if X.ndim == 2 and X.shape[0] >= 2 and X.shape[1] >= 8:
                return X
        except Exception:
            pass
