def _nepa_memoize_verifies(_ns):
    """PERFORMANCE FIX (v300++++): the capability engines' verify() methods are deterministic
    STATIC benchmarks (range res, speedups, voxel counts…). UnifiedRealityReport.build() runs
    every frame and calls their status()→verify(), which measured ~5.2 s/frame (≈0.2 fps cap).
    Memoize verify() per instance — compute once, cache forever (results never change), so the
    per-frame readout reads cached values. Parameterised calls are NOT cached; fresh instances
    (the self-test creates new ones each cycle) recompute, so re-verification stays genuine."""
    import functools
    for _cn in ("SubResolutionLocalizer", "ClarityEnhancementStack", "SpectralClarityMapper",
                "AccuracyMaximizer", "SpectralPointCloudRenderer", "DenseFieldRenderer",
                "PhotorealisticSurfaceRenderer", "ProceduralTextureSynthesizer",
                "VolumetricDetailRenderer", "CorrelationBottleneckSolver", "ParallelCorrelationEngine",
                "SpectrumCorrelationOrganizer", "CompoundInformationGain", "HighOrderCorrelationOrganizer",
                "TheoreticalLimitAnalyzer", "TemporalCoherenceEngine", "MotionFlowRenderer",
                "PBRMaterialRenderer", "ThoughtFrequencyCorrelator",
                "SpectrumAsLightRenderer", "FrequencyAudioEngine", "SpectrumLightPainter",
                "RenderInferenceRetester", "MultiFrameSuperResolution", "CLEANDeconvolver",
                "CompoundPipelineBenchmark", "SensoryOrganizationHierarchy", "SensoryHypercube",
                "SuperVisionComparator", "CorrelationEigenModes", "MultiLayerCorrelationEngine",
                "PerceptualSceneOrganizer", "PerceptualObjectTracker", "CumulativeImprovementEstimator",
                "GeoReferenceManager", "PropagationModeler", "TotalSpectrumSightEngine",
                "DigitalResonanceTwin", "GlobalInstrumentOrchestrator", "ThreatDetectionEngine",
                "EthicalPrivacyLayer", "ForensicTimelineReplay", "LifeFormAnimator",
                "GlobalScanOrchestrator", "SceneExporter", "LongTermSpectralMemory",
                "PatternOfLifeAnalyzer", "PredictiveCausalReasoner", "ThreatNarrativeGenerator",
                "EvidencePackageBuilder", "AdversarialRobustnessSuite", "SafetyPolicyEngine",
                "BehavioralStateTranslator", "ConsentMindGate", "AdaptiveFidelityController",
                "CrossSessionTwinMerger", "UncertaintyPropagationEngine", "SelfCalibrationEngine",
                "MultiUserSessionManager", "PolicyComplianceAuditor", "SimulationToRealityBridge",
                "HumanAICollaborationInterface", "EnergyAwareScanningScheduler", "VersionedSchemaMigrator",
                "SparseVoxelOctree", "ExtremeCompressionPipeline", "DeltaWorldHistory",
                "InMemoryComputeCache", "ActiveSensingOptimizer", "CollectiveBehaviorSimulator",
                "BiasFairnessAuditor", "ByzantineFaultTolerantFusion", "PredictivePrefetchEngine",
                "HotpathAccelerator", "NeuralSignatureExtractor", "NeuralSignalDecoder",
                "MindDecoderModel", "MindContentRenderer", "LiveMindOverlayRenderer",
                "MindReadingProvenanceTracker", "EthicsMindGate", "GlobalNeuralMeshCoordinator",
                "PersistentWorldStateManager", "EEGConstrainedSpeechDecoder",
                "DecoherenceReverseEngineeringEngine", "ParallelRefinedSensingEngine",
                "Goal4ReverseEngineeredSight", "DigitalHoneProbe", "BeyondHorizonRelaySight",
                "BeyondHorizonMaxExtentRenderer", "BeyondHorizonReachMultiplier",
                "MaxVisionReachAmplifier", "AbsoluteMaxVisionCeiling",
                "RealInformationHorizonMaximizer"):
        _cls = _ns.get(_cn)
        if _cls is None or not hasattr(_cls, "verify"):
            continue
        _orig = _cls.verify
        if getattr(_orig, "_nepa_memoized", False):
            continue

        def _make(orig):
            @functools.wraps(orig)
            def _wrapped(self, *a, **k):
                if a or k:
                    return orig(self, *a, **k)
                c = self.__dict__.get("_verify_cache")
                if c is not None:
                    return c
                c = orig(self, *a, **k)
                try:
                    self.__dict__["_verify_cache"] = c
                except Exception:
                    pass
                return c
            _wrapped._nepa_memoized = True
            return _wrapped
        _cls.verify = _make(_orig)


_nepa_memoize_verifies(globals())


